INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C62','kor',4,2,'u4',4,'이야기 속 낱말 — 추궁(잘못한 일에 대하여 엄하게 따져서 밝힘) · 기세등등하다(기세가 매우 높고 힘차다) · 교정하다(가르쳐서 바르게 하다) · 경청하다(귀를 기울여 듣다) — 문맥으로 짐작',ARRAY['[4국05-03][4국05-05]']::text[],62) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
