INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C64','kor',4,2,'u4',9,'「약, 잘 쓰고 잘 버리는 방법」 내용 — 폐의약품 수거함 · 소비 기한과 상자·설명서 보관 · 처방대로 바로 먹기 · 버린 약의 환경 오염 · 항생제와 내성균',ARRAY['[4국02-03]']::text[],64) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C65','kor',4,2,'u4',9,'설명하는 글 속 낱말 — 처방 · 개봉 · 터득 · 수거(낱말 퍼즐 — 가로세로로만, 문장 속 쓰임으로 뜻 찾기)',ARRAY['[4국02-03]']::text[],65) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C66','kor',4,2,'u4',11,'「저작권을 왜 지켜야 하나요?」 내용 — 저작권의 뜻 · 창작자의 시간과 노력 보호 · 지키지 않으면 문화 수준·산업이 낮아짐 · 허락 받기·출처·실수는 바로 인정',ARRAY['[4국02-03]']::text[],66) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C67','kor',4,2,'u4',11,'의견을 제시하는 글 속 낱말 — 창작(예술 작품을 독창적으로 지어냄) · 발전(더 낫고 좋은 상태나 더 높은 단계로 나아감) · 침해(침범해 해를 끼침)',ARRAY['[4국02-03]']::text[],67) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C68','kor',4,2,'u4',13,'시 「마음먹기」의 내용 — 동생과 사이좋게·엄마에게 대들지 말기·숙제 끝내고 게임 — 꾹꾹 먹은 마음이 꺼지는 배처럼 사라져 마음도 밥처럼 매일 먹어야 함',ARRAY['[4국05-03][4국05-05]']::text[],68) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X01','kor',4,'u4',ARRAY['K4-2-u4-C1']::text[],'이 단원에서 배울 내용을 책을 빨리 많이 읽는 법이나 단원과 상관없는 것으로 여긴다','느낌 나누기 · 되돌아보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X02','kor',4,'u4',ARRAY['K4-2-u4-C2']::text[],'끝까지·빨리·여러 번 읽기만 하면 잘 읽은 것이라고 여기고 읽는 동안 한 일은 살피지 않는다','읽는 동안 무엇을 했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X03','kor',4,'u4',ARRAY['K4-2-u4-C3']::text[],'책 무게나 표지 색처럼 읽기와 상관없는 불편을 읽기의 어려움으로 고른다','읽었는데 잘 모르겠다?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X04','kor',4,'u4',ARRAY['K4-2-u4-C4']::text[],'질문은 남에게만 하는 것이라 여기거나 읽기를 점검하는 일과 상관없다고 여긴다','스스로 묻고 점검해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X05','kor',4,'u4',ARRAY['K4-2-u4-C5','K4-2-u4-C32','K4-2-u4-C48']::text[],'글의 종류와 그 글에 어울리는 질문을 엇갈리게 짝짓는다','무엇을 하려고 쓴 글?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X06','kor',4,'u4',ARRAY['K4-2-u4-C6','K4-2-u4-C53']::text[],'질문을 많이 만들수록 잘 읽은 것이라고 여긴다','개수보다 쓸모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X07','kor',4,'u4',ARRAY['K4-2-u4-C6','K4-2-u4-C33']::text[],'읽기 전·중·후 활동을 언제나 빠짐없이 다 해야 잘 읽은 것이라고 여긴다','그때그때 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X08','kor',4,'u4',ARRAY['K4-2-u4-C7','K4-2-u4-C9']::text[],'같은 시에서는 떠오르는 장면이 하나로 정해져 있고, 다른 장면은 잘못 읽은 것이라고 여긴다','채워 넣을 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X09','kor',4,'u4',ARRAY['K4-2-u4-C8']::text[],'시에서 늘인 낱말 속에 들리는 것을 엇갈리게 읽는다','소리 내어 늘여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X10','kor',4,'u4',ARRAY['K4-2-u4-C10']::text[],'가장 많이 나온 느낌으로 반의 느낌이나 시의 느낌을 정한다','수로 정하지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X11','kor',4,'u4',ARRAY['K4-2-u4-C10','K4-2-u4-C13']::text[],'친구가 먼저 말한 느낌이나 고른 방법을 그대로 따라 한다','내 느낌을 말해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X12','kor',4,'u4',ARRAY['K4-2-u4-C11','K4-2-u4-C51']::text[],'나와 다른 느낌이나 방법을 들으면 틀렸다고 말한다','다를 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X13','kor',4,'u4',ARRAY['K4-2-u4-C11']::text[],'다른 느낌을 들으면 내 느낌을 그쪽으로 바꾸어야 한다고 여긴다','까닭을 물어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X14','kor',4,'u4',ARRAY['K4-2-u4-C10']::text[],'느낌은 정답이 없으니 까닭 없이 아무렇게나 말해도 된다고 여긴다','까닭을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X15','kor',4,'u4',ARRAY['K4-2-u4-C12']::text[],'늘였을 때 남는 소리가 낱말이 아닌데도 숨은 낱말이 있다고 고르거나 늘이는 자리를 엇갈린다','남는 소리가 낱말?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X16','kor',4,'u4',ARRAY['K4-2-u4-C13']::text[],'느낌을 나눈 뒤에는 모두 같은 느낌이 되어야 한다고 여긴다','넓게 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X17','kor',4,'u4',ARRAY['K4-2-u4-C14','K4-2-u4-C15']::text[],'인물이 겉으로 한 말만 보고 속마음을 놓쳐 이야기 내용을 잘못 안다(형준이는 소품이 좋아서)','손을 왜 내렸나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X20','kor',4,'u4',ARRAY['K4-2-u4-C14','K4-2-u4-C18']::text[],'인물의 성격을 말과 행동이 아니라 이름·겉모습·한 장면만 보고 정한다','말과 행동을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X22','kor',4,'u4',ARRAY['K4-2-u4-C19']::text[],'인물의 말과 행동에 어울리지 않는 말투를 고른다(형준 — 크고 빠르게·거칠게)','말끝이 흐려져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X23','kor',4,'u4',ARRAY['K4-2-u4-C20']::text[],'역할놀이로 나타낼 장면에는 정답이 하나 있다고 여기거나 까닭 없이 고른다','까닭만 있으면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X24','kor',4,'u4',ARRAY['K4-2-u4-C22']::text[],'가장 웃긴 역할놀이가 가장 잘한 역할놀이라고 여긴다','웃기기 대회 ✗') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X25','kor',4,'u4',ARRAY['K4-2-u4-C22']::text[],'목소리가 클수록 잘한 역할놀이라고 여긴다','마음이 드러났나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X26','kor',4,'u4',ARRAY['K4-2-u4-C21']::text[],'역할놀이 차례를 엇갈리게 알거나 다른 모둠 차례에 끼어든다','정하기 → 나누기 → 연습 → 해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X28','kor',4,'u4',ARRAY['K4-2-u4-C23','K4-2-u4-C52']::text[],'작품이나 읽기와 상관없는 것(나이·옷 색·날짜)을 묻는 질문을 만든다','읽은 것을 묻나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X29','kor',4,'u4',ARRAY['K4-2-u4-C25']::text[],'이야기 속 다툼에서 한 사람만 잘못했다고 여긴다','둘 다 한 가지씩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X30','kor',4,'u4',ARRAY['K4-2-u4-C26','K4-2-u4-C27','K4-2-u4-C28','K4-2-u4-C29']::text[],'읽기 전·중·후와 그 단계에서 하는 일을 엇갈리게 짝짓는다','펴기 전 · 읽는 동안 · 다 읽고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X31','kor',4,'u4',ARRAY['K4-2-u4-C30']::text[],'읽기 전 질문으로 끝까지 읽어야 답할 수 있는 질문을 고르거나, 읽기 후 질문을 제목만으로 답할 수 있다고 여긴다','지금 답할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X32','kor',4,'u4',ARRAY['K4-2-u4-C30','K4-2-u4-C52']::text[],'도서관 위치·글의 줄 수처럼 읽기와 상관없는 질문을 읽기 과정 질문으로 고른다','내 읽기가 드러나나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X34','kor',4,'u4',ARRAY['K4-2-u4-C34']::text[],'설명하는 글을 느낌을 적은 글이나 일기, 시키는 글로 여긴다','알기 쉽게 알려 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X35','kor',4,'u4',ARRAY['K4-2-u4-C35']::text[],'설명하는 글에서 읽은 내용을 글과 다르게 안다','그 줄을 다시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X37','kor',4,'u4',ARRAY['K4-2-u4-C37']::text[],'첫 문장이나 긴 문장, 곁가지 문장을 중심 문장으로 고른다','없으면 뜻이 안 통하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X38','kor',4,'u4',ARRAY['K4-2-u4-C38']::text[],'글에 나온 문장을 모두 옮겨 적는 것을 간추리기라고 여긴다','짧게 정리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X39','kor',4,'u4',ARRAY['K4-2-u4-C38']::text[],'가장 재미있었던 부분만 적는 것을 간추리기라고 여긴다','중심 문장을 모아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X40','kor',4,'u4',ARRAY['K4-2-u4-C39','K4-2-u4-C49']::text[],'점검표나 자기 점검을 잘 보이려고 모두 「예」가 되게 표시한다','나를 위해 솔직하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X41','kor',4,'u4',ARRAY['K4-2-u4-C49']::text[],'점검표는 빨리 채우는 것이 가장 중요하다고 여긴다','다시 읽을 곳 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X42','kor',4,'u4',ARRAY['K4-2-u4-C41']::text[],'의견을 제시하는 글을 읽는 사람이 반드시 따라야 하는 글이나 겪은 일을 적은 글로 여긴다','글쓴이의 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X43','kor',4,'u4',ARRAY['K4-2-u4-C42']::text[],'제목만 보고 이유가 몇 개인지나 글쓴이가 누구인지까지 알 수 있다고 여긴다','제목엔 의견만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X44','kor',4,'u4',ARRAY['K4-2-u4-C43']::text[],'글쓴이의 의견을 인사·문제 상황·실천 권유와 헷갈린다','~라고 생각합니다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X45','kor',4,'u4',ARRAY['K4-2-u4-C44']::text[],'문제 상황이나 실천을 권하는 말을 의견을 받치는 이유로 고른다','첫째 · 둘째') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X46','kor',4,'u4',ARRAY['K4-2-u4-C45']::text[],'의견과 이어지지 않는 이유나 길고 많기만 한 이유를 알맞은 이유로 여긴다','의견대로 하면 좋은 점?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X47','kor',4,'u4',ARRAY['K4-2-u4-C45']::text[],'이유가 알맞은지를 내가 그 의견에 찬성하는지로 정한다','찬반과 상관없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X48','kor',4,'u4',ARRAY['K4-2-u4-C46','K4-2-u4-C47']::text[],'글에 실린 의견은 무조건 옳다고 믿고 그대로 따른다','이유를 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X49','kor',4,'u4',ARRAY['K4-2-u4-C46','K4-2-u4-C47']::text[],'의견 글은 일단 틀렸다고 보고 무조건 의심하거나 반대한다','견주어 보아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X50','kor',4,'u4',ARRAY['K4-2-u4-C50','K4-2-u4-C51']::text[],'느낌을 나타내는 방법에 등수가 있다고 여기거나 배운 방법만 써야 한다고 여긴다','방법에 등수 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X51','kor',4,'u4',ARRAY['K4-2-u4-C53']::text[],'질문 놀이에서 질문을 많이 받은 사람이 이긴다고 여긴다','이기는 놀이 ✗') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X52','kor',4,'u4',ARRAY['K4-2-u4-C53']::text[],'질문 놀이에서 빨리 답할수록 잘한 것이라고 여긴다','그렇게 읽었다고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X53','kor',4,'u4',ARRAY['K4-2-u4-C55']::text[],'물건이나 값을 「-시-」를 붙여 높인다','사람만 높여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X54','kor',4,'u4',ARRAY['K4-2-u4-C56']::text[],'나라를 말할 때 「저희 나라」라고 낮춘다','우리나라') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X55','kor',4,'u4',ARRAY['K4-2-u4-C57']::text[],'외국어와 우리말을 엇갈리게 짝짓거나, 외국어가 더 멋지다고 여기거나, 들어온 말은 빠짐없이 다 바꿔야 한다고 여긴다','바꿀 말이 있으면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X56','kor',4,'u4',ARRAY['K4-2-u4-C58']::text[],'ㄺ·ㄼ·ㄵ 같은 다른 겹받침을 ㄻ으로 여기거나 ㄻ을 받침 하나로 쓴다','ㄹ과 ㅁ이 나란히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X58','kor',4,'u4',ARRAY['K4-2-u4-C40']::text[],'글에서 새로 안 것과 더 알고 싶어진 것을 헷갈리거나 글과 상관없는 말을 한다','새로 안 것 · 궁금한 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X59','kor',4,'u4',ARRAY['K4-2-u4-C55','K4-2-u4-C56']::text[],'높임을 고칠 때 사람이 아닌 낱말에 「께서」를 붙이는 등 엉뚱한 곳을 높인다','높일 사람은 누구?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X60','kor',4,'u4',ARRAY['K4-2-u4-C60','K4-2-u4-C61']::text[],'「네 생각을 솔직히 말해」의 사건과 인물이 한 일을 이야기와 다르게 안다(서영이가 가방 구경을 못 해서 소리쳤다 · 진우가 재미로 옛이야기를 했다)','그 장면을 다시 읽어 보면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X61','kor',4,'u4',ARRAY['K4-2-u4-C18','K4-2-u4-C25']::text[],'하고 싶은 말을 거침없이 하는 인물(서영)을 친구를 일부러 괴롭히고 상처 주려는 나쁜 아이로 단정한다','서영이에게 나쁜 마음이 있었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X62','kor',4,'u4',ARRAY['K4-2-u4-C61','K4-2-u4-C25']::text[],'솔직하게 말하는 것은 상대의 기분이나 입장은 생각하지 않고 하고 싶은 말을 다 하는 것이라고 여긴다','같은 말도 다른 느낌으로 할 수 있다면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X63','kor',4,'u4',ARRAY['K4-2-u4-C61','K4-2-u4-C25']::text[],'마음이 불편할 때 무조건 참고 양보하는 것은 언제나 좋은 일이라고 여기고, 자기 마음을 속이는 것임을 놓친다','그건 참는 걸까, 도망치는 걸까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X64','kor',4,'u4',ARRAY['K4-2-u4-C62']::text[],'추궁 · 기세등등하다 · 교정하다 · 경청하다의 뜻을 엇갈리게 알거나, 문장 속 쓰임을 보지 않고 뜻을 고른다','쓰인 문장을 다시 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X65','kor',4,'u4',ARRAY['K4-2-u4-C59']::text[],'「기뻐의 비밀」에서 말하는 이가 한 말(숨은 비밀 · 조심하라고 한 것 · 눈물이 나는 때)을 시와 다르게 안다','그 줄을 다시 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X66','kor',4,'u4',ARRAY['K4-2-u4-C7','K4-2-u4-C9']::text[],'시를 읽고 떠올리는 경험은 직접 겪은 일만 해당하고, 책이나 텔레비전에서 본 일(간접 경험)은 해당하지 않는다고 여긴다','책이나 텔레비전에서 본 일도?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X67','kor',4,'u4',ARRAY['K4-2-u4-C10','K4-2-u4-C50']::text[],'생각이나 느낌은 말이나 글로만 나타낼 수 있다고 여겨 표정·소리·동작이나 색깔·모양·노래·즉흥극으로 나타내기를 빠뜨린다','몸짓이나 색깔로도 될까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X68','kor',4,'u4',ARRAY['K4-2-u4-C29','K4-2-u4-C38']::text[],'글을 잘 읽으려면 글의 내용을 빠짐없이 다 기억해야 한다고 여기고, 중요한 내용을 찾아 요약하는 것을 놓친다','다 외우기? 중요한 것 찾기?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X69','kor',4,'u4',ARRAY['K4-2-u4-C27','K4-2-u4-C28']::text[],'예상한 내용과 글의 내용은 꼭 같아야 하고, 다르면 잘못 읽은 것이라고 여긴다','예상은 확인하는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X70','kor',4,'u4',ARRAY['K4-2-u4-C63','K4-2-u4-C65','K4-2-u4-C67']::text[],'설명하는 글·의견을 제시하는 글의 낱말(새순·채취하다·고약·처방·개봉·터득·수거·창작·발전·침해)의 뜻을 엇갈리게 알거나 문장 속 쓰임을 살피지 않는다','뜻과 문장을 함께 보아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X71','kor',4,'u4',ARRAY['K4-2-u4-C64']::text[],'남은 약은 두었다가 비슷한 증상에 먹거나 쓰레기통·하수구에 버려도 되고, 버리면 약이 사라진다고 여긴다','남은 약은 어디로?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X72','kor',4,'u4',ARRAY['K4-2-u4-C66']::text[],'인터넷에 있는 자료나 친구의 작품은 누구나 볼 수 있으니 허락 없이 마음대로 써도 된다고 여긴다','만든 사람에게 허락을 받았나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X73','kor',4,'u4',ARRAY['K4-2-u4-C68']::text[],'시 「마음먹기」의 내용(먹은 마음 · 마음이 사라지는 모습 · 깨달은 것)을 시와 다르게 안다','그 줄을 다시 읽어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_basic#1','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C2',1,'mc','auto','『국어』 181쪽 「생각 열기」예요. 두 친구의 읽기 과정은 어떻게 다른가요?',ARRAY['K4-2-u4-X02','K4-2-u4-X01']::text[],false,'{"seq":1,"concept":"K4-2-u4-C2","difficulty":1,"kind":"mc","stem":"『국어』 181쪽 「생각 열기」예요. 두 친구의 읽기 과정은 어떻게 다른가요?","options":[{"t":"남자아이는 책을 읽기만 했고, 여자아이는 내용을 짐작하거나 제대로 이해했는지 확인하며 읽었다","correct":true},{"t":"남자아이가 더 빨리 끝까지 읽었으니 더 잘 읽었다","mis":"K4-2-u4-X02"},{"t":"여자아이는 같은 책을 여러 번 읽기만 했다","mis":"K4-2-u4-X02"},{"t":"두 친구의 읽기 과정은 똑같다","mis":"K4-2-u4-X01"}],"explanation":["남자아이는 다 읽고 나서 기억나는 내용이 없다고 했어요.","여자아이는 제목으로 짐작하고, 이해가 안 되는 부분은 다시 읽고, 다 읽고 정리했어요.","읽는 동안 무엇을 했는지가 두 친구의 차이예요."],"asset":{"type":"speech","turns":[{"who":"남자아이 — 읽기 전","text":"“이 책을 읽어 봐야지!”"},{"who":"남자아이 — 읽은 뒤","text":"“책을 읽었는데 왜 기억나는 내용이 없지?”"},{"who":"여자아이 — 읽기 전","text":"“제목을 보니 이 책에서는 화살나무에 대한 정보를 얻을 수 있겠어.”"},{"who":"여자아이 — 읽는 중","text":"“이 부분은 이해가 안 되네. 다시 천천히 읽어 보자.”"},{"who":"여자아이 — 읽은 뒤","text":"“책을 읽고 난 뒤에 중요한 내용을 따로 정리해 두어야지.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_basic#2','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C2',1,'mc','auto','여자아이처럼 책을 읽고 난 뒤에 중요한 내용을 따로 정리해 두면 어떤 점이 좋을까요?',ARRAY['K4-2-u4-X02','K4-2-u4-X68','K4-2-u4-X03']::text[],false,'{"seq":2,"concept":"K4-2-u4-C2","difficulty":1,"kind":"mc","stem":"여자아이처럼 책을 읽고 난 뒤에 중요한 내용을 따로 정리해 두면 어떤 점이 좋을까요?","options":[{"t":"읽은 내용을 정확하게, 오래 기억할 수 있다","correct":true},{"t":"책을 더 빨리 읽을 수 있다","mis":"K4-2-u4-X02"},{"t":"글의 모든 문장을 빠짐없이 외울 수 있다","mis":"K4-2-u4-X68"},{"t":"책 표지를 더 예쁘게 꾸밀 수 있다","mis":"K4-2-u4-X03"}],"explanation":["중요한 내용을 정리하면 다시 볼 수 있어요.","그래서 읽은 내용을 정확하게 기억할 수 있어요.","모든 문장을 외우는 것이 아니라 중요한 것을 골라 정리해요."],"asset":{"type":"speech","turns":[{"who":"남자아이 — 읽기 전","text":"“이 책을 읽어 봐야지!”"},{"who":"남자아이 — 읽은 뒤","text":"“책을 읽었는데 왜 기억나는 내용이 없지?”"},{"who":"여자아이 — 읽기 전","text":"“제목을 보니 이 책에서는 화살나무에 대한 정보를 얻을 수 있겠어.”"},{"who":"여자아이 — 읽는 중","text":"“이 부분은 이해가 안 되네. 다시 천천히 읽어 보자.”"},{"who":"여자아이 — 읽은 뒤","text":"“책을 읽고 난 뒤에 중요한 내용을 따로 정리해 두어야지.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_basic#3','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C1',1,'ox','auto','이 단원에서는 작품을 읽고 생각이나 느낌을 나누고, 질문을 활용해 읽기 과정을 되돌아보는 것을 배워요.',ARRAY['K4-2-u4-X01']::text[],false,'{"seq":3,"concept":"K4-2-u4-C1","difficulty":1,"kind":"ox","stem":"이 단원에서는 작품을 읽고 생각이나 느낌을 나누고, 질문을 활용해 읽기 과정을 되돌아보는 것을 배워요.","answer":"O","reason_options":[{"t":"『국어』 183쪽 「무엇을 배울까요」에 소단원 1과 소단원 2로 나와 있어요.","correct":true},{"t":"이 단원은 책을 빨리 많이 읽는 방법을 배우는 단원이에요.","mis":"K4-2-u4-X01"}],"mis":"K4-2-u4-X01","explanation":["소단원 1은 시와 이야기를 읽고 생각이나 느낌을 나누어요.","소단원 2는 질문을 활용해 읽기 과정을 되돌아보아요.","빨리 많이 읽기를 배우는 단원이 아니에요."],"asset":{"type":"passage","lines":["소단원 1 ① 시를 읽고 생각이나 느낌 나누기","소단원 1 ② 이야기를 읽고 생각이나 느낌 나누기","소단원 2 ① 읽기 과정을 되돌아볼 수 있는 질문 알기","소단원 2 ② 설명하는 글을 읽고 읽기 과정 되돌아보기","소단원 2 ③ 의견을 제시하는 글을 읽고 읽기 과정 되돌아보기"],"title":"무엇을 배울까요 — 『국어』 183쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_basic#4','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C59',1,'mc','auto','『국어』 184쪽 「기뻐의 비밀」에서 말하는 ‘기뻐의 비밀’은 무엇인가요?',ARRAY['K4-2-u4-X65','K4-2-u4-X09']::text[],false,'{"seq":4,"concept":"K4-2-u4-C59","difficulty":1,"kind":"mc","stem":"『국어』 184쪽 「기뻐의 비밀」에서 말하는 ‘기뻐의 비밀’은 무엇인가요?","options":[{"t":"기뻐 안에는 이뻐가 들어 있다는 것","correct":true},{"t":"기뻐를 길게 늘이면 반드시 끊어진다는 것","mis":"K4-2-u4-X65"},{"t":"기뻐 안에는 뻐기다가 들어 있다는 것","mis":"K4-2-u4-X09"},{"t":"기쁠 때는 누구나 눈물이 난다는 것","mis":"K4-2-u4-X65"}],"explanation":["말하는 이는 “내가 기뻐의 비밀을 말해 줄까?” 하고 시작해요.","바로 다음에 “기뻐 안에는 / 이뻐가 들어 있다”라고 했어요.","‘기’를 길게 늘이면 ‘이뻐’가 들려요."],"asset":{"type":"passage","lines":["내가 기뻐의 비밀을 말해 줄까?","기뻐 안에는","이뻐가 들어 있다","(간추림) 왼손으로 ‘기’, 오른손으로 ‘뻐’를 잡고 고무줄처럼 늘이면","(간추림) ‘기’와 ‘뻐’ 사이가 ‘이’로 길게 이어진다."],"title":"「기뻐의 비밀」(이안 글) 앞부분 — 『국어』 184쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_basic#5','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C59',2,'mc','auto','「기뻐의 비밀」에서 말하는 이가 조심하라고 한 것은 무엇인가요?',ARRAY['K4-2-u4-X65','K4-2-u4-X09']::text[],false,'{"seq":5,"concept":"K4-2-u4-C59","difficulty":2,"kind":"mc","stem":"「기뻐의 비밀」에서 말하는 이가 조심하라고 한 것은 무엇인가요?","options":[{"t":"기쁘다고 너무 뻐기다가 기뻐를 끊어 먹지 않도록 하는 것","correct":true},{"t":"고무줄을 너무 세게 잡아당기는 것","mis":"K4-2-u4-X65"},{"t":"기뻐를 너무 짧게 말하는 것","mis":"K4-2-u4-X09"},{"t":"친구에게 비밀을 말하는 것","mis":"K4-2-u4-X65"}],"explanation":["“기쁘다고 너무 뻐기다가”를 다시 읽어요.","그다음 줄이 “기뻐를 끊어 먹지 않도록 조심해”예요.","너무 뻐기면 기쁨이 끊어질 수 있다는 말이에요."],"asset":{"type":"passage","lines":["기쁘다고 너무 뻐기다가","기뻐를 끊어 먹지 않도록 조심해","(간추림) 길다고 꼭 좋은 것만은 아니라고 한다.","(간추림) 기뻐가 끊어질 땐 무지 따끔하다고 한다.","어쩔 땐 찔끔 눈물이이 나아"],"title":"「기뻐의 비밀」(이안 글) 뒷부분 — 『국어』 184쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_basic#6','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C59',2,'sa','auto','「기뻐의 비밀」에서 말하는 이는 언제 찔끔 눈물이 난다고 했나요? 시의 내용에서 찾아 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"K4-2-u4-C59","difficulty":2,"kind":"sa","stem":"「기뻐의 비밀」에서 말하는 이는 언제 찔끔 눈물이 난다고 했나요? 시의 내용에서 찾아 쓰세요.","answer":["기뻐가 끊어질 때","기뻐가 끊어질 땐","끊어질 때","기뻐가 끊어질 때 따끔해서"],"explanation":["“어쩔 땐 찔끔 눈물이이 나아” 바로 앞을 보아요.","기뻐가 끊어질 땐 무지 따끔하다고 했어요.","그래서 기뻐가 끊어질 때 찔끔 눈물이 난다는 거예요."],"asset":{"type":"passage","lines":["기쁘다고 너무 뻐기다가","기뻐를 끊어 먹지 않도록 조심해","(간추림) 길다고 꼭 좋은 것만은 아니라고 한다.","(간추림) 기뻐가 끊어질 땐 무지 따끔하다고 한다.","어쩔 땐 찔끔 눈물이이 나아"],"title":"「기뻐의 비밀」(이안 글) 뒷부분 — 『국어』 184쪽"},"mis":"K4-2-u4-X65"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_basic#7','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C10',2,'mc','auto','『국어』 185쪽 3번 (1)의 보기에서 말하는 이의 마음을 노란색 동그라미로 나타낸 까닭은 무엇인가요?',ARRAY['K4-2-u4-X10','K4-2-u4-X11','K4-2-u4-X14']::text[],false,'{"seq":7,"concept":"K4-2-u4-C10","difficulty":2,"kind":"mc","stem":"『국어』 185쪽 3번 (1)의 보기에서 말하는 이의 마음을 노란색 동그라미로 나타낸 까닭은 무엇인가요?","options":[{"t":"‘기뻐’를 길게 늘여 ‘이뻐’를 만들고 밝게 웃는 모습이 떠올라서","correct":true},{"t":"노란색이 반에서 가장 인기 있는 색이라서","mis":"K4-2-u4-X10"},{"t":"친구가 먼저 노란색을 골라서 따라 했기 때문에","mis":"K4-2-u4-X11"},{"t":"까닭은 없어도 되고 아무 색이나 고르면 되어서","mis":"K4-2-u4-X14"}],"explanation":["색깔이나 모양으로 나타낼 때에는 까닭을 함께 써요.","보기는 밝게 웃는 모습이 떠올라 노란색 동그라미로 나타냈어요.","사람마다 다른 색깔이 떠올라도 괜찮아요."],"asset":{"type":"passage","lines":["색깔이나 모양 — 노란색 동그라미","그렇게 나타낸 까닭 — ‘기뻐’를 길게 늘여 ‘이뻐’를 만들고","밝게 웃는 모습이 떠올랐기 때문입니다."],"title":"『국어』 185쪽 3번 (1) 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_basic#8','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C12',2,'mc','auto','『국어』 186쪽 4번 (1)이에요. 보기처럼 글자를 늘였을 때 비밀이 숨어 있는 낱말을 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u4-X15']::text[],false,'{"seq":8,"concept":"K4-2-u4-C12","difficulty":2,"kind":"mc","stem":"『국어』 186쪽 4번 (1)이에요. 보기처럼 글자를 늘였을 때 비밀이 숨어 있는 낱말을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"감기 — 암기","correct":true},{"t":"감기 — 오기","mis":"K4-2-u4-X15"},{"t":"모기 — 암기","mis":"K4-2-u4-X15"},{"t":"박수 — 기뻐","mis":"K4-2-u4-X15"}],"explanation":["‘감기’의 ‘감’을 길게 늘이면 ‘가아암기’가 돼요.","그러면 뒤에서 ‘암기’가 들려요.","‘모기’를 늘이면 ‘오기’가 숨어 있어요."],"asset":{"type":"passage","lines":["보기 — 찾은 낱말: 박수 → 숨어 있는 비밀: 악수","[늘이기] ‘바아아아…악수’처럼 앞 글자를 길게 늘여 소리 내어 보아요."],"title":"『국어』 186쪽 4번 (1) 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_basic#9','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C9',2,'mc','auto','「기뻐의 비밀」을 읽고 떠오른 장면이 짝과 서로 달랐어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u4-X08','K4-2-u4-X12','K4-2-u4-X10']::text[],false,'{"seq":9,"concept":"K4-2-u4-C9","difficulty":2,"kind":"mc","stem":"「기뻐의 비밀」을 읽고 떠오른 장면이 짝과 서로 달랐어요. 알맞은 생각은 무엇인가요?","options":[{"t":"사람마다 겪은 일이 달라서 떠오르는 장면도 다를 수 있다","correct":true},{"t":"같은 시에서는 떠오르는 장면이 하나로 정해져 있다","mis":"K4-2-u4-X08"},{"t":"나와 다른 장면은 틀린 것이다","mis":"K4-2-u4-X12"},{"t":"많은 친구가 떠올린 장면이 정답이다","mis":"K4-2-u4-X10"}],"explanation":["시를 읽으면 저마다 겪은 일과 이어서 장면을 떠올려요.","그래서 같은 시에서도 장면이 다를 수 있어요.","다른 장면은 틀린 것이 아니라 다른 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_basic#10','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C7',3,'mc','auto','친구들이 「기뻐의 비밀」을 읽고 떠올린 경험이에요. 시를 읽고 떠올린 경험으로 볼 수 있는 것을 모두 고른 것은 무엇인가요?',ARRAY['K4-2-u4-X66','K4-2-u4-X08','K4-2-u4-X14']::text[],false,'{"seq":10,"concept":"K4-2-u4-C7","difficulty":3,"kind":"mc","stem":"친구들이 「기뻐의 비밀」을 읽고 떠올린 경험이에요. 시를 읽고 떠올린 경험으로 볼 수 있는 것을 모두 고른 것은 무엇인가요?","options":[{"t":"㉠, ㉡, ㉢","correct":true},{"t":"㉠ — 직접 겪은 일만 경험이다","mis":"K4-2-u4-X66"},{"t":"㉡, ㉢ — 시와 똑같은 일만 경험이다","mis":"K4-2-u4-X08"},{"t":"없다 — 시와 아무 상관이 없다","mis":"K4-2-u4-X14"}],"explanation":["시를 읽고 자신이 직접 겪은 일을 떠올릴 수 있어요.","책이나 텔레비전에서 본 일처럼 간접적으로 겪은 일도 떠올릴 수 있어요.","그래서 ㉠, ㉡, ㉢ 모두 시를 읽고 떠올린 경험이에요."],"asset":{"type":"passage","lines":["㉠ 고무줄을 길게 늘이다가 끊어져 손이 따끔했던 일","㉡ 텔레비전에서 아이들이 고무줄놀이 하는 모습을 본 일","㉢ 책에서 글자로 말놀이를 하는 다른 시를 읽은 일"],"title":"친구들이 시를 읽고 떠올린 경험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_challenge#1','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C3',2,'mc','auto','『국어』 182쪽 1번 상황 ㉮~㉱ 가운데에서 시나 이야기를 읽을 때 겪은 어려움을 모두 고른 것은 무엇인가요?',ARRAY['K4-2-u4-X05']::text[],false,'{"seq":1,"concept":"K4-2-u4-C3","difficulty":2,"kind":"mc","stem":"『국어』 182쪽 1번 상황 ㉮~㉱ 가운데에서 시나 이야기를 읽을 때 겪은 어려움을 모두 고른 것은 무엇인가요?","options":[{"t":"㉯, ㉱","correct":true},{"t":"㉮, ㉰","mis":"K4-2-u4-X05"},{"t":"㉮, ㉯","mis":"K4-2-u4-X05"},{"t":"㉰, ㉱","mis":"K4-2-u4-X05"}],"explanation":["㉯는 작품에 대한 생각이나 느낌을, ㉱는 인물의 마음을 모르는 어려움이에요.","㉮는 의견을 제시하는 글, ㉰는 설명하는 글을 읽을 때의 어려움이에요.","글의 종류에 따라 겪는 어려움도 달라요."],"asset":{"type":"passage","lines":["㉮ “글쓴이의 의견이 뭐지?”","㉯ “작품에 대한 내 생각이나 느낌을 말하기가 어려워.”","㉰ “글에서 설명하는 내용이 잘 이해되지 않아.”","㉱ “그 상황에서 인물이 어떤 마음이었는지 모르겠어.”"],"title":"『국어』 182쪽 1번 상황 ㉮~㉱"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_challenge#2','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C4',2,'mc','auto','『국어』 182쪽 2번이에요. 읽기 과정에서 겪은 어려움을 해결하는 방법으로 친구들이 떠올린 것은 무엇인가요?',ARRAY['K4-2-u4-X02','K4-2-u4-X04']::text[],false,'{"seq":2,"concept":"K4-2-u4-C4","difficulty":2,"kind":"mc","stem":"『국어』 182쪽 2번이에요. 읽기 과정에서 겪은 어려움을 해결하는 방법으로 친구들이 떠올린 것은 무엇인가요?","options":[{"t":"질문을 활용해서 글을 어떻게 읽었는지 되돌아본다","correct":true},{"t":"어려운 글은 읽지 않고 쉬운 글만 읽는다","mis":"K4-2-u4-X02"},{"t":"질문은 선생님께만 하는 것이니 기다린다","mis":"K4-2-u4-X04"},{"t":"같은 글을 처음부터 빨리 여러 번 읽기만 한다","mis":"K4-2-u4-X02"}],"explanation":["친구 2가 질문을 활용해 되돌아보면 도움이 된다고 했어요.","스스로 던지는 질문으로 내가 잘 이해했는지 점검할 수 있어요.","이것이 이 단원에서 배울 읽기 방법이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“읽기 과정에서 겪은 어려움을 어떻게 해결할 수 있을까?”"},{"who":"친구 2","text":"“질문을 활용해서 글을 어떻게 읽었는지 되돌아보면 도움이 될 거야.”"},{"who":"친구 3","text":"“읽기 과정을 되돌아보려면 어떤 질문을 해야 할까?”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_challenge#3','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C5',3,'match','auto','『국어』 183쪽 3번이에요. 질문과 그 질문을 떠올린 글의 종류를 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u4-C5","difficulty":3,"kind":"match","stem":"『국어』 183쪽 3번이에요. 질문과 그 질문을 떠올린 글의 종류를 알맞게 이으세요.","pairs":[{"l":"가장 기억에 남는 표현이나 장면은 무엇인가요?","r":"시나 이야기"},{"l":"이 글은 무엇에 대해 자세하게 알려 주고 있나요?","r":"설명하는 글"},{"l":"글쓴이의 의견을 뒷받침하는 이유가 적절한가요?","r":"의견을 제시하는 글"}],"mis":"K4-2-u4-X05","explanation":["시나 이야기는 마음에 남는 표현이나 장면을 떠올려요.","설명하는 글은 무엇을 알려 주는지 살펴요.","의견을 제시하는 글은 이유가 적절한지 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_challenge#4','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C5',3,'mc','auto','친구 4가 한 말 「(          )」에 들어갈 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X05','K4-2-u4-X06','K4-2-u4-X30']::text[],false,'{"seq":4,"concept":"K4-2-u4-C5","difficulty":3,"kind":"mc","stem":"친구 4가 한 말 「(          )」에 들어갈 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"글의 종류에 따라 읽기 과정을 되돌아보는 질문이 다를 것 같아.","correct":true},{"t":"어떤 글이든 똑같은 질문 하나만 하면 될 것 같아.","mis":"K4-2-u4-X05"},{"t":"질문은 많이 만들수록 좋을 것 같아.","mis":"K4-2-u4-X06"},{"t":"글을 다 읽은 뒤에만 질문하면 될 것 같아.","mis":"K4-2-u4-X30"}],"explanation":["친구 3은 어떤 질문을 해야 할지 물었어요.","시, 설명하는 글, 의견을 제시하는 글은 쓴 목적이 달라요.","그래서 글의 종류에 따라 알맞은 질문도 달라요."],"asset":{"type":"speech","turns":[{"who":"친구 2","text":"“질문을 활용해서 글을 어떻게 읽었는지 되돌아보면 도움이 될 거야.”"},{"who":"친구 3","text":"“읽기 과정을 되돌아보려면 어떤 질문을 해야 할까?”"},{"who":"친구 4","text":"“(                    )”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_challenge#5','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C11',3,'error','auto','「기뻐의 비밀」에 대한 생각이나 느낌을 짝과 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X12','K4-2-u4-X16','K4-2-u4-X13']::text[],false,'{"seq":5,"concept":"K4-2-u4-C11","difficulty":3,"kind":"error","stem":"「기뻐의 비밀」에 대한 생각이나 느낌을 짝과 이야기했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"서윤: “네가 떠올린 장면은 틀렸어. 고무줄 장면이 정답이야.”","correct":true,"mis_target":"K4-2-u4-X12"},{"t":"지아: “뻐기다가 끊어 먹지 말라는 부분에서 조심스러운 마음이 느껴졌어.”","mis":"K4-2-u4-X16"},{"t":"준서: “나랑 느낌이 다르네. 왜 그렇게 느꼈는지 궁금해.”","mis":"K4-2-u4-X13"}],"explanation":["생각이나 느낌은 사람마다 다를 수 있어요.","다른 느낌을 들으면 틀렸다고 하지 않고 까닭을 물어요.","서로 다른 느낌을 나누면 작품의 여러 면을 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_challenge#6','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C12',3,'mc','auto','「기뻐의 비밀」에서 ‘기뻐’ 속에 ‘이뻐’가 들어 있다고 한 까닭은 무엇인가요?',ARRAY['K4-2-u4-X15','K4-2-u4-X65','K4-2-u4-X09']::text[],false,'{"seq":6,"concept":"K4-2-u4-C12","difficulty":3,"kind":"mc","stem":"「기뻐의 비밀」에서 ‘기뻐’ 속에 ‘이뻐’가 들어 있다고 한 까닭은 무엇인가요?","options":[{"t":"‘기’를 길게 늘이면 ‘이’ 소리가 이어져 ‘이뻐’가 들리기 때문","correct":true},{"t":"‘뻐’를 길게 늘이면 ‘이’ 소리가 나기 때문","mis":"K4-2-u4-X15"},{"t":"기쁘면 누구나 예뻐지기 때문","mis":"K4-2-u4-X65"},{"t":"‘기뻐’와 ‘이뻐’는 뜻이 같기 때문","mis":"K4-2-u4-X09"}],"explanation":["‘기’를 “기이이이……” 하고 늘여 소리 내어 보아요.","‘이’ 소리 끝에 ‘뻐’가 붙어 ‘이뻐’가 들려요.","소리를 늘여 숨은 낱말을 찾는 말놀이예요."],"asset":{"type":"passage","lines":["내가 기뻐의 비밀을 말해 줄까?","기뻐 안에는","이뻐가 들어 있다","(간추림) 왼손으로 ‘기’, 오른손으로 ‘뻐’를 잡고 고무줄처럼 늘이면","(간추림) ‘기’와 ‘뻐’ 사이가 ‘이’로 길게 이어진다."],"title":"「기뻐의 비밀」(이안 글) 앞부분 — 『국어』 184쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_challenge#7','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C59',3,'mc','auto','「기뻐의 비밀」의 재미를 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X65','K4-2-u4-X15']::text[],false,'{"seq":7,"concept":"K4-2-u4-C59","difficulty":3,"kind":"mc","stem":"「기뻐의 비밀」의 재미를 바르게 말한 것은 무엇인가요?","options":[{"t":"‘기뻐’ 속에 ‘이뻐’가 있다는 구절처럼 말소리를 재치 있게 살려 새로운 뜻을 붙였다","correct":true},{"t":"어려운 낱말을 많이 써서 뜻을 알기 어렵게 했다","mis":"K4-2-u4-X65"},{"t":"기쁜 일을 겪은 날짜와 장소를 자세히 적었다","mis":"K4-2-u4-X65"},{"t":"늘인 글자 속에는 숨은 낱말이 없다","mis":"K4-2-u4-X15"}],"explanation":["시는 ‘기뻐’의 소리를 고무줄처럼 늘여 보여 줘요.","그 속에서 ‘이뻐’라는 새 낱말을 찾아냈어요.","주변 낱말에서도 이런 비밀을 찾아보면 시를 더 재미있게 즐길 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_challenge#8','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C10',4,'essay','teacher','「도」에서 인상 깊은 부분을 찾아 그렇게 느낀 까닭을 쓰고, 생각나는 친구에게 응원하는 쪽지를 짧게 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u4-C10","difficulty":4,"kind":"essay","stem":"「도」에서 인상 깊은 부분을 찾아 그렇게 느낀 까닭을 쓰고, 생각나는 친구에게 응원하는 쪽지를 짧게 쓰세요.","answer_guide":{"answer":"예: 인상 깊은 부분 — “막다른 곳에서도 / 힘을 내는 도가 있어 / 아직도” · 까닭 — 친구를 응원하는 마음이 잘 느껴졌기 때문입니다. · 쪽지 — ○○야, 연습이 힘들어도 너는 아직 할 수 있어! 늘 응원할게.","scoring_points":["시에서 인상 깊은 부분을 골랐는가","그렇게 느낀 까닭을 시의 내용과 이어 썼는가","응원하는 마음이 드러나는 쪽지를 썼는가"]},"explanation":["『국어활동』 54~55쪽에서는 응원하고 싶은 친구를 떠올리며 시를 읽어요.","인상 깊은 부분과 그렇게 느낀 까닭을 함께 써요.","쪽지에는 친구에게 힘이 되는 말을 담아요."],"asset":{"type":"passage","lines":["막다른 곳에서도","힘을 내는 도가 있어","아직도"],"title":"「도」에서 인상 깊은 부분 — 『국어활동』 55쪽 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_challenge#9','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C59',4,'essay','teacher','「기뻐의 비밀」에서 “아니이잖아”, “눈물이이 나아”처럼 ‘이’를 반복해서 쓴 까닭을 생각해 쓰고, 그 부분을 소리 내어 읽을 때 든 느낌을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u4-C59","difficulty":4,"kind":"essay","stem":"「기뻐의 비밀」에서 “아니이잖아”, “눈물이이 나아”처럼 ‘이’를 반복해서 쓴 까닭을 생각해 쓰고, 그 부분을 소리 내어 읽을 때 든 느낌을 쓰세요.","answer_guide":{"answer":"예: 고무줄처럼 길게 늘어난 기뻐를 말소리로도 늘여 보여 주려고 ‘이’를 반복한 것 같다. 그 부분을 소리 내어 읽으니 말끝이 늘어지면서 웃음이 나고, 눈물이 찔끔 나는 모습도 떠올랐다.","scoring_points":["‘이’를 반복한 까닭을 시의 내용(늘이기)과 이어 썼는가","소리 내어 읽을 때 든 자신의 느낌을 썼는가","시의 구절을 근거로 들었는가"]},"explanation":["시에서 ‘이’가 반복된 곳을 모두 찾아 소리 내어 읽어요.","‘기이이…뻐’처럼 늘이는 장면과 이어 생각해요.","내 느낌은 정답이 없지만 까닭을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L02_challenge#10','kor',4,2,'u4','L02','tb_g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C12',4,'essay','teacher','「기뻐의 비밀」처럼 글자에 숨어 있는 비밀을 찾아, 「박수의 비밀」처럼 시를 바꾸어 쓰세요. 찾은 낱말과 숨어 있는 비밀이 드러나게 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C12","difficulty":4,"kind":"essay","stem":"「기뻐의 비밀」처럼 글자에 숨어 있는 비밀을 찾아, 「박수의 비밀」처럼 시를 바꾸어 쓰세요. 찾은 낱말과 숨어 있는 비밀이 드러나게 쓰세요.","answer_guide":{"answer":"예: 「감기의 비밀」 — 내가 감기의 비밀을 말해 줄까? / 감기 안에는 / 암기가 들어 있다 / 왼손으로 ‘감’, 오른손으로 ‘기’를 잡고 / 쭈욱 늘이는 거야 / 감기에 걸려 쉬는 날에도 / 구구단 암기는 잊지 말자","scoring_points":["글자를 늘였을 때 비밀이 숨어 있는 낱말을 찾았는가","찾은 낱말과 숨은 낱말이 시에 드러나는가","「기뻐의 비밀」의 짜임을 살려 바꾸어 썼는가"]},"explanation":["먼저 앞 글자를 길게 늘였을 때 다른 낱말이 들리는 낱말을 찾아요.","「박수의 비밀」처럼 찾은 낱말을 넣어 시를 바꾸어요.","숨은 낱말로 새로운 뜻을 붙여 보아요."],"asset":{"type":"passage","lines":["내가 박수의 비밀을 말해 줄까?","박수 안에는","악수가 들어 있다","(간추림) 왼손으로 ‘박’, 오른손으로 ‘수’를 잡고 고무줄처럼 늘인다.","친구의 기쁨에","진심으로 박수를 보내다 보면","너와 악수를 나눌 좋은 친구가","많이 생기게 될 거야"],"title":"시 바꾸어 쓰기 예 「박수의 비밀」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_basic#1','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C60',1,'mc','auto','『국어』 196쪽 내용 알기예요. 선물 가게에서 서영이는 왜 승한이에게 다급하게 소리를 질렀나요?',ARRAY['K4-2-u4-X60']::text[],false,'{"seq":1,"concept":"K4-2-u4-C60","difficulty":1,"kind":"mc","stem":"『국어』 196쪽 내용 알기예요. 선물 가게에서 서영이는 왜 승한이에게 다급하게 소리를 질렀나요?","options":[{"t":"마음을 솔직하게 말하지 못하고 원하지 않는 가방을 억지로 사려는 승한이가 답답해서","correct":true},{"t":"가방 구경을 못 해서","mis":"K4-2-u4-X60"},{"t":"자기도 그 가방을 사고 싶어서","mis":"K4-2-u4-X60"},{"t":"아저씨가 가방을 너무 비싸게 팔아서","mis":"K4-2-u4-X60"}],"explanation":["승한이는 전부터 버지5 가방을 가지고 싶다고 했어요.","그런데 아저씨가 권한 다른 가방을 사고 있었어요.","서영이는 그런 승한이의 모습이 답답했어요."],"asset":{"type":"passage","lines":["(간추림) 진우와 서영이는 승한이가 선물 가게로 들어가는 것을 보고 따라갔다.","(간추림) 승한이는 막 계산을 마치고 가방을 받고 있었다.","“야! 정승한. 너 이 가방, 버지5 아니잖아.”","“그, 그게……. 버지5도 좋은데 아저씨가 지금은 다 떨어졌다고 해서.","이 가방도 좋은 거래.”"],"title":"「네 생각을 솔직히 말해」(신지영 글) 선물 가게 — 『국어』 188~189쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_basic#2','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C61',1,'mc','auto','진우가 승한이에게 스님과 사슴 이야기를 해 준 까닭은 무엇인가요?',ARRAY['K4-2-u4-X60','K4-2-u4-X17']::text[],false,'{"seq":2,"concept":"K4-2-u4-C61","difficulty":1,"kind":"mc","stem":"진우가 승한이에게 스님과 사슴 이야기를 해 준 까닭은 무엇인가요?","options":[{"t":"서영이도 승한이가 손해 보거나 양보만 하다가 진짜 나쁜 사람을 만날까 봐 걱정했다는 것을 알려 주려고","correct":true},{"t":"승한이에게 재미있는 옛이야기를 들려주어 기분을 풀어 주려고","mis":"K4-2-u4-X60"},{"t":"스님처럼 채소를 잘 키우는 방법을 알려 주려고","mis":"K4-2-u4-X60"},{"t":"승한이가 겉으로 괜찮다고 했으니 정말 괜찮은 줄 알아서","mis":"K4-2-u4-X17"}],"explanation":["스님은 사슴에게 사람을 조심해야 한다는 걸 가르치려고 막대기를 휘둘렀어요.","진우는 서영이가 스님처럼 승한이를 위해 그렇게 한 것이라고 했어요.","승한이가 무조건 양보하다가 큰일을 당할까 봐 걱정한 거예요."],"asset":{"type":"passage","lines":["(간추림) 스님들은 채소를 먹는 어린 사슴이 귀엽고 안돼서 쫓아내지 않았다.","(간추림) 어느 날 한 스님이 막대기를 휘두르며 사슴을 쫓아냈다.","(간추림) 세상에는 사냥꾼도 있으니 사람을 조심해야 하는 걸 가르쳐야 한다고 했다.","“서영이는 그런 너를 위해 스님처럼 막대기를 휘둘러 준 거야.”"],"title":"「네 생각을 솔직히 말해」 스님과 사슴 이야기 — 『국어』 191~192쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_basic#3','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C61',1,'mc','auto','서영이가 소은이에게 이상한 냄새가 난다고 한 말을 소은이와 다른 사람들이 전혀 다르게 받아들인 까닭은 무엇인가요?',ARRAY['K4-2-u4-X61','K4-2-u4-X62','K4-2-u4-X60']::text[],false,'{"seq":3,"concept":"K4-2-u4-C61","difficulty":1,"kind":"mc","stem":"서영이가 소은이에게 이상한 냄새가 난다고 한 말을 소은이와 다른 사람들이 전혀 다르게 받아들인 까닭은 무엇인가요?","options":[{"t":"서영이가 상대의 입장에서 생각하지 않고 하고 싶은 말을 다 했기 때문","correct":true},{"t":"서영이가 소은이를 놀리고 괴롭히려고 일부러 말했기 때문","mis":"K4-2-u4-X61"},{"t":"솔직한 말은 언제나 상대를 기쁘게 하기 때문","mis":"K4-2-u4-X62"},{"t":"소은이가 서영이의 말을 잘못 들었기 때문","mis":"K4-2-u4-X60"}],"explanation":["서영이는 놀리거나 괴롭히려는 생각은 없었어요.","하지만 아이들이 가득 있는 교실에서 소은이의 마음을 헤아리지 않고 말했어요.","상대의 입장을 생각하지 않은 말은 상처를 줄 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 서영이는 짝 소은이에게 이상한 냄새가 난다고 말했던 일을 떠올렸다.","(간추림) 놀리거나 괴롭히려는 생각은 없었지만 소은이는 다르게 받아들였다.","(간추림) 소은이가 된 상상을 하자 서영이는 마음이 따갑고 아팠다.","(간추림) 승한이는 친구들이 프라모델을 달라고 할까 봐 집에 부르지 않았다.","(간추림) 서영이도 승한이도 오랫동안 말이 없었다."],"title":"「네 생각을 솔직히 말해」 돌아보는 두 친구 — 『국어』 194~195쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_basic#4','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C62',1,'mc','auto','『국어』 196쪽 낱말 알기예요. 「잘못한 일에 대하여 엄하게 따져서 밝힘.」이라는 뜻을 가진 낱말은 무엇인가요?',ARRAY['K4-2-u4-X64']::text[],false,'{"seq":4,"concept":"K4-2-u4-C62","difficulty":1,"kind":"mc","stem":"『국어』 196쪽 낱말 알기예요. 「잘못한 일에 대하여 엄하게 따져서 밝힘.」이라는 뜻을 가진 낱말은 무엇인가요?","options":[{"t":"추궁","correct":true},{"t":"기세등등하다","mis":"K4-2-u4-X64"},{"t":"교정하다","mis":"K4-2-u4-X64"},{"t":"경청하다","mis":"K4-2-u4-X64"}],"explanation":["“서영이의 추궁에 승한이가 우물쭈물하더니”를 다시 읽어요.","서영이가 승한이를 엄하게 따져 묻는 장면이에요.","그래서 ‘추궁’의 뜻은 잘못을 엄하게 따져서 밝히는 것이에요."],"asset":{"type":"passage","lines":["서영이의 추궁에 승한이가 우물쭈물하더니 기어드는 소리로 말했다.","서영이가 기세등등해서 속이 시원하다는 듯 소리쳤다.","자신의 잘못을 조목조목 짚어 가며 교정해 주는 사람이 아니라는 거야."],"title":"「네 생각을 솔직히 말해」 낱말 알기 — 『국어』 196쪽","hi":["추궁","기세등등해서","교정해"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_basic#5','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C62',2,'match','auto','이야기에 나온 낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u4-C62","difficulty":2,"kind":"match","stem":"이야기에 나온 낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"기세등등하다","r":"기세가 매우 높고 힘차다."},{"l":"교정하다","r":"가르쳐서 바르게 하다."},{"l":"경청하다","r":"귀를 기울여 듣다."}],"mis":"K4-2-u4-X64","explanation":["서영이가 속이 시원하다는 듯 소리칠 때 ‘기세등등해서’가 나와요.","진우는 친구들이 잘못을 교정해 주는 사람을 원하지 않는다고 했어요.","두 친구가 진우의 이야기를 경청했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_basic#6','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C18',2,'mc','auto','승한이의 말 “버지5가 좋긴 더 좋은데, 이 가방도 괜찮지 않을까?”로 짐작할 수 있는 승한이의 성격은 무엇인가요?',ARRAY['K4-2-u4-X20','K4-2-u4-X17']::text[],false,'{"seq":6,"concept":"K4-2-u4-C18","difficulty":2,"kind":"mc","stem":"승한이의 말 “버지5가 좋긴 더 좋은데, 이 가방도 괜찮지 않을까?”로 짐작할 수 있는 승한이의 성격은 무엇인가요?","options":[{"t":"자신의 생각을 주장하기보다 다른 사람의 기분을 맞추려 한다","correct":true},{"t":"자기 생각을 거리낌 없이 빠르게 말한다","mis":"K4-2-u4-X20"},{"t":"이 가방이 정말 마음에 들어 끝까지 사려고 한다","mis":"K4-2-u4-X17"},{"t":"상대의 잘못을 차분하게 짚어 준다","mis":"K4-2-u4-X20"}],"explanation":["승한이는 버지5가 더 좋다고 하면서도 아저씨 말을 따르려 해요.","하고 싶은 말을 분명히 하지 못하고 있어요.","인물의 말과 행동을 살펴 성격을 짐작해요."],"asset":{"type":"passage","lines":["“아저씨, 잠깐만요. 야! 정승한, 너 똑바로 말해.”","“버지5가 좋긴 더 좋은데, 이 가방도 괜찮지 않을까?”","(간추림) 서영이는 가방을 낚아채 주인아저씨에게 돌려주었다.","(간추림) 다그치는 서영이에게 승한이는 겨우 고개를 끄덕였다.","(간추림) 승한이는 얼굴이 빨개져서 도망치듯 가게를 뛰쳐나갔다."],"title":"「네 생각을 솔직히 말해」 선물 가게 — 『국어』 189~190쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_basic#7','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C19',2,'mc','auto','역할놀이에서 진우를 맡았어요. 진우의 성격을 잘 드러내는 말투는 무엇인가요?',ARRAY['K4-2-u4-X22','K4-2-u4-X24']::text[],false,'{"seq":7,"concept":"K4-2-u4-C19","difficulty":2,"kind":"mc","stem":"역할놀이에서 진우를 맡았어요. 진우의 성격을 잘 드러내는 말투는 무엇인가요?","options":[{"t":"단단하면서도 차분한 목소리","correct":true},{"t":"천천히, 기어드는 작은 목소리","mis":"K4-2-u4-X22"},{"t":"빠르고 높은 목소리로 다그치듯","mis":"K4-2-u4-X22"},{"t":"친구들이 웃도록 큰 소리로 장난스럽게","mis":"K4-2-u4-X24"}],"explanation":["진우는 두 친구의 태도에서 고쳐야 할 점을 차분하게 알려 줘요.","그래서 단단하면서도 차분한 목소리가 어울려요.","천천히 말하는 승한이, 빠르게 말하는 서영이와 다르게 표현해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_basic#8','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C21',2,'mc','auto','『국어』 198쪽 (3)처럼 역할놀이를 할 때의 순서로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X26']::text[],false,'{"seq":8,"concept":"K4-2-u4-C21","difficulty":2,"kind":"mc","stem":"『국어』 198쪽 (3)처럼 역할놀이를 할 때의 순서로 알맞은 것은 무엇인가요?","options":[{"t":"상황 정하기 → 역할 나누기(해설자 포함) → 연습하기 → 발표하기","correct":true},{"t":"역할 나누기 → 발표하기 → 상황 정하기 → 연습하기","mis":"K4-2-u4-X26"},{"t":"연습하기 → 상황 정하기 → 발표하기 → 역할 나누기","mis":"K4-2-u4-X26"},{"t":"상황 정하기 → 발표하기 → 연습하기 → 역할 나누기","mis":"K4-2-u4-X26"}],"explanation":["먼저 어떤 장면을 할지 상황을 정해요.","해설자를 포함해 역할을 나누고 연습해요.","연습한 뒤 친구들 앞에서 발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_basic#9','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C25',2,'ox','auto','진우는 서영이에게 “내가 보기엔 서영이 너도 좀 문제야.”라고 했어요. 진우는 승한이만 잘못했다고 생각해요.',ARRAY['K4-2-u4-X29']::text[],false,'{"seq":9,"concept":"K4-2-u4-C25","difficulty":2,"kind":"ox","stem":"진우는 서영이에게 “내가 보기엔 서영이 너도 좀 문제야.”라고 했어요. 진우는 승한이만 잘못했다고 생각해요.","answer":"X","reason_options":[{"t":"진우는 승한이에게도, 서영이에게도 고칠 점을 한 가지씩 알려 주었어요.","correct":true},{"t":"진우는 서영이가 다 옳고 승한이만 잘못했다고 했어요.","mis":"K4-2-u4-X29"}],"mis":"K4-2-u4-X29","explanation":["진우는 승한이에게 무조건 양보하는 것은 도망치는 것이라고 했어요.","서영이에게는 상대방의 입장에서 생각하고 말해 보라고 했어요.","두 친구 모두 고칠 점이 있었어요."],"asset":{"type":"passage","lines":["“내가 보기엔 서영이 너도 좀 문제야.”","(간추림) 친구들이 좋아하는 사람은 이해를 해 주는 친구라고 했다.","“그리고 같은 말이라도 얼마든지 다른 느낌으로 할 수 있어.”","“넌 한 번이라도 상대방의 입장이 돼서 생각하고 말해 본 적 있니?”"],"title":"「네 생각을 솔직히 말해」 진우의 조언 — 『국어』 193~194쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_basic#10','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C14',3,'mc','auto','『국어』 199쪽 정리처럼, 이야기를 읽고 생각이나 느낌을 나누는 방법을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X68','K4-2-u4-X10','K4-2-u4-X20']::text[],false,'{"seq":10,"concept":"K4-2-u4-C14","difficulty":3,"kind":"mc","stem":"『국어』 199쪽 정리처럼, 이야기를 읽고 생각이나 느낌을 나누는 방법을 바르게 말한 것은 무엇인가요?","options":[{"t":"인물의 말과 행동을 떠올리고, 이야기와 관련 있는 자신의 경험을 떠올린다","correct":true},{"t":"이야기의 문장을 그대로 외워 말한다","mis":"K4-2-u4-X68"},{"t":"가장 많은 친구가 말한 느낌을 따라 말한다","mis":"K4-2-u4-X10"},{"t":"인물의 이름과 겉모습만 보고 느낌을 정한다","mis":"K4-2-u4-X20"}],"explanation":["인물이 한 말과 행동을 떠올리면 생각이나 느낌이 생겨요.","나와 비슷한 경험을 떠올리면 느낌이 더 풍부해져요.","남의 느낌을 따라 하지 않고 내 느낌과 까닭을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_challenge#1','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C60',2,'mc','auto','『국어』 190쪽이에요. 승한이가 고개를 끄덕이자 주인아저씨는 어떻게 했나요?',ARRAY['K4-2-u4-X60']::text[],false,'{"seq":1,"concept":"K4-2-u4-C60","difficulty":2,"kind":"mc","stem":"『국어』 190쪽이에요. 승한이가 고개를 끄덕이자 주인아저씨는 어떻게 했나요?","options":[{"t":"불쾌한 얼굴로 가방을 다시 걸어 놓고 돈을 되돌려 주었다","correct":true},{"t":"승한이에게 버지5 가방을 꺼내 주었다","mis":"K4-2-u4-X60"},{"t":"서영이를 칭찬하며 가방값을 깎아 주었다","mis":"K4-2-u4-X60"},{"t":"승한이에게 그 가방을 억지로 팔았다","mis":"K4-2-u4-X60"}],"explanation":["아저씨는 싫으면 싫다고 말을 해야지 왜 자기만 나쁜 사람을 만드냐고 했어요.","그리고 불쾌한 얼굴로 가방을 다시 걸어 놓고 돈을 돌려주었어요.","승한이는 얼굴이 빨개져서 가게를 뛰쳐나갔어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_challenge#2','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C62',2,'mc','auto','「서영이가 기세등등해서 속이 시원하다는 듯 소리쳤다.」에서 ‘기세등등해서’를 바꾸어 쓸 수 있는 말은 무엇인가요?',ARRAY['K4-2-u4-X64']::text[],false,'{"seq":2,"concept":"K4-2-u4-C62","difficulty":2,"kind":"mc","stem":"「서영이가 기세등등해서 속이 시원하다는 듯 소리쳤다.」에서 ‘기세등등해서’를 바꾸어 쓸 수 있는 말은 무엇인가요?","options":[{"t":"기세가 매우 높고 힘차서","correct":true},{"t":"잘못한 일을 엄하게 따져서","mis":"K4-2-u4-X64"},{"t":"가르쳐서 바르게 하여","mis":"K4-2-u4-X64"},{"t":"귀를 기울여 들어서","mis":"K4-2-u4-X64"}],"explanation":["진우가 서영이 편을 드는 말을 하자 서영이는 우쭐해졌어요.","그래서 속이 시원하다는 듯 소리쳤어요.","‘기세등등하다’는 기세가 매우 높고 힘차다는 뜻이에요."],"asset":{"type":"passage","lines":["서영이의 추궁에 승한이가 우물쭈물하더니 기어드는 소리로 말했다.","서영이가 기세등등해서 속이 시원하다는 듯 소리쳤다.","자신의 잘못을 조목조목 짚어 가며 교정해 주는 사람이 아니라는 거야."],"title":"「네 생각을 솔직히 말해」 낱말 알기 — 『국어』 196쪽","hi":["추궁","기세등등해서","교정해"]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_challenge#3','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C61',3,'mc','auto','진우가 승한이에게 “그건 참는 게 아니라 도망치는 거니까.”라고 말한 까닭은 무엇인가요?',ARRAY['K4-2-u4-X63','K4-2-u4-X17','K4-2-u4-X62']::text[],false,'{"seq":3,"concept":"K4-2-u4-C61","difficulty":3,"kind":"mc","stem":"진우가 승한이에게 “그건 참는 게 아니라 도망치는 거니까.”라고 말한 까닭은 무엇인가요?","options":[{"t":"마음이 불편한 상황이 생기면 무조건 손해 보거나 양보하며 자기 마음을 속여 왔기 때문","correct":true},{"t":"양보하고 참는 것은 언제나 좋은 일이라서","mis":"K4-2-u4-X63"},{"t":"승한이가 신호등 앞에서 정말로 달아나 버려서","mis":"K4-2-u4-X17"},{"t":"서영이처럼 하고 싶은 말을 다 해야 해서","mis":"K4-2-u4-X62"}],"explanation":["승한이는 서영이처럼 남을 창피하게 하는 것보다 양보하는 게 낫다고 했어요.","진우는 승한이가 불편한 상황을 피하려고 무조건 양보한다고 했어요.","그것은 참는 것이 아니라 자기 마음을 속이고 피하는 것이라는 뜻이에요."],"asset":{"type":"passage","lines":["“넌 아저씨 앞에서 꼭 그렇게 해야 해? 아저씨도 창피하고 나도 창피하잖아.”","“그럼 넌 내가 잘못했다는 거니?”","“그건 참는 게 아니라 도망치는 거니까.”","“넌 네 마음이 불편한 상황이 생기면 무조건 네가 손해 보거나 양보하잖아.”"],"title":"「네 생각을 솔직히 말해」 신호등 앞 — 『국어』 190~191쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_challenge#4','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C61',3,'mc','auto','진우의 조언 “같은 말이라도 얼마든지 다른 느낌으로 할 수 있어.”에 담긴 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X62','K4-2-u4-X63','K4-2-u4-X60']::text[],false,'{"seq":4,"concept":"K4-2-u4-C61","difficulty":3,"kind":"mc","stem":"진우의 조언 “같은 말이라도 얼마든지 다른 느낌으로 할 수 있어.”에 담긴 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"옳은 말이라도 상대방의 기분과 입장을 생각하며 말해야 한다","correct":true},{"t":"옳은 말이면 어떻게 말해도 친구들은 떠나지 않는다","mis":"K4-2-u4-X62"},{"t":"솔직하게 말하지 말고 늘 참아야 한다","mis":"K4-2-u4-X63"},{"t":"말은 짧게 할수록 좋다","mis":"K4-2-u4-X60"}],"explanation":["진우는 서영이가 상대방의 기분은 생각하지 않고 말을 쏟아 낸다고 했어요.","그러면 아무리 옳은 말이라도 친구들이 떠날 수 있어요.","상대의 입장에서 생각하고 말하라는 뜻이에요."],"asset":{"type":"passage","lines":["“내가 보기엔 서영이 너도 좀 문제야.”","(간추림) 친구들이 좋아하는 사람은 이해를 해 주는 친구라고 했다.","“그리고 같은 말이라도 얼마든지 다른 느낌으로 할 수 있어.”","“넌 한 번이라도 상대방의 입장이 돼서 생각하고 말해 본 적 있니?”"],"title":"「네 생각을 솔직히 말해」 진우의 조언 — 『국어』 193~194쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_challenge#5','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C25',3,'error','auto','「네 생각을 솔직히 말해」를 읽고 친구들이 생각을 나누었어요. 이야기와 다르게 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X61','K4-2-u4-X63','K4-2-u4-X29']::text[],false,'{"seq":5,"concept":"K4-2-u4-C25","difficulty":3,"kind":"error","stem":"「네 생각을 솔직히 말해」를 읽고 친구들이 생각을 나누었어요. 이야기와 다르게 말한 친구는 누구인가요?","options":[{"t":"수아: 서영이는 친구를 괴롭히려고 일부러 소은이에게 상처를 준 나쁜 아이야.","correct":true,"mis_target":"K4-2-u4-X61"},{"t":"민호: 승한이는 친구들이 원하는 대로만 하다가 자기 마음을 속여 왔어.","mis":"K4-2-u4-X63"},{"t":"하린: 진우는 두 친구 모두에게 고칠 점을 알려 주었어.","mis":"K4-2-u4-X29"}],"explanation":["서영이는 놀리거나 괴롭히려는 생각이 눈곱만큼도 없었어요.","다만 상대의 입장에서 생각하지 않고 말해서 상처를 주었어요.","한 장면만 보고 인물을 나쁜 아이로 단정하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_challenge#6','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C20',3,'mc','auto','모둠에서 역할놀이로 표현할 장면을 고르려고 해요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u4-X23','K4-2-u4-X24']::text[],false,'{"seq":6,"concept":"K4-2-u4-C20","difficulty":3,"kind":"mc","stem":"모둠에서 역할놀이로 표현할 장면을 고르려고 해요. 알맞은 생각은 무엇인가요?","options":[{"t":"어떤 장면을 골라도 좋고, 그 장면을 고른 까닭을 말할 수 있으면 된다","correct":true},{"t":"선생님이 정한 장면 하나만 정답이다","mis":"K4-2-u4-X23"},{"t":"가장 웃긴 장면을 골라야 잘한 역할놀이가 된다","mis":"K4-2-u4-X24"},{"t":"이야기 맨 처음 장면만 고를 수 있다","mis":"K4-2-u4-X23"}],"explanation":["장면 카드에는 여섯 장면이 있어요.","모둠이 표현하고 싶은 장면을 까닭과 함께 골라요.","정하기 어려우면 장면 카드를 뽑아도 돼요."],"asset":{"type":"passage","lines":["① 서영이가 선물 가게에서 원하지 않는 가방을 사려는 승한이를 다그치는 장면","② 서영이와 승한이가 신호등 앞에서 다투는 장면","③ 진우가 스님과 사슴 이야기로 승한이에게 깨달음을 주는 장면","④ 진우가 서영이에게 친구 관계에 대한 조언을 하는 장면","⑤ 서영이가 소은이에게 이상한 냄새가 난다고 말하는 장면","⑥ 서영이와 승한이가 오랫동안 말없이 앉아 있는 장면"],"title":"장면 카드 — 역할놀이로 나타낼 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_challenge#7','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C22',3,'mc','auto','역할놀이를 보고 평가할 때 가장 중요하게 볼 점은 무엇인가요?',ARRAY['K4-2-u4-X24','K4-2-u4-X25']::text[],false,'{"seq":7,"concept":"K4-2-u4-C22","difficulty":3,"kind":"mc","stem":"역할놀이를 보고 평가할 때 가장 중요하게 볼 점은 무엇인가요?","options":[{"t":"인물의 말이나 행동에 대한 생각이나 느낌을 얼마나 충실히 표현했는가","correct":true},{"t":"친구들을 얼마나 크게 웃겼는가","mis":"K4-2-u4-X24"},{"t":"목소리가 얼마나 컸는가","mis":"K4-2-u4-X25"}],"explanation":["역할놀이는 웃기기 대회가 아니에요.","인물의 말과 행동을 어떻게 생각하고 느꼈는지가 드러나야 해요.","결과만 보지 않고 표현하는 과정을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_challenge#8','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C23',4,'essay','teacher','『국어』 199쪽 「자신과 관련짓기」 보기처럼 작품과 자신을 관련짓는 질문을 하나 만들고, 그 질문에 대한 자신의 답을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u4-C23","difficulty":4,"kind":"essay","stem":"『국어』 199쪽 「자신과 관련짓기」 보기처럼 작품과 자신을 관련짓는 질문을 하나 만들고, 그 질문에 대한 자신의 답을 쓰세요.","answer_guide":{"answer":"예: 질문 — 서영이처럼 일부러 그런 것이 아닌데 친구에게 상처를 준 경험이 있나요? / 답 — 친구 그림을 보고 “이상하다.”라고 말했다가 친구가 속상해한 적이 있어요. 그때 친구의 마음을 먼저 생각했어야 했어요.","scoring_points":["작품 속 인물과 이어지는 질문을 만들었는가","친구의 생각이나 경험을 알아볼 수 있는 질문인가","자신의 경험을 들어 답을 썼는가"]},"explanation":["보기에는 승한·서영·진우와 관련된 질문이 있어요.","작품에 대한 친구의 생각이나 느낌을 알아볼 수 있는 질문이 좋아요.","묻고 답하며 내가 어떻게 읽었는지 되돌아보아요."],"asset":{"type":"passage","lines":["○ 승한이와 비슷한 경험을 한 적이 있나요?","○ 자신이 서영이라면 어떻게 했을까요?","○ 자신이 진우라면 서영이에게 어떻게 말해 주었을까요?"],"title":"『국어』 199쪽 자신과 관련짓기 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_challenge#9','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C14',4,'essay','teacher','『국어』 197쪽 (1)처럼 「네 생각을 솔직히 말해」의 인물 한 명을 골라 인물의 말이나 행동을 쓰고, 그 말이나 행동에 대한 자신의 생각이나 느낌을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u4-C14","difficulty":4,"kind":"essay","stem":"『국어』 197쪽 (1)처럼 「네 생각을 솔직히 말해」의 인물 한 명을 골라 인물의 말이나 행동을 쓰고, 그 말이나 행동에 대한 자신의 생각이나 느낌을 쓰세요.","answer_guide":{"answer":"예: 인물 — 승한 / 말이나 행동 — “그, 그게……. 버지5도 좋은데 아저씨가 지금은 다 떨어졌다고 해서.” / 생각이나 느낌 — 싫다는 말을 못 해서 원하지 않던 가방을 사려고 한 모습이 안타까웠어. 불편한 상황을 피하려고 늘 양보해 온 승한이가 힘들었을 거야.","scoring_points":["인물을 한 명 골랐는가","그 인물의 말이나 행동을 이야기에서 찾아 썼는가","말이나 행동에 대한 자신의 생각이나 느낌을 까닭과 함께 썼는가"]},"explanation":["인물의 말이나 행동이 드러난 장면을 찾아요.","그 말이나 행동을 보고 든 생각이나 느낌을 써요.","인물의 성격도 함께 짐작해 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L04_challenge#10','kor',4,2,'u4','L04','tb_g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C24',4,'essay','teacher','『국어』 199쪽 「세상과 연결하기」예요. 주변에 이야기 속 인물과 비슷한 사람이 있는지 떠올려, 그 사람에게 해 주고 싶은 말을 쪽지로 쓰세요. 받는 사람이 상처받지 않게 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C24","difficulty":4,"kind":"essay","stem":"『국어』 199쪽 「세상과 연결하기」예요. 주변에 이야기 속 인물과 비슷한 사람이 있는지 떠올려, 그 사람에게 해 주고 싶은 말을 쪽지로 쓰세요. 받는 사람이 상처받지 않게 쓰세요.","answer_guide":{"answer":"예: ○○에게 / 너는 친구들 부탁을 잘 들어줘서 늘 고마워. 그런데 네가 하고 싶은 것이 있으면 나한테도 솔직하게 말해 줘. 나는 네 생각이 정말 궁금해. / △△가","scoring_points":["이야기 속 인물과 비슷한 사람을 떠올렸는가","그 사람에게 해 주고 싶은 말을 구체적으로 썼는가","받는 사람이 상처받지 않도록 배려하는 말로 썼는가"]},"explanation":["승한·서영·진우와 닮은 사람을 떠올려요.","“너는 ~하잖아.” 대신 “나는 ~라고 생각해.”처럼 써요.","받는 사람의 마음을 생각하며 쪽지를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_basic#1','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C27',1,'mc','auto','『국어』 200쪽 1번이에요. 보기 가운데 읽기 전에 할 수 있는 활동을 모두 고른 것은 무엇인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":1,"concept":"K4-2-u4-C27","difficulty":1,"kind":"mc","stem":"『국어』 200쪽 1번이에요. 보기 가운데 읽기 전에 할 수 있는 활동을 모두 고른 것은 무엇인가요?","options":[{"t":"㉮, ㉲","correct":true},{"t":"㉮, ㉴","mis":"K4-2-u4-X30"},{"t":"㉲, ㉰","mis":"K4-2-u4-X30"},{"t":"㉱, ㉰","mis":"K4-2-u4-X30"}],"explanation":["읽기 전에는 아직 글을 읽지 않았어요.","제목이나 차례를 보며 예상하고(㉮), 알고 있는 내용을 떠올려요(㉲).","㉴는 읽기 중, ㉱·㉰는 읽기 후 활동이에요."],"asset":{"type":"passage","lines":["㉮ 제목이나 차례를 보며 내용 예상하기","㉯ 각 부분의 중심 내용 파악하기","㉰ 더 알고 싶은 내용 생각하기","㉱ 글 전체의 내용을 요약하여 정리하기","㉲ 자신이 알고 있는 내용 떠올리기","㉳ 글의 중심 생각 파악하기","㉴ 짐작한 내용이 맞는지 확인하기","㉵ 새롭게 안 내용 파악하기"],"title":"『국어』 200쪽 1번 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_basic#2','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C29',1,'mc','auto','『국어』 200쪽 1번 보기 가운데 읽기 후에 할 수 있는 활동을 모두 고른 것은 무엇인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":2,"concept":"K4-2-u4-C29","difficulty":1,"kind":"mc","stem":"『국어』 200쪽 1번 보기 가운데 읽기 후에 할 수 있는 활동을 모두 고른 것은 무엇인가요?","options":[{"t":"㉱, ㉰","correct":true},{"t":"㉮, ㉲","mis":"K4-2-u4-X30"},{"t":"㉳, ㉵","mis":"K4-2-u4-X30"},{"t":"㉯, ㉴","mis":"K4-2-u4-X30"}],"explanation":["읽기 후에는 글을 끝까지 다 읽었어요.","글 전체를 요약하여 정리하고(㉱), 더 알고 싶은 내용을 생각해요(㉰).","나머지는 읽기 전이나 읽기 중 활동이에요."],"asset":{"type":"passage","lines":["㉮ 제목이나 차례를 보며 내용 예상하기","㉯ 각 부분의 중심 내용 파악하기","㉰ 더 알고 싶은 내용 생각하기","㉱ 글 전체의 내용을 요약하여 정리하기","㉲ 자신이 알고 있는 내용 떠올리기","㉳ 글의 중심 생각 파악하기","㉴ 짐작한 내용이 맞는지 확인하기","㉵ 새롭게 안 내용 파악하기"],"title":"『국어』 200쪽 1번 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_basic#3','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C63',1,'mc','auto','『국어』 202쪽 3번이에요. 화살나무라는 이름이 붙은 까닭은 무엇인가요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":3,"concept":"K4-2-u4-C63","difficulty":1,"kind":"mc","stem":"『국어』 202쪽 3번이에요. 화살나무라는 이름이 붙은 까닭은 무엇인가요?","options":[{"t":"나뭇가지에 화살의 날개처럼 생긴 것이 달려 있기 때문","correct":true},{"t":"화살을 만들 때 쓰는 나무이기 때문","mis":"K4-2-u4-X35"},{"t":"꽃이 화살처럼 뾰족하게 생겼기 때문","mis":"K4-2-u4-X35"},{"t":"열매가 화살처럼 멀리 날아가기 때문","mis":"K4-2-u4-X35"}],"explanation":["글쓴이는 이름의 까닭을 가지를 보면 알 수 있다고 했어요.","가지에 코르크 재질의 날개처럼 생긴 것이 있어요.","그 모습이 화살의 날개처럼 생겨서 화살나무예요."],"asset":{"type":"passage","lines":["(간추림) 가지에 코르크 재질의 날개처럼 생긴 것이 2~4줄 보인다.","(간추림) 그 모습이 화살의 날개처럼 생겨서 화살나무라는 이름이 붙었다.","(간추림) 키 작은 떨기나무로, 꽃은 정말 작고 황록색이라 눈에 잘 띄지 않는다.","(간추림) 꽃받침과 꽃잎이 4장씩, 수술이 4개 있다.","(간추림) 가을에 붉게 단풍이 들고, 잎이 진 뒤 빨간 열매가 보인다."],"title":"「화살나무를 아시나요?」 둘째 문단 — 『국어』 201쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_basic#4','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C63',1,'mc','auto','화살나무는 어디어디에 사용되나요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":4,"concept":"K4-2-u4-C63","difficulty":1,"kind":"mc","stem":"화살나무는 어디어디에 사용되나요?","options":[{"t":"먹거리와 약재, 고약의 원료","correct":true},{"t":"화살과 활을 만드는 재료","mis":"K4-2-u4-X35"},{"t":"집을 짓는 기둥과 가구","mis":"K4-2-u4-X35"},{"t":"종이와 연필의 원료","mis":"K4-2-u4-X35"}],"explanation":["새순은 무치거나 국에 넣거나 나물밥을 해 먹어요.","봄에 채취해 말린 뒤 약재로도 썼어요.","날개와 열매는 고약의 원료로 썼어요."],"asset":{"type":"passage","lines":["화살나무는 예부터 많은 먹거리를 제공해 왔습니다.","(간추림) 새순을 무쳐 먹거나 된장국에 넣거나 나물밥을 해 먹을 수 있다.","(간추림) 봄에 채취하여 말린 뒤 약재로도 썼다.","(간추림) 고약의 원료로 화살나무의 날개와 열매를 사용했다.","[낱말] 새순 — 새로 돋아나는 순. 새싹.","[낱말] 고약 — 주로 헐거나 곪은 데 붙이는 끈끈한 약."],"title":"「화살나무를 아시나요?」 셋째 문단 — 『국어』 201쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_basic#5','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C28',2,'mc','auto','『국어』 200쪽 1번 보기 가운데 읽기 중에 하는 활동이 아닌 것은 무엇인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":5,"concept":"K4-2-u4-C28","difficulty":2,"kind":"mc","stem":"『국어』 200쪽 1번 보기 가운데 읽기 중에 하는 활동이 아닌 것은 무엇인가요?","options":[{"t":"㉰ 더 알고 싶은 내용 생각하기","correct":true},{"t":"㉳ 글의 중심 생각 파악하기","mis":"K4-2-u4-X30"},{"t":"㉴ 짐작한 내용이 맞는지 확인하기","mis":"K4-2-u4-X30"},{"t":"㉵ 새롭게 안 내용 파악하기","mis":"K4-2-u4-X30"}],"explanation":["읽기 중에는 짐작한 내용이 맞는지 확인해요.","중심 내용과 중심 생각, 새롭게 안 내용을 파악하며 읽어요.","더 알고 싶은 내용은 다 읽은 뒤에 생각해요."],"asset":{"type":"passage","lines":["㉮ 제목이나 차례를 보며 내용 예상하기","㉯ 각 부분의 중심 내용 파악하기","㉰ 더 알고 싶은 내용 생각하기","㉱ 글 전체의 내용을 요약하여 정리하기","㉲ 자신이 알고 있는 내용 떠올리기","㉳ 글의 중심 생각 파악하기","㉴ 짐작한 내용이 맞는지 확인하기","㉵ 새롭게 안 내용 파악하기"],"title":"『국어』 200쪽 1번 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_basic#6','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C30',2,'blank','auto','『국어』 202쪽 4번 표예요. ㉠에 붙일 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X32']::text[],false,'{"seq":6,"concept":"K4-2-u4-C30","difficulty":2,"kind":"blank","stem":"『국어』 202쪽 4번 표예요. ㉠에 붙일 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"이 주제에 대해 알고 있는 것을 떠올렸나요?","correct":true},{"t":"읽은 내용을 요약했나요?","mis":"K4-2-u4-X31"},{"t":"새롭게 안 내용을 찾으며 읽었나요?","mis":"K4-2-u4-X31"},{"t":"이 책은 모두 몇 쪽인가요?","mis":"K4-2-u4-X32"}],"explanation":["㉠은 읽기 전의 ‘알고 있는 내용 떠올리기’ 칸이에요.","그 활동을 했는지 묻는 질문을 붙여요.","요약은 읽기 후, 새롭게 안 내용은 읽기 중 질문이에요."],"asset":{"type":"passage","lines":["[읽기 전] 내용 예상하기 — 제목이나 차례를 보며 내용을 예상했나요?","[읽기 전] 알고 있는 내용 떠올리기 — (     ㉠     )","[읽기 중] 예상한 내용 확인하기 — (     ㉡     )","[읽기 중] 중심 내용 파악하기 — 글의 중심 내용을 찾으며 읽었나요?","[읽기 중] 중심 생각 파악하기 — (     ㉢     )","[읽기 중] 새롭게 안 내용 파악하기 — 새롭게 안 내용을 찾으며 읽었나요?","[읽기 후] 요약하여 정리하기 — (     ㉣     )","[읽기 후] 더 알고 싶은 내용 생각하기 — 더 알고 싶은 내용을 생각했나요?"],"title":"『국어』 202쪽 4번 — 읽기 과정을 되돌아볼 수 있는 질문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_basic#7','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C30',2,'blank','auto','『국어』 202쪽 4번 표의 ㉣에 붙일 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X32']::text[],false,'{"seq":7,"concept":"K4-2-u4-C30","difficulty":2,"kind":"blank","stem":"『국어』 202쪽 4번 표의 ㉣에 붙일 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"읽은 내용을 요약했나요?","correct":true},{"t":"제목이나 차례를 보며 내용을 예상했나요?","mis":"K4-2-u4-X31"},{"t":"자신이 예상한 내용이 맞는지 확인했나요?","mis":"K4-2-u4-X31"},{"t":"글을 다 읽는 데 몇 분 걸렸나요?","mis":"K4-2-u4-X32"}],"explanation":["㉣은 읽기 후의 ‘요약하여 정리하기’ 칸이에요.","글 전체의 내용을 요약했는지 물어요.","걸린 시간은 읽기 과정을 되돌아보는 질문이 아니에요."],"asset":{"type":"passage","lines":["[읽기 전] 내용 예상하기 — 제목이나 차례를 보며 내용을 예상했나요?","[읽기 전] 알고 있는 내용 떠올리기 — (     ㉠     )","[읽기 중] 예상한 내용 확인하기 — (     ㉡     )","[읽기 중] 중심 내용 파악하기 — 글의 중심 내용을 찾으며 읽었나요?","[읽기 중] 중심 생각 파악하기 — (     ㉢     )","[읽기 중] 새롭게 안 내용 파악하기 — 새롭게 안 내용을 찾으며 읽었나요?","[읽기 후] 요약하여 정리하기 — (     ㉣     )","[읽기 후] 더 알고 싶은 내용 생각하기 — 더 알고 싶은 내용을 생각했나요?"],"title":"『국어』 202쪽 4번 — 읽기 과정을 되돌아볼 수 있는 질문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_basic#8','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C63',2,'sa','auto','「화살나무를 아시나요?」에서 화살나무 꽃의 색은 무엇이라고 했나요?','{}'::text[],false,'{"seq":8,"concept":"K4-2-u4-C63","difficulty":2,"kind":"sa","stem":"「화살나무를 아시나요?」에서 화살나무 꽃의 색은 무엇이라고 했나요?","answer":["황록색"],"explanation":["둘째 문단에서 꽃에 대해 설명했어요.","꽃은 정말 작고 색도 황록색이라고 했어요.","그래서 눈에 잘 들어오지 않는다고 했어요."],"mis":"K4-2-u4-X35"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_basic#9','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C26',2,'ox','auto','읽기 과정은 읽기 전, 읽기 중, 읽기 후로 나눌 수 있고 과정마다 알맞은 활동이 있어요.',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":9,"concept":"K4-2-u4-C26","difficulty":2,"kind":"ox","stem":"읽기 과정은 읽기 전, 읽기 중, 읽기 후로 나눌 수 있고 과정마다 알맞은 활동이 있어요.","answer":"O","reason_options":[{"t":"읽기 전에는 예상하기, 읽기 중에는 중심 내용 파악하기, 읽기 후에는 요약하기처럼 하는 일이 달라요.","correct":true},{"t":"읽기 과정은 나누지 않고 언제나 같은 활동만 해요.","mis":"K4-2-u4-X30"}],"mis":"K4-2-u4-X30","explanation":["글을 펴기 전, 읽는 동안, 다 읽은 뒤로 나누어 보아요.","과정마다 하기 좋은 활동이 있어요.","알맞은 활동을 하면 글을 더 잘 이해할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_basic#10','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C33',3,'mc','auto','『국어』 203쪽 「글의 종류에 따라 읽기 전, 중, 후의 활동과 질문은 달라질 수 있어요.」와 같은 뜻의 생각은 무엇인가요?',ARRAY['K4-2-u4-X07','K4-2-u4-X06','K4-2-u4-X05']::text[],false,'{"seq":10,"concept":"K4-2-u4-C33","difficulty":3,"kind":"mc","stem":"『국어』 203쪽 「글의 종류에 따라 읽기 전, 중, 후의 활동과 질문은 달라질 수 있어요.」와 같은 뜻의 생각은 무엇인가요?","options":[{"t":"글의 특성, 읽는 목적, 읽기 상황에 따라 알맞은 활동과 질문을 골라 쓴다","correct":true},{"t":"어떤 글이든 여덟 가지 활동을 빠짐없이 다 해야 한다","mis":"K4-2-u4-X07"},{"t":"질문은 많이 만들수록 잘 읽은 것이다","mis":"K4-2-u4-X06"},{"t":"읽기 과정 질문은 설명하는 글에만 쓴다","mis":"K4-2-u4-X05"}],"explanation":["『국어』에 나온 활동은 예시예요.","글의 특성과 읽는 목적에 따라 활동이 달라질 수 있어요.","그때그때 알맞은 것을 스스로 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_challenge#1','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C28',2,'mc','auto','「화살나무를 아시나요?」를 읽으며 중요한 내용이나 새롭게 안 내용에 밑줄을 그었어요. 어느 과정의 활동인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":1,"concept":"K4-2-u4-C28","difficulty":2,"kind":"mc","stem":"「화살나무를 아시나요?」를 읽으며 중요한 내용이나 새롭게 안 내용에 밑줄을 그었어요. 어느 과정의 활동인가요?","options":[{"t":"읽기 중","correct":true},{"t":"읽기 전","mis":"K4-2-u4-X30"},{"t":"읽기 후","mis":"K4-2-u4-X30"}],"explanation":["밑줄은 글을 읽는 동안 그어요.","중요한 내용과 새롭게 안 내용을 파악하는 활동이에요.","그래서 읽기 중 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_challenge#2','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C30',2,'blank','auto','『국어』 202쪽 4번 표의 ㉢에 붙일 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X32']::text[],false,'{"seq":2,"concept":"K4-2-u4-C30","difficulty":2,"kind":"blank","stem":"『국어』 202쪽 4번 표의 ㉢에 붙일 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"글을 통해 글쓴이가 전하려는 생각을 파악하며 읽었나요?","correct":true},{"t":"더 알고 싶은 내용을 생각했나요?","mis":"K4-2-u4-X31"},{"t":"제목이나 차례를 보며 내용을 예상했나요?","mis":"K4-2-u4-X31"},{"t":"글쓴이는 몇 살인가요?","mis":"K4-2-u4-X32"}],"explanation":["㉢은 읽기 중의 ‘글의 중심 생각 파악하기’ 칸이에요.","글쓴이가 전하려는 생각을 파악했는지 물어요.","글쓴이의 나이는 읽기 과정과 상관없어요."],"asset":{"type":"passage","lines":["[읽기 전] 내용 예상하기 — 제목이나 차례를 보며 내용을 예상했나요?","[읽기 전] 알고 있는 내용 떠올리기 — (     ㉠     )","[읽기 중] 예상한 내용 확인하기 — (     ㉡     )","[읽기 중] 중심 내용 파악하기 — 글의 중심 내용을 찾으며 읽었나요?","[읽기 중] 중심 생각 파악하기 — (     ㉢     )","[읽기 중] 새롭게 안 내용 파악하기 — 새롭게 안 내용을 찾으며 읽었나요?","[읽기 후] 요약하여 정리하기 — (     ㉣     )","[읽기 후] 더 알고 싶은 내용 생각하기 — 더 알고 싶은 내용을 생각했나요?"],"title":"『국어』 202쪽 4번 — 읽기 과정을 되돌아볼 수 있는 질문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_challenge#3','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C30',3,'match','auto','『국어』 203쪽 5번 예시 질문과 읽기 과정을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u4-C30","difficulty":3,"kind":"match","stem":"『국어』 203쪽 5번 예시 질문과 읽기 과정을 알맞게 이으세요.","pairs":[{"l":"‘화살나무를 아시나요?’라는 제목을 보고 어떤 내용일지 예상했나요?","r":"읽기 전"},{"l":"화살나무에 대해 새롭게 안 내용을 찾으며 읽었나요?","r":"읽기 중"},{"l":"화살나무에 대해 더 알고 싶은 내용을 떠올렸나요?","r":"읽기 후"}],"mis":"K4-2-u4-X31","explanation":["제목을 보고 예상하는 것은 읽기 전이에요.","새롭게 안 내용을 찾는 것은 읽는 동안이에요.","더 알고 싶은 내용은 다 읽은 뒤에 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_challenge#4','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C30',3,'mc','auto','다음 가운데 「화살나무를 아시나요?」를 읽기 전에는 답할 수 없고, 끝까지 읽어야 답할 수 있는 질문은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X32']::text[],false,'{"seq":4,"concept":"K4-2-u4-C30","difficulty":3,"kind":"mc","stem":"다음 가운데 「화살나무를 아시나요?」를 읽기 전에는 답할 수 없고, 끝까지 읽어야 답할 수 있는 질문은 무엇인가요?","options":[{"t":"화살나무의 특징을 비롯해서 중요한 내용을 요약했나요?","correct":true},{"t":"제목을 보고 어떤 내용일지 예상했나요?","mis":"K4-2-u4-X31"},{"t":"화살나무에 대해 알고 있는 것을 생각했나요?","mis":"K4-2-u4-X31"},{"t":"이 글을 읽을 때 연필을 썼나요?","mis":"K4-2-u4-X32"}],"explanation":["요약은 글 전체를 읽어야 할 수 있어요.","예상하기와 알고 있는 것 떠올리기는 읽기 전에도 할 수 있어요.","연필을 썼는지는 읽기 과정과 상관없는 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_challenge#5','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C63',3,'mc','auto','「화살나무를 아시나요?」의 내용으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":5,"concept":"K4-2-u4-C63","difficulty":3,"kind":"mc","stem":"「화살나무를 아시나요?」의 내용으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"화살나무 꽃은 크고 색이 화려해서 눈에 잘 띈다","correct":true},{"t":"가을에 붉게 단풍이 들었을 때 무척 예쁘다","mis":"K4-2-u4-X35"},{"t":"꽃받침과 꽃잎이 4장씩 있고 수술도 4개 있다","mis":"K4-2-u4-X35"},{"t":"새순을 무쳐 먹거나 된장국에 넣어 먹을 수 있다","mis":"K4-2-u4-X35"}],"explanation":["글쓴이는 화살나무 꽃이 정말로 작다고 했어요.","꽃 색도 황록색이라 눈에 잘 들어오지 않는다고 했어요.","글에서 다시 찾아 확인하는 습관을 들여요."],"asset":{"type":"passage","lines":["(간추림) 가지에 코르크 재질의 날개처럼 생긴 것이 2~4줄 보인다.","(간추림) 그 모습이 화살의 날개처럼 생겨서 화살나무라는 이름이 붙었다.","(간추림) 키 작은 떨기나무로, 꽃은 정말 작고 황록색이라 눈에 잘 띄지 않는다.","(간추림) 꽃받침과 꽃잎이 4장씩, 수술이 4개 있다.","(간추림) 가을에 붉게 단풍이 들고, 잎이 진 뒤 빨간 열매가 보인다."],"title":"「화살나무를 아시나요?」 둘째 문단 — 『국어』 201쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_challenge#6','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C63',3,'mc','auto','「봄에 채취하여 말린 뒤 약재로도 썼다고 해요.」에서 ‘채취하다’의 뜻은 무엇인가요?',ARRAY['K4-2-u4-X70']::text[],false,'{"seq":6,"concept":"K4-2-u4-C63","difficulty":3,"kind":"mc","stem":"「봄에 채취하여 말린 뒤 약재로도 썼다고 해요.」에서 ‘채취하다’의 뜻은 무엇인가요?","options":[{"t":"풀, 나무, 광석 따위를 찾아 베거나 캐거나 하여 얻어 내다","correct":true},{"t":"주로 헐거나 곪은 데 붙이는 끈끈한 약을 만들다","mis":"K4-2-u4-X70"},{"t":"새로 돋아나는 순이 나다","mis":"K4-2-u4-X70"}],"explanation":["『국어』 201쪽 낱말 풀이를 보아요.","봄에 화살나무를 베거나 캐어서 얻어 낸다는 뜻이에요.","고약·새순은 다른 낱말의 뜻이에요."],"asset":{"type":"passage","lines":["화살나무는 예부터 많은 먹거리를 제공해 왔습니다.","(간추림) 새순을 무쳐 먹거나 된장국에 넣거나 나물밥을 해 먹을 수 있다.","(간추림) 봄에 채취하여 말린 뒤 약재로도 썼다.","(간추림) 고약의 원료로 화살나무의 날개와 열매를 사용했다.","[낱말] 새순 — 새로 돋아나는 순. 새싹.","[낱말] 고약 — 주로 헐거나 곪은 데 붙이는 끈끈한 약."],"title":"「화살나무를 아시나요?」 셋째 문단 — 『국어』 201쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_challenge#7','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C4',3,'mc','auto','읽기 습관 ○ × 퀴즈에서 「책을 읽다가 앞부분으로 다시 돌아간 적이 있다.」에 ○ 표를 했어요. 이런 퀴즈를 하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X51','K4-2-u4-X02']::text[],false,'{"seq":7,"concept":"K4-2-u4-C4","difficulty":3,"kind":"mc","stem":"읽기 습관 ○ × 퀴즈에서 「책을 읽다가 앞부분으로 다시 돌아간 적이 있다.」에 ○ 표를 했어요. 이런 퀴즈를 하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"글을 읽을 때 어떤 생각이나 행동을 하는지 되짚어 보고, 스스로 점검하는 질문이 필요함을 알기 위해","correct":true},{"t":"○ 표를 많이 한 사람이 이기는 놀이라서","mis":"K4-2-u4-X51"},{"t":"앞부분으로 돌아가는 것은 잘못 읽은 것이라 고치려고","mis":"K4-2-u4-X02"},{"t":"책을 가장 빨리 읽는 사람을 뽑으려고","mis":"K4-2-u4-X02"}],"explanation":["퀴즈에 답하며 자신의 읽기 습관을 돌아보아요.","왜 앞으로 다시 돌아갔는지 까닭도 말해 보아요.","그러면서 스스로 점검하는 질문이 필요하다는 것을 알게 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_challenge#8','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C30',4,'essay','teacher','『국어』 203쪽 5번이에요. 「화살나무를 아시나요?」에 맞게 읽기 전, 읽기 중, 읽기 후를 되돌아볼 수 있는 질문을 하나씩 만들어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u4-C30","difficulty":4,"kind":"essay","stem":"『국어』 203쪽 5번이에요. 「화살나무를 아시나요?」에 맞게 읽기 전, 읽기 중, 읽기 후를 되돌아볼 수 있는 질문을 하나씩 만들어 쓰세요.","answer_guide":{"answer":"예: 읽기 전 — 화살나무에 대해 알고 있는 것을 생각했나요? / 읽기 중 — 화살나무라는 이름이 붙은 까닭을 찾으며 읽었나요? / 읽기 후 — 화살나무에 대해 더 알고 싶은 내용을 떠올렸나요?","scoring_points":["읽기 전·중·후 질문을 하나씩 썼는가","각 질문이 그 과정에 알맞은가","「화살나무를 아시나요?」 내용과 이어지는 질문인가"]},"explanation":["읽기 전 질문은 제목만 보고도 답할 수 있어요.","읽기 중 질문은 읽으면서 확인하는 것이에요.","읽기 후 질문은 다 읽고 나서 정리하거나 더 알고 싶은 것을 묻는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_challenge#9','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C33',4,'essay','teacher','『국어』에서 제시한 읽기 과정 활동은 예시예요. 읽는 목적이나 글의 종류에 따라 활동이 달라지는 예를 하나 들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u4-C33","difficulty":4,"kind":"essay","stem":"『국어』에서 제시한 읽기 과정 활동은 예시예요. 읽는 목적이나 글의 종류에 따라 활동이 달라지는 예를 하나 들어 쓰세요.","answer_guide":{"answer":"예: 화살나무 이름의 까닭만 빨리 알고 싶을 때에는 모든 활동을 다 하지 않고, 제목을 보고 예상한 뒤 이름이 나온 부분을 찾아 읽으며 예상과 같은지 확인한다. 시를 읽을 때에는 중심 생각보다 마음에 남는 표현이나 장면을 떠올리며 읽는다.","scoring_points":["읽는 목적이나 글의 종류를 밝혔는가","그에 맞게 고른 활동을 썼는가","활동을 매번 모두 하는 것이 아니라 골라 쓴다는 생각이 드러나는가"]},"explanation":["『국어』의 활동은 예시라서 상황에 따라 달라질 수 있어요.","왜 읽는지, 어떤 글인지 먼저 생각해요.","그때그때 알맞은 활동을 스스로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L07_challenge#10','kor',4,2,'u4','L07','tb_g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C29',4,'essay','teacher','『국어』 203쪽 6번처럼 「화살나무를 아시나요?」를 다시 읽고, 글 전체의 내용을 두세 문장으로 요약하세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C29","difficulty":4,"kind":"essay","stem":"『국어』 203쪽 6번처럼 「화살나무를 아시나요?」를 다시 읽고, 글 전체의 내용을 두세 문장으로 요약하세요.","answer_guide":{"answer":"예: 화살나무는 가지에 화살의 날개처럼 생긴 것이 있어 이름이 붙었다. 꽃은 작고 황록색이지만 가을의 붉은 단풍과 빨간 열매가 예쁘다. 새순은 먹거리로, 날개와 열매는 약재와 고약의 원료로 쓰였다.","scoring_points":["각 문단의 중심 내용이 들어갔는가","두세 문장으로 짧게 정리했는가","글에 없는 내용을 지어 쓰지 않았는가"]},"explanation":["문단마다 중심 내용을 하나씩 찾아요.","찾은 중심 내용을 이어 짧게 써요.","모든 문장을 옮겨 적지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_basic#1','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C34',1,'mc','auto','『국어』 204쪽에서 설명하는 글을 무엇이라고 했나요?',ARRAY['K4-2-u4-X34','K4-2-u4-X05']::text[],false,'{"seq":1,"concept":"K4-2-u4-C34","difficulty":1,"kind":"mc","stem":"『국어』 204쪽에서 설명하는 글을 무엇이라고 했나요?","options":[{"t":"어떤 지식이나 정보를 이해하기 쉽게 객관적으로 전달하는 글","correct":true},{"t":"겪은 일과 그때의 느낌을 쓴 글","mis":"K4-2-u4-X34"},{"t":"어떤 문제에 대해 자신의 주장을 밝혀 쓴 글","mis":"K4-2-u4-X05"},{"t":"짧은 줄에 말의 재미를 살려 쓴 글","mis":"K4-2-u4-X34"}],"explanation":["설명하는 글은 지식이나 정보를 전달해요.","읽는 사람이 이해하기 쉽게, 객관적으로 써요.","주장을 밝혀 쓴 글은 의견을 제시하는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_basic#2','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C34',1,'mc','auto','『국어』 204쪽 경험 떠올리기 ㉮~㉰에서 친구들이 읽은 글의 공통점은 무엇인가요?',ARRAY['K4-2-u4-X34','K4-2-u4-X05']::text[],false,'{"seq":2,"concept":"K4-2-u4-C34","difficulty":1,"kind":"mc","stem":"『국어』 204쪽 경험 떠올리기 ㉮~㉰에서 친구들이 읽은 글의 공통점은 무엇인가요?","options":[{"t":"모두 설명하는 글이다","correct":true},{"t":"모두 시다","mis":"K4-2-u4-X34"},{"t":"모두 의견을 제시하는 글이다","mis":"K4-2-u4-X05"},{"t":"모두 일기다","mis":"K4-2-u4-X34"}],"explanation":["조립 설명서, 동물에 대해 알려 주는 책, 조리법을 읽었어요.","모두 알고 싶은 지식이나 정보를 전해 주는 글이에요.","그래서 모두 설명하는 글이에요."],"asset":{"type":"speech","turns":[{"who":"㉮","text":"“장난감을 조립할 때 설명서를 읽었어.”"},{"who":"㉯","text":"“멸종 위기 동물에 대해 알고 싶어서 책을 읽었어.”"},{"who":"㉰","text":"“음식 만드는 방법을 알고 싶어서 조리법을 찾아 읽었어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_basic#3','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C64',1,'mc','auto','『국어』 208쪽 내용 알기예요. 더 이상 쓰지 않는 약을 처리하는 방법은 무엇인가요?',ARRAY['K4-2-u4-X71']::text[],false,'{"seq":3,"concept":"K4-2-u4-C64","difficulty":1,"kind":"mc","stem":"『국어』 208쪽 내용 알기예요. 더 이상 쓰지 않는 약을 처리하는 방법은 무엇인가요?","options":[{"t":"폐의약품 수거함에 넣는다","correct":true},{"t":"쓰레기통에 버린다","mis":"K4-2-u4-X71"},{"t":"하수구에 흘려보낸다","mis":"K4-2-u4-X71"},{"t":"두었다가 비슷한 증상이 생기면 먹는다","mis":"K4-2-u4-X71"}],"explanation":["보건소와 대부분의 약국에 폐의약품 수거함이 있어요.","쓰지 않는 약을 넣으면 모아서 따로 버려 줘요.","아무 곳에나 버리면 환경을 오염시켜요."],"asset":{"type":"passage","lines":["약을 잘 쓰고 잘 버리는 건 우리 자신의 건강을 위해서뿐만 아니라","다른 사람들, 다른 생물들, 또 우리 후손의 건강을 위해서도 중요한 일이에요.","(간추림) 보건소와 대부분의 약국에는 폐의약품 수거함이 비치되어 있다.","(간추림) 더 이상 쓰지 않는 약을 넣으면 모아서 따로 버려 준다."],"title":"「약, 잘 쓰고 잘 버리는 방법」(김선 글) — 『국어』 204~205쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_basic#4','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C64',1,'mc','auto','약의 소비 기한을 살펴봐야 하는 까닭은 무엇인가요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":4,"concept":"K4-2-u4-C64","difficulty":1,"kind":"mc","stem":"약의 소비 기한을 살펴봐야 하는 까닭은 무엇인가요?","options":[{"t":"소비 기한이 지난 약은 약효가 떨어지고 상할 수 있기 때문","correct":true},{"t":"소비 기한이 지나면 약효가 더 좋아지기 때문","mis":"K4-2-u4-X35"},{"t":"상자에 적힌 숫자를 외워야 하기 때문","mis":"K4-2-u4-X35"},{"t":"약에는 소비 기한이 없기 때문","mis":"K4-2-u4-X35"}],"explanation":["약도 우유나 빵처럼 소비 기한이 있어요.","소비 기한이 지나면 약효가 떨어지고 상할 수도 있어요.","그래서 상자와 설명서를 함께 보관해요."],"asset":{"type":"passage","lines":["약도 우유나 빵처럼 소비 기한이 있다는 사실, 알고 있나요?","(간추림) 소비 기한이 지나면 약효가 떨어질 뿐 아니라 상할 수도 있다.","(간추림) 약은 반드시 상자와 사용 설명서를 함께 보관해야 한다.","(간추림) 설명서에 적힌 보관법대로 보관해야 한다.","(간추림) 소비 기한은 적절하게 보관했을 경우에 적용된다."],"title":"「약, 잘 쓰고 잘 버리는 방법」 보관하기 — 『국어』 205쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_basic#5','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C64',2,'mc','auto','약을 잘 쓰고 잘 버려야 하는 까닭은 무엇인가요?',ARRAY['K4-2-u4-X71','K4-2-u4-X35']::text[],false,'{"seq":5,"concept":"K4-2-u4-C64","difficulty":2,"kind":"mc","stem":"약을 잘 쓰고 잘 버려야 하는 까닭은 무엇인가요?","options":[{"t":"함부로 버린 약이 환경을 오염시키고 생물들에게 안 좋은 영향을 주기 때문","correct":true},{"t":"쓰레기통에 버리면 약이 바로 사라지기 때문","mis":"K4-2-u4-X71"},{"t":"약을 버리면 돈을 받을 수 있기 때문","mis":"K4-2-u4-X35"},{"t":"약은 물고기에게 좋은 먹이가 되기 때문","mis":"K4-2-u4-X35"}],"explanation":["버린 약은 땅에 묻히거나 강으로 흘러 들어가요.","생물들의 번식에 영향을 주고 물고기들이 먹을 수도 있어요.","결국 우리 모두의 건강과 환경의 문제예요."],"asset":{"type":"passage","lines":["(간추림) 버린 쓰레기는 땅에 묻히거나 하수구를 통해 강으로 흘러간다.","(간추림) 항생제나 성호르몬이 든 약은 생물들의 번식에 영향을 줄 수 있다.","쓰레기통에 버린다고 해서 약이 사라지는 건 아니에요.","(간추림) 과학자들은 버려진 약이 사람에게 어떤 영향을 미칠지 모른다고 경고한다."],"title":"「약, 잘 쓰고 잘 버리는 방법」 버려진 약 — 『국어』 206쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_basic#6','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C65',2,'blank','auto','『국어』 208쪽 낱말 알기예요. ㉠ 「약을 먹으려고 약상자를 (     )했다.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K4-2-u4-X70']::text[],false,'{"seq":6,"concept":"K4-2-u4-C65","difficulty":2,"kind":"blank","stem":"『국어』 208쪽 낱말 알기예요. ㉠ 「약을 먹으려고 약상자를 (     )했다.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"개봉","correct":true},{"t":"처방","mis":"K4-2-u4-X70"},{"t":"터득","mis":"K4-2-u4-X70"},{"t":"수거","mis":"K4-2-u4-X70"}],"explanation":["뜻풀이는 「열지 못하게 붙여 두었던 것을 떼거나 엶.」이에요.","약상자를 연다는 뜻이에요.","퍼즐 첫째 줄에서 ‘개봉’을 찾을 수 있어요."],"asset":{"type":"passage","lines":["보기 — 병원에서 감기약 ( 처방 )을 받았다.","처방: 치료하는 데 필요한 의약품이나 방법 따위를 적은 문서.","㉠ 약을 먹으려고 약상자를 (     )했다. — 열지 못하게 붙여 두었던 것을 떼거나 엶.","㉡ 병균을 물리치는 방법을 (     )했다. — 깊이 생각해 이치를 깨달아 알아냄.","㉢ 재활용품은 일반 쓰레기와 분리해 (     )해야 한다. — 거두어 감.","[낱말 퍼즐] 처 개 봉 로 / 방 프 수 니 / 터 득 거 해 (가로세로로만 찾아요)"],"title":"『국어』 208쪽 낱말 알기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_basic#7','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C37',2,'mc','auto','설명하는 글을 읽을 때 각 문단의 중심 문장에 밑줄을 그으며 읽으면 좋은 까닭은 무엇인가요?',ARRAY['K4-2-u4-X37','K4-2-u4-X06']::text[],false,'{"seq":7,"concept":"K4-2-u4-C37","difficulty":2,"kind":"mc","stem":"설명하는 글을 읽을 때 각 문단의 중심 문장에 밑줄을 그으며 읽으면 좋은 까닭은 무엇인가요?","options":[{"t":"중심 문장을 찾으면 글 전체의 내용을 이해하는 데 도움이 되기 때문","correct":true},{"t":"문단의 첫 문장에만 밑줄을 그으면 되기 때문","mis":"K4-2-u4-X37"},{"t":"가장 긴 문장이 늘 중심 문장이기 때문","mis":"K4-2-u4-X37"},{"t":"밑줄을 많이 그을수록 잘 읽은 것이기 때문","mis":"K4-2-u4-X06"}],"explanation":["설명하는 글에서는 중심 내용을 파악하는 것이 중요해요.","중심 문장을 찾으면 전체 내용을 이해하기 쉬워요.","첫 문장이나 긴 문장이 늘 중심 문장인 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_basic#8','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C30',2,'blank','auto','『국어』 209쪽이에요. 읽기 전 ㉠에 붙일 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X32']::text[],false,'{"seq":8,"concept":"K4-2-u4-C30","difficulty":2,"kind":"blank","stem":"『국어』 209쪽이에요. 읽기 전 ㉠에 붙일 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"글을 읽기 전에 제목을 보고 어떤 내용일지 예상했나요?","correct":true},{"t":"읽은 내용을 요약했나요?","mis":"K4-2-u4-X31"},{"t":"새롭게 안 내용을 찾으며 읽었나요?","mis":"K4-2-u4-X31"},{"t":"약국은 어디에 있나요?","mis":"K4-2-u4-X32"}],"explanation":["읽기 전에는 제목을 보고 내용을 예상해요.","그다음 칸이 알고 있는 내용 떠올리기예요.","약국 위치는 읽기 과정을 되돌아보는 질문이 아니에요."],"asset":{"type":"passage","lines":["[읽기 전] (     ㉠     )","[읽기 전] 글을 읽기 전에 제목을 보고 자신이 알고 있는 내용을 떠올렸나요?","[읽기 중] 자신이 예상한 내용이 글의 내용과 같은지 확인했나요?","[읽기 중] 글의 중심 내용을 찾으며 읽었나요?","[읽기 중] 새롭게 안 내용을 찾으며 읽었나요?","[읽기 후] (     ㉡     )","[읽기 후] 더 알고 싶은 내용을 생각했나요?","‘예’면 다음 질문으로, ‘아니요’면 「이렇게 해 보세요」로 가요."],"title":"『국어』 209쪽 — 질문을 활용해 읽기 과정 되돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_basic#9','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C40',2,'mc','auto','『국어』 211쪽 「글과 연결하기」에서 ‘더 알고 싶은 점’을 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X58']::text[],false,'{"seq":9,"concept":"K4-2-u4-C40","difficulty":2,"kind":"mc","stem":"『국어』 211쪽 「글과 연결하기」에서 ‘더 알고 싶은 점’을 말한 친구는 누구인가요?","options":[{"t":"친구 2","correct":true},{"t":"친구 1","mis":"K4-2-u4-X58"},{"t":"친구 3","mis":"K4-2-u4-X58"}],"explanation":["친구 1과 친구 3은 “……까닭을 알았어.”라고 했어요.","이것은 새롭게 안 점이에요.","친구 2는 약이 어떻게 만들어지는지 궁금하다고 했어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“약도 소비 기한을 지켜야 하는 까닭을 알았어.”"},{"who":"친구 2","text":"“먹는 약은 어떻게 만들어지는지 궁금해.”"},{"who":"친구 3","text":"“약을 올바르게 버려야 하는 까닭을 알았어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_basic#10','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C39',3,'mc','auto','『국어』 209쪽처럼 질문에 답하다가 ‘아니요’가 나왔어요. 어떻게 하면 좋을까요?',ARRAY['K4-2-u4-X40','K4-2-u4-X41','K4-2-u4-X02']::text[],false,'{"seq":10,"concept":"K4-2-u4-C39","difficulty":3,"kind":"mc","stem":"『국어』 209쪽처럼 질문에 답하다가 ‘아니요’가 나왔어요. 어떻게 하면 좋을까요?","options":[{"t":"「이렇게 해 보세요」를 따라 그 과정을 다시 해 본다","correct":true},{"t":"잘 보이도록 ‘예’로 고쳐 표시한다","mis":"K4-2-u4-X40"},{"t":"빨리 다음 칸으로 넘어가 끝낸다","mis":"K4-2-u4-X41"},{"t":"그 글은 다시 읽지 않는다","mis":"K4-2-u4-X02"}],"explanation":["‘아니요’는 다시 해 볼 곳을 알려 줘요.","『국어』 210쪽 「이렇게 해 보세요」를 따라 다시 해 보아요.","점검은 점수가 아니라 나를 위한 것이에요."],"asset":{"type":"passage","lines":["[읽기 전] (     ㉠     )","[읽기 전] 글을 읽기 전에 제목을 보고 자신이 알고 있는 내용을 떠올렸나요?","[읽기 중] 자신이 예상한 내용이 글의 내용과 같은지 확인했나요?","[읽기 중] 글의 중심 내용을 찾으며 읽었나요?","[읽기 중] 새롭게 안 내용을 찾으며 읽었나요?","[읽기 후] (     ㉡     )","[읽기 후] 더 알고 싶은 내용을 생각했나요?","‘예’면 다음 질문으로, ‘아니요’면 「이렇게 해 보세요」로 가요."],"title":"『국어』 209쪽 — 질문을 활용해 읽기 과정 되돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_challenge#1','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C64',2,'mc','auto','병원에서 처방전으로 지은 약에 대해 글에서 설명한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X71','K4-2-u4-X35']::text[],false,'{"seq":1,"concept":"K4-2-u4-C64","difficulty":2,"kind":"mc","stem":"병원에서 처방전으로 지은 약에 대해 글에서 설명한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"처방해 주신 대로 바로바로 먹는 게 중요하다","correct":true},{"t":"남겨 뒀다가 다음에 비슷한 증상일 때 먹으면 된다","mis":"K4-2-u4-X71"},{"t":"개봉한 처방 약도 소비 기한을 정확히 알 수 있다","mis":"K4-2-u4-X35"},{"t":"여러 약을 한 봉지에 섞어 두면 좋다","mis":"K4-2-u4-X35"}],"explanation":["처방 약은 의사 선생님이 처방해 주신 대로 먹어요.","비슷해 보여도 실제 몸 상태는 달라 부작용이 생길 수 있어요.","개봉된 처방 약은 소비 기한을 알 수 없어요."],"asset":{"type":"passage","lines":["(간추림) 처방전으로 지은 약은 처방해 주신 대로 바로바로 먹는 게 중요하다.","(간추림) 남겨 뒀다가 비슷한 증상이라고 함부로 먹는 건 위험하다.","(간추림) 실제 몸 상태는 다를 수 있어 부작용이 생길 수 있다.","(간추림) 개봉된 처방 약은 여러 약이 섞여 소비 기한을 알 수 없다."],"title":"「약, 잘 쓰고 잘 버리는 방법」 처방 약 — 『국어』 205~206쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_challenge#2','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C64',2,'sa','auto','「약, 잘 쓰고 잘 버리는 방법」에서 ‘내성’은 어떤 뜻이라고 했나요? 글에서 찾아 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u4-C64","difficulty":2,"kind":"sa","stem":"「약, 잘 쓰고 잘 버리는 방법」에서 ‘내성’은 어떤 뜻이라고 했나요? 글에서 찾아 쓰세요.","answer":["견딜 수 있는 힘"],"explanation":["항생제 이야기가 나오는 부분을 보아요.","바뀐 균을 ‘내성균’이라고 했어요.","내성은 ‘견딜 수 있는 힘’이라는 뜻이에요."],"asset":{"type":"passage","lines":["(간추림) 항생제는 우리 몸에 병을 일으키는 균을 죽이는 약이다.","(간추림) 균도 공격을 자주 받으면 항생제를 물리칠 요령을 터득한다.","(간추림) 이렇게 바뀐 균을 ‘내성균’이라 하고, 내성은 ‘견딜 수 있는 힘’이다.","이렇게 약을 잘 쓰고 잘 버린다는 건 우리 모두의 건강과 환경을 지키는 일이에요."],"title":"「약, 잘 쓰고 잘 버리는 방법」 항생제와 끝맺음 — 『국어』 207쪽"},"mis":"K4-2-u4-X35"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_challenge#3','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C64',3,'mc','auto','항생제를 많이 쓰면 쓸수록 어떤 일이 생길 수 있다고 했나요?',ARRAY['K4-2-u4-X35','K4-2-u4-X71']::text[],false,'{"seq":3,"concept":"K4-2-u4-C64","difficulty":3,"kind":"mc","stem":"항생제를 많이 쓰면 쓸수록 어떤 일이 생길 수 있다고 했나요?","options":[{"t":"내성균이 많이 생겨 병에 걸렸을 때 치료제의 효과가 없을 수도 있다","correct":true},{"t":"균이 모두 사라져 다시는 병에 걸리지 않는다","mis":"K4-2-u4-X35"},{"t":"항생제가 균을 더 쉽게 죽이게 된다","mis":"K4-2-u4-X35"},{"t":"버려도 환경에는 아무 영향이 없다","mis":"K4-2-u4-X71"}],"explanation":["균도 공격을 자주 받으면 물리칠 요령을 터득해요.","그렇게 바뀐 균이 내성균이에요.","내성균이 많아지면 치료제가 듣지 않을 수 있어요."],"asset":{"type":"passage","lines":["(간추림) 항생제는 우리 몸에 병을 일으키는 균을 죽이는 약이다.","(간추림) 균도 공격을 자주 받으면 항생제를 물리칠 요령을 터득한다.","(간추림) 이렇게 바뀐 균을 ‘내성균’이라 하고, 내성은 ‘견딜 수 있는 힘’이다.","이렇게 약을 잘 쓰고 잘 버린다는 건 우리 모두의 건강과 환경을 지키는 일이에요."],"title":"「약, 잘 쓰고 잘 버리는 방법」 항생제와 끝맺음 — 『국어』 207쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_challenge#4','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C65',3,'blank','auto','『국어』 208쪽 ㉡ 「병균을 물리치는 방법을 (     )했다.」와 글 속 「항생제를 물리칠 요령을 (     )하게 된답니다.」에 함께 들어갈 낱말은 무엇인가요?',ARRAY['K4-2-u4-X70']::text[],false,'{"seq":4,"concept":"K4-2-u4-C65","difficulty":3,"kind":"blank","stem":"『국어』 208쪽 ㉡ 「병균을 물리치는 방법을 (     )했다.」와 글 속 「항생제를 물리칠 요령을 (     )하게 된답니다.」에 함께 들어갈 낱말은 무엇인가요?","options":[{"t":"터득","correct":true},{"t":"개봉","mis":"K4-2-u4-X70"},{"t":"수거","mis":"K4-2-u4-X70"},{"t":"처방","mis":"K4-2-u4-X70"}],"explanation":["뜻풀이는 「깊이 생각해 이치를 깨달아 알아냄.」이에요.","균이 항생제를 물리칠 요령을 깨달아 알아낸다는 뜻이에요.","두 문장 모두 ‘터득’이 알맞아요."],"asset":{"type":"passage","lines":["보기 — 병원에서 감기약 ( 처방 )을 받았다.","처방: 치료하는 데 필요한 의약품이나 방법 따위를 적은 문서.","㉠ 약을 먹으려고 약상자를 (     )했다. — 열지 못하게 붙여 두었던 것을 떼거나 엶.","㉡ 병균을 물리치는 방법을 (     )했다. — 깊이 생각해 이치를 깨달아 알아냄.","㉢ 재활용품은 일반 쓰레기와 분리해 (     )해야 한다. — 거두어 감.","[낱말 퍼즐] 처 개 봉 로 / 방 프 수 니 / 터 득 거 해 (가로세로로만 찾아요)"],"title":"『국어』 208쪽 낱말 알기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_challenge#5','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C65',3,'mc','auto','『국어』 208쪽 낱말 퍼즐을 풀 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u4-X70']::text[],false,'{"seq":5,"concept":"K4-2-u4-C65","difficulty":3,"kind":"mc","stem":"『국어』 208쪽 낱말 퍼즐을 풀 때 알맞은 방법은 무엇인가요?","options":[{"t":"가로와 세로로만 낱말을 찾고, 낱말의 뜻과 문장 속 쓰임을 함께 살핀다","correct":true},{"t":"대각선으로도 낱말을 찾을 수 있다","mis":"K4-2-u4-X70"},{"t":"뜻은 보지 않고 글자 수만 맞추면 된다","mis":"K4-2-u4-X70"}],"explanation":["낱말은 가로세로로만 찾고 대각선으로는 찾지 않아요.","여러 뜻이 있는 낱말은 문장에 맞는 뜻을 골라요.","어려우면 국어사전을 찾아보아요."],"asset":{"type":"passage","lines":["보기 — 병원에서 감기약 ( 처방 )을 받았다.","처방: 치료하는 데 필요한 의약품이나 방법 따위를 적은 문서.","㉠ 약을 먹으려고 약상자를 (     )했다. — 열지 못하게 붙여 두었던 것을 떼거나 엶.","㉡ 병균을 물리치는 방법을 (     )했다. — 깊이 생각해 이치를 깨달아 알아냄.","㉢ 재활용품은 일반 쓰레기와 분리해 (     )해야 한다. — 거두어 감.","[낱말 퍼즐] 처 개 봉 로 / 방 프 수 니 / 터 득 거 해 (가로세로로만 찾아요)"],"title":"『국어』 208쪽 낱말 알기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_challenge#6','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C38',3,'mc','auto','「약, 잘 쓰고 잘 버리는 방법」을 요약한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X38','K4-2-u4-X39','K4-2-u4-X37']::text[],false,'{"seq":6,"concept":"K4-2-u4-C38","difficulty":3,"kind":"mc","stem":"「약, 잘 쓰고 잘 버리는 방법」을 요약한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"약은 소비 기한과 보관법을 지키고 처방대로 먹으며, 남은 약은 폐의약품 수거함에 넣어야 우리 모두의 건강과 환경을 지킬 수 있다.","correct":true},{"t":"약도 소비 기한이 있다는 사실, 알고 있나요? 약은 소비 기한이 지나면…… (글을 처음부터 그대로 옮겨 적음)","mis":"K4-2-u4-X38"},{"t":"물고기들이 약을 먹을 수 있다는 부분이 가장 놀라웠다.","mis":"K4-2-u4-X39"},{"t":"내성은 견딜 수 있는 힘이다.","mis":"K4-2-u4-X37"}],"explanation":["요약은 각 문단의 중심 내용을 모아 짧게 쓰는 것이에요.","글을 그대로 옮기거나 한 부분만 쓰면 요약이 아니에요.","보관·복용·버리기·까닭이 모두 들어가야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_challenge#7','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C40',3,'mc','auto','『국어』 211쪽 「글과 연결하기」의 말을 ‘새롭게 안 점’과 ‘더 알고 싶은 점’으로 바르게 가른 것은 무엇인가요?',ARRAY['K4-2-u4-X58']::text[],false,'{"seq":7,"concept":"K4-2-u4-C40","difficulty":3,"kind":"mc","stem":"『국어』 211쪽 「글과 연결하기」의 말을 ‘새롭게 안 점’과 ‘더 알고 싶은 점’으로 바르게 가른 것은 무엇인가요?","options":[{"t":"새롭게 안 점 — 약도 소비 기한을 지켜야 하는 까닭 / 더 알고 싶은 점 — 먹는 약은 어떻게 만들어지는지","correct":true},{"t":"새롭게 안 점 — 먹는 약은 어떻게 만들어지는지 / 더 알고 싶은 점 — 약도 소비 기한을 지켜야 하는 까닭","mis":"K4-2-u4-X58"},{"t":"새롭게 안 점 — 오늘 점심 메뉴 / 더 알고 싶은 점 — 내일 날씨","mis":"K4-2-u4-X58"}],"explanation":["새롭게 안 점은 글을 읽고 알게 된 것이에요.","더 알고 싶은 점은 읽고 나서 궁금해진 것이에요.","둘 다 글과 이어져야 해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“약도 소비 기한을 지켜야 하는 까닭을 알았어.”"},{"who":"친구 2","text":"“먹는 약은 어떻게 만들어지는지 궁금해.”"},{"who":"친구 3","text":"“약을 올바르게 버려야 하는 까닭을 알았어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_challenge#8','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C39',4,'essay','teacher','『국어』 211쪽 「자신과 연결하기」예요. 질문을 활용해 「약, 잘 쓰고 잘 버리는 방법」을 읽은 자신의 읽기 과정을 되돌아보고, 잘한 점과 노력할 점을 하나씩 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u4-C39","difficulty":4,"kind":"essay","stem":"『국어』 211쪽 「자신과 연결하기」예요. 질문을 활용해 「약, 잘 쓰고 잘 버리는 방법」을 읽은 자신의 읽기 과정을 되돌아보고, 잘한 점과 노력할 점을 하나씩 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 제목을 보고 약을 버리는 방법이 나올 것이라고 예상하고, 읽으면서 예상이 맞는지 확인했다. 노력할 점 — 각 문단의 중심 문장을 찾지 않고 읽어서 요약하기 어려웠다. 다음에는 중심 문장에 밑줄을 그으며 읽겠다.","scoring_points":["읽기 과정을 되돌아보는 질문을 떠올려 점검했는가","잘한 점과 노력할 점을 솔직하게 썼는가","노력할 점을 고칠 방법을 구체적으로 썼는가"]},"explanation":["『국어』 209쪽 질문에 ‘예’와 ‘아니요’로 답해 보아요.","‘아니요’가 나온 곳이 노력할 점이에요.","점검은 다음에 더 잘 읽기 위한 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_challenge#9','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C40',4,'essay','teacher','『국어』 211쪽 「글과 연결하기」처럼 「약, 잘 쓰고 잘 버리는 방법」을 읽고 새롭게 안 점과 더 알고 싶은 점을 하나씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u4-C40","difficulty":4,"kind":"essay","stem":"『국어』 211쪽 「글과 연결하기」처럼 「약, 잘 쓰고 잘 버리는 방법」을 읽고 새롭게 안 점과 더 알고 싶은 점을 하나씩 쓰세요.","answer_guide":{"answer":"예: 새롭게 안 점 — 쓰레기통에 버린 약도 사라지지 않고 강으로 흘러가 물고기에게 피해를 줄 수 있다는 것을 알았다. 더 알고 싶은 점 — 폐의약품 수거함에 모인 약은 어떻게 처리되는지 궁금하다.","scoring_points":["글을 읽고 새롭게 안 점을 썼는가","읽고 나서 더 알고 싶어진 점을 썼는가","두 가지가 글의 내용과 이어지는가"]},"explanation":["글에서 처음 알게 된 내용을 찾아요.","읽고 나서 궁금해진 것을 떠올려요.","친구들과 이야기하며 생각을 넓혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L09_challenge#10','kor',4,2,'u4','L09','tb_g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C34',4,'essay','teacher','『국어』 204쪽 경험 떠올리기처럼 설명하는 글을 읽은 경험을 하나 떠올려, 무엇을 알고 싶어서 어떤 글을 읽었는지와 그 글이 설명하는 글인 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C34","difficulty":4,"kind":"essay","stem":"『국어』 204쪽 경험 떠올리기처럼 설명하는 글을 읽은 경험을 하나 떠올려, 무엇을 알고 싶어서 어떤 글을 읽었는지와 그 글이 설명하는 글인 까닭을 쓰세요.","answer_guide":{"answer":"예: 라면을 끓이는 방법을 알고 싶어서 봉지에 적힌 조리법을 읽었다. 조리법은 끓이는 차례와 방법이라는 정보를 이해하기 쉽게 알려 주니까 설명하는 글이다.","scoring_points":["설명하는 글을 읽은 경험을 구체적으로 썼는가","무엇을 알고 싶어서 읽었는지 썼는가","그 글이 지식이나 정보를 전달하는 글이라는 까닭을 썼는가"]},"explanation":["조립 설명서, 소개 글, 조리법, 안내문도 설명하는 글이에요.","그 글을 왜 읽었는지 떠올려요.","지식이나 정보를 이해하기 쉽게 전달하는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_basic#1','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C41',1,'mc','auto','『국어』 212쪽에서 의견을 제시하는 글을 무엇이라고 했나요?',ARRAY['K4-2-u4-X42','K4-2-u4-X05']::text[],false,'{"seq":1,"concept":"K4-2-u4-C41","difficulty":1,"kind":"mc","stem":"『국어』 212쪽에서 의견을 제시하는 글을 무엇이라고 했나요?","options":[{"t":"어떤 문제에 대해 자신의 생각이나 주장을 밝혀 쓴 글","correct":true},{"t":"겪은 일을 시간 차례대로 적은 글","mis":"K4-2-u4-X42"},{"t":"읽는 사람이 반드시 따라야 하는 규칙을 적은 글","mis":"K4-2-u4-X42"},{"t":"어떤 지식이나 정보를 객관적으로 전달하는 글","mis":"K4-2-u4-X05"}],"explanation":["의견을 제시하는 글에는 글쓴이의 생각이나 주장이 있어요.","어떤 문제에 대해 그 생각을 밝혀 써요.","정보를 객관적으로 전달하는 글은 설명하는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_basic#2','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C66',1,'mc','auto','『국어』 214쪽 내용 알기예요. 저작권은 무엇인가요?',ARRAY['K4-2-u4-X72','K4-2-u4-X35']::text[],false,'{"seq":2,"concept":"K4-2-u4-C66","difficulty":1,"kind":"mc","stem":"『국어』 214쪽 내용 알기예요. 저작권은 무엇인가요?","options":[{"t":"사람의 생각 또는 감정을 표현한 창작물에 대해 이를 만든 사람이 가지는 권리","correct":true},{"t":"창작물을 산 사람이 마음대로 고칠 수 있는 권리","mis":"K4-2-u4-X72"},{"t":"인터넷에 올린 자료를 누구나 쓸 수 있는 권리","mis":"K4-2-u4-X72"},{"t":"작품을 가장 먼저 본 사람이 가지는 권리","mis":"K4-2-u4-X35"}],"explanation":["저작권은 창작물을 만든 사람의 권리예요.","창작물은 사람의 생각이나 감정을 표현한 것이에요.","그래서 만든 사람에게 허락을 받고 써야 해요."],"asset":{"type":"passage","lines":["저작권이란 사람의 생각 또는 감정을 표현한 창작물에 대하여","이를 만든 사람이 가지는 권리를 말합니다.","(간추림) 창작자가 창작물에 들인 시간과 노력을 인정하고 보호해 주어야 한다.","(간추림) 창작자에게는 이용을 허락하거나 허락하지 않을 권리가 있다.","(간추림) 그러므로 만든 사람에게 허락을 받고 창작물을 이용해야 한다."],"title":"「저작권을 왜 지켜야 하나요?」 둘째 문단 — 『국어』 213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_basic#3','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C43',1,'mc','auto','「저작권을 왜 지켜야 하나요?」에서 글쓴이의 의견이 가장 잘 드러난 문장은 무엇인가요?',ARRAY['K4-2-u4-X44']::text[],false,'{"seq":3,"concept":"K4-2-u4-C43","difficulty":1,"kind":"mc","stem":"「저작권을 왜 지켜야 하나요?」에서 글쓴이의 의견이 가장 잘 드러난 문장은 무엇인가요?","options":[{"t":"우리는 저작권을 지키기 위하여 노력해야 합니다.","correct":true},{"t":"저작권은 우리의 일상생활 속에서 쉽게 자주 접하게 되는 개념입니다.","mis":"K4-2-u4-X44"},{"t":"여러분의 작품을 친구가 허락 없이 사용한 상황을 상상해 봅시다.","mis":"K4-2-u4-X44"},{"t":"음악이나 재미있는 영화, 책도 없어지겠지요.","mis":"K4-2-u4-X44"}],"explanation":["의견은 글쓴이가 바라는 것을 밝힌 문장이에요.","「~해야 합니다」처럼 무엇을 하자고 하는 말을 찾아요.","상황을 상상해 보자는 말이나 결과를 말한 문장과 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_basic#4','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C67',1,'blank','auto','『국어』 214쪽 낱말 알기예요. 「다른 사람의 권리를 (     )해서는 안 돼.」 빈칸에 들어갈 낱말은 무엇인가요?',ARRAY['K4-2-u4-X70']::text[],false,'{"seq":4,"concept":"K4-2-u4-C67","difficulty":1,"kind":"blank","stem":"『국어』 214쪽 낱말 알기예요. 「다른 사람의 권리를 (     )해서는 안 돼.」 빈칸에 들어갈 낱말은 무엇인가요?","options":[{"t":"침해","correct":true},{"t":"창작","mis":"K4-2-u4-X70"},{"t":"발전","mis":"K4-2-u4-X70"},{"t":"보호","mis":"K4-2-u4-X70"}],"explanation":["뜻풀이는 「침범해 해를 끼침.」이에요.","글자 카드에서 ‘침’과 ‘해’를 찾아요.","다른 사람의 권리를 침해하면 안 돼요."],"asset":{"type":"passage","lines":["보기 글자 카드: 스 피 해 이 래 창 광 작 터 발 코 전 침","(1) 다른 사람이 (     )한 작품을 인정하고 보호해 주어야 해.","— 예술 작품을 독창적으로 지어냄. 방안이나 물건 따위를 처음으로 만들어 냄.","(2) 저작권을 잘 지키면 우리나라 문화 산업이 (     )할 수 있어.","— 더 낫고 좋은 상태나 더 높은 단계로 나아감.","(3) 다른 사람의 권리를 (     )해서는 안 돼.","— 침범해 해를 끼침."],"title":"『국어』 214쪽 낱말 알기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_basic#5','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C66',2,'mc','auto','저작권을 지켜야 하는 까닭은 무엇인가요?',ARRAY['K4-2-u4-X72','K4-2-u4-X35','K4-2-u4-X48']::text[],false,'{"seq":5,"concept":"K4-2-u4-C66","difficulty":2,"kind":"mc","stem":"저작권을 지켜야 하는 까닭은 무엇인가요?","options":[{"t":"창작자가 창작물에 들인 시간과 노력을 인정하고 보호해 주어야 하기 때문","correct":true},{"t":"창작물은 누구나 허락 없이 써도 되기 때문","mis":"K4-2-u4-X72"},{"t":"저작권을 지키면 내 작품이 저절로 많아지기 때문","mis":"K4-2-u4-X35"},{"t":"글쓴이가 시켰으니 무조건 따라야 하기 때문","mis":"K4-2-u4-X48"}],"explanation":["창작자는 오랜 시간 공들여 창작물을 만들어요.","그 시간과 노력을 인정하고 보호해야 해요.","그래서 허락을 받고 창작물을 이용해요."],"asset":{"type":"passage","lines":["저작권이란 사람의 생각 또는 감정을 표현한 창작물에 대하여","이를 만든 사람이 가지는 권리를 말합니다.","(간추림) 창작자가 창작물에 들인 시간과 노력을 인정하고 보호해 주어야 한다.","(간추림) 창작자에게는 이용을 허락하거나 허락하지 않을 권리가 있다.","(간추림) 그러므로 만든 사람에게 허락을 받고 창작물을 이용해야 한다."],"title":"「저작권을 왜 지켜야 하나요?」 둘째 문단 — 『국어』 213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_basic#6','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C66',2,'mc','auto','만약 세상에서 새로운 노래나 이야기가 더 이상 만들어지지 않는다면 우리 생활은 어떻게 될까요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":6,"concept":"K4-2-u4-C66","difficulty":2,"kind":"mc","stem":"만약 세상에서 새로운 노래나 이야기가 더 이상 만들어지지 않는다면 우리 생활은 어떻게 될까요?","options":[{"t":"누릴 수 있는 문화의 수준이 낮아지고 일상에서의 즐거움이 사라진다","correct":true},{"t":"아무 변화가 없다","mis":"K4-2-u4-X35"},{"t":"문화 산업이 더 발전한다","mis":"K4-2-u4-X35"},{"t":"일자리가 더 많이 생긴다","mis":"K4-2-u4-X35"}],"explanation":["좋은 작품이 만들어지지 않으면 문화의 수준이 낮아져요.","음악이나 영화, 책이 주는 즐거움도 사라져요.","그래서 창작자의 권리를 지켜 주어야 해요."],"asset":{"type":"passage","lines":["(간추림) 저작권을 잘 지키지 않으면 창작자는 더 좋은 작품을 만들려고 노력하지 않게 된다.","(간추림) 그러면 사람들이 누릴 수 있는 문화의 수준도 낮아질 가능성이 크다.","(간추림) 음악이나 영화, 책도 없어지고 문화 산업도 발전하지 않을 것이다.","(간추림) 일자리가 사라지고 우리나라의 경제적인 성장도 기대할 수 없게 된다."],"title":"「저작권을 왜 지켜야 하나요?」 셋째 문단 — 『국어』 213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_basic#7','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C44',2,'mc','auto','글쓴이가 「저작권을 지켜야 한다」는 의견을 뒷받침하려고 든 이유로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X45','K4-2-u4-X46']::text[],false,'{"seq":7,"concept":"K4-2-u4-C44","difficulty":2,"kind":"mc","stem":"글쓴이가 「저작권을 지켜야 한다」는 의견을 뒷받침하려고 든 이유로 알맞은 것은 무엇인가요?","options":[{"t":"저작권을 지키지 않으면 창작자가 더 좋은 작품을 만들려는 노력을 하지 않게 되기 때문","correct":true},{"t":"실수로 저작권을 침해했다면 바로 인정하고 수정해야 하기 때문","mis":"K4-2-u4-X45"},{"t":"친구가 허락 없이 내 작품을 쓴 상황을 상상해 보아야 하기 때문","mis":"K4-2-u4-X45"},{"t":"저작권이라는 낱말은 어렵기 때문","mis":"K4-2-u4-X46"}],"explanation":["이유는 의견을 받쳐 주는 까닭이에요.","저작권을 지키지 않았을 때 생기는 문제가 이유로 나와요.","실천을 권하는 말이나 상황을 상상하게 하는 말은 이유와 구별해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_basic#8','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C48',2,'blank','auto','『국어』 215쪽이에요. 읽기 중 ㉡에 붙일 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X32']::text[],false,'{"seq":8,"concept":"K4-2-u4-C48","difficulty":2,"kind":"blank","stem":"『국어』 215쪽이에요. 읽기 중 ㉡에 붙일 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"의견에 대한 이유가 적절한지 살피며 읽었나요?","correct":true},{"t":"읽은 내용을 요약했나요?","mis":"K4-2-u4-X31"},{"t":"제목이나 차례를 보며 내용을 예상했나요?","mis":"K4-2-u4-X31"},{"t":"글쓴이의 글씨가 예쁜가요?","mis":"K4-2-u4-X32"}],"explanation":["의견을 제시하는 글을 읽는 동안에는 의견을 찾아요.","그다음에는 의견에 대한 이유가 적절한지 살펴요.","글씨 모양은 읽기 과정 질문이 아니에요."],"asset":{"type":"passage","lines":["[읽기 전] 글을 읽기 전에 제목을 보고 어떤 내용일지 예상했나요?","[읽기 전] (     ㉠     )","[읽기 중] 자신이 예상한 내용이 글의 내용과 같은지 확인했나요?","[읽기 중] 글쓴이의 의견이 무엇인지 찾으며 읽었나요?","[읽기 중] (     ㉡     )","[읽기 후] (     ㉢     )","[읽기 후] 글쓴이와 자신의 의견을 비교하여 정리했나요?","‘예’면 다음 질문으로, ‘아니요’면 「이렇게 해 보세요」로 가요."],"title":"『국어』 215쪽 — 질문을 활용해 읽기 과정 되돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_basic#9','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C46',2,'ox','auto','의견을 제시하는 글에서 글쓴이의 의견은 무조건 옳다고 믿으면 돼요.',ARRAY['K4-2-u4-X48']::text[],false,'{"seq":9,"concept":"K4-2-u4-C46","difficulty":2,"kind":"ox","stem":"의견을 제시하는 글에서 글쓴이의 의견은 무조건 옳다고 믿으면 돼요.","answer":"X","reason_options":[{"t":"의견에 대한 이유가 적절한지 살피며 읽고, 내 의견과 견주어 보아요.","correct":true},{"t":"책에 실린 의견이니 따지지 않고 그대로 따라야 해요.","mis":"K4-2-u4-X48"}],"mis":"K4-2-u4-X48","explanation":["『국어』 221쪽 스스로 확인하기에서 이 돌은 바른 길이 아니에요.","글쓴이의 의견은 글쓴이의 생각이에요.","이유를 따져 보고 내 생각을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_basic#10','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C44',3,'mc','auto','「학교에서 스마트폰을 사용하지 않아야 한다.」라는 주제에 대해 자신의 의견을 말하려고 해요. 의견과 함께 꼭 생각해야 할 것은 무엇인가요?',ARRAY['K4-2-u4-X10','K4-2-u4-X47','K4-2-u4-X41']::text[],false,'{"seq":10,"concept":"K4-2-u4-C44","difficulty":3,"kind":"mc","stem":"「학교에서 스마트폰을 사용하지 않아야 한다.」라는 주제에 대해 자신의 의견을 말하려고 해요. 의견과 함께 꼭 생각해야 할 것은 무엇인가요?","options":[{"t":"그렇게 생각한 이유","correct":true},{"t":"찬성하는 친구가 몇 명인지","mis":"K4-2-u4-X10"},{"t":"반대하는 친구의 이름","mis":"K4-2-u4-X47"},{"t":"의견을 말하는 데 걸리는 시간","mis":"K4-2-u4-X41"}],"explanation":["의견에는 그렇게 생각한 이유가 함께 있어야 해요.","이유를 들으면 상대가 의견을 이해할 수 있어요.","의견 글을 읽을 때에도 글쓴이가 든 이유를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_challenge#1','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C42',2,'mc','auto','「저작권을 왜 지켜야 하나요?」의 제목만 보고 짐작할 수 있는 것은 무엇인가요?',ARRAY['K4-2-u4-X43']::text[],false,'{"seq":1,"concept":"K4-2-u4-C42","difficulty":2,"kind":"mc","stem":"「저작권을 왜 지켜야 하나요?」의 제목만 보고 짐작할 수 있는 것은 무엇인가요?","options":[{"t":"저작권을 지켜야 하는 까닭을 쓴 글일 것이다","correct":true},{"t":"이유가 모두 다섯 가지일 것이다","mis":"K4-2-u4-X43"},{"t":"글쓴이가 몇 살인지 알 수 있다","mis":"K4-2-u4-X43"},{"t":"저작권을 지키지 말자는 글일 것이다","mis":"K4-2-u4-X43"}],"explanation":["제목에 ‘왜 지켜야 하나요?’라는 물음이 있어요.","그래서 지켜야 하는 까닭을 쓴 글이라고 짐작할 수 있어요.","이유가 몇 개인지는 글을 읽어야 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_challenge#2','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C67',2,'blank','auto','「저작권을 잘 지키면 우리나라 문화 산업이 (     )할 수 있어.」 보기 글자 카드에서 찾아 쓸 낱말은 무엇인가요?',ARRAY['K4-2-u4-X70']::text[],false,'{"seq":2,"concept":"K4-2-u4-C67","difficulty":2,"kind":"blank","stem":"「저작권을 잘 지키면 우리나라 문화 산업이 (     )할 수 있어.」 보기 글자 카드에서 찾아 쓸 낱말은 무엇인가요?","options":[{"t":"발전","correct":true},{"t":"창작","mis":"K4-2-u4-X70"},{"t":"침해","mis":"K4-2-u4-X70"},{"t":"피해","mis":"K4-2-u4-X70"}],"explanation":["뜻풀이는 「더 낫고 좋은 상태나 더 높은 단계로 나아감.」이에요.","글자 카드에서 ‘발’과 ‘전’을 찾아요.","저작권을 지키면 문화 산업이 발전할 수 있어요."],"asset":{"type":"passage","lines":["보기 글자 카드: 스 피 해 이 래 창 광 작 터 발 코 전 침","(1) 다른 사람이 (     )한 작품을 인정하고 보호해 주어야 해.","— 예술 작품을 독창적으로 지어냄. 방안이나 물건 따위를 처음으로 만들어 냄.","(2) 저작권을 잘 지키면 우리나라 문화 산업이 (     )할 수 있어.","— 더 낫고 좋은 상태나 더 높은 단계로 나아감.","(3) 다른 사람의 권리를 (     )해서는 안 돼.","— 침범해 해를 끼침."],"title":"『국어』 214쪽 낱말 알기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_challenge#3','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C45',3,'mc','auto','다음 가운데 「저작권을 지켜야 한다」는 의견을 뒷받침하는 이유로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u4-X47']::text[],false,'{"seq":3,"concept":"K4-2-u4-C45","difficulty":3,"kind":"mc","stem":"다음 가운데 「저작권을 지켜야 한다」는 의견을 뒷받침하는 이유로 알맞지 않은 것은 무엇인가요?","options":[{"t":"저작권이라는 말이 세 글자로 되어 있기 때문","correct":true},{"t":"좋은 작품이 만들어지지 않으면 문화의 수준이 낮아지기 때문","mis":"K4-2-u4-X47"},{"t":"창작자의 권리를 보호하고 정직한 사회를 만드는 데 기여하기 때문","mis":"K4-2-u4-X47"},{"t":"문화 산업이 발전하지 않으면 일자리도 사라지기 때문","mis":"K4-2-u4-X47"}],"explanation":["이유는 의견대로 하면 좋은 점이나 하지 않으면 생기는 문제여야 해요.","글자 수는 저작권을 지켜야 하는 까닭과 이어지지 않아요.","찬성하든 반대하든 이유가 이어지는지로 판단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_challenge#4','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C47',3,'mc','auto','읽기 후 「글쓴이와 자신의 의견을 비교하여 정리했나요?」에 답하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X48','K4-2-u4-X49','K4-2-u4-X44']::text[],false,'{"seq":4,"concept":"K4-2-u4-C47","difficulty":3,"kind":"mc","stem":"읽기 후 「글쓴이와 자신의 의견을 비교하여 정리했나요?」에 답하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"글쓴이의 의견과 자신의 의견에서 같거나 다른 점을 찾고, 다르면 자신의 이유를 마련한다","correct":true},{"t":"글쓴이의 의견을 그대로 따라 쓴다","mis":"K4-2-u4-X48"},{"t":"글쓴이의 의견은 일단 틀렸다고 쓴다","mis":"K4-2-u4-X49"},{"t":"글쓴이의 의견은 찾지 않고 내 생각만 쓴다","mis":"K4-2-u4-X44"}],"explanation":["먼저 글쓴이의 의견을 정확히 찾아요.","내 의견과 같은 점, 다른 점을 견주어요.","다르다면 내 생각의 이유를 마련해요."],"asset":{"type":"passage","lines":["[읽기 전] 글을 읽기 전에 제목을 보고 어떤 내용일지 예상했나요?","[읽기 전] (     ㉠     )","[읽기 중] 자신이 예상한 내용이 글의 내용과 같은지 확인했나요?","[읽기 중] 글쓴이의 의견이 무엇인지 찾으며 읽었나요?","[읽기 중] (     ㉡     )","[읽기 후] (     ㉢     )","[읽기 후] 글쓴이와 자신의 의견을 비교하여 정리했나요?","‘예’면 다음 질문으로, ‘아니요’면 「이렇게 해 보세요」로 가요."],"title":"『국어』 215쪽 — 질문을 활용해 읽기 과정 되돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_challenge#5','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C66',3,'mc','auto','『국어』 217쪽 「세상과 연결하기」예요. 일상생활에서 저작권을 지키는 방법으로 알맞지 않은 것은 무엇인가요?',ARRAY['K4-2-u4-X72']::text[],false,'{"seq":5,"concept":"K4-2-u4-C66","difficulty":3,"kind":"mc","stem":"『국어』 217쪽 「세상과 연결하기」예요. 일상생활에서 저작권을 지키는 방법으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"인터넷에 있는 그림은 누구나 볼 수 있으니 허락 없이 내 과제에 써도 된다","correct":true},{"t":"과제를 할 때 인터넷에서 사진을 가져오면 반드시 출처를 밝힌다","mis":"K4-2-u4-X72"},{"t":"친구의 글이나 그림을 허락 없이 사용하지 않는다","mis":"K4-2-u4-X72"}],"explanation":["인터넷에서 가져온 자료도 허락을 받고 쓰는 것이 원칙이에요.","가져온 자료는 출처를 밝혀요.","친구의 작품도 허락 없이 쓰지 않아요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“우리가 일상생활에서 저작권을 지키기 위해 할 수 있는 일에는 무엇이 있을까?”"},{"who":"친구 2","text":"“과제를 할 때 인터넷에서 사진을 가져오면 반드시 출처를 밝혀야 해.”"},{"who":"친구 3","text":"“친구의 글이나 그림을 허락 없이 사용하지 않아야 해.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_challenge#6','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C49',3,'error','auto','세 친구가 『국어』 215쪽 읽기 과정 되돌아보기를 했어요. 잘못 생각한 친구는 누구인가요?',ARRAY['K4-2-u4-X40','K4-2-u4-X41','K4-2-u4-X07']::text[],false,'{"seq":6,"concept":"K4-2-u4-C49","difficulty":3,"kind":"error","stem":"세 친구가 『국어』 215쪽 읽기 과정 되돌아보기를 했어요. 잘못 생각한 친구는 누구인가요?","options":[{"t":"윤호: ‘아니요’가 나오면 안 좋으니까 모두 ‘예’에 표시했어.","correct":true,"mis_target":"K4-2-u4-X40"},{"t":"채린: ‘아니요’가 나온 질문은 「이렇게 해 보세요」를 따라 다시 해 봤어.","mis":"K4-2-u4-X41"},{"t":"도윤: 이유가 적절한지 살피지 못해서 그 부분을 다시 읽었어.","mis":"K4-2-u4-X07"}],"explanation":["되돌아보기는 나를 위한 점검이에요.","‘아니요’가 나오면 「이렇게 해 보세요」를 따라 다시 해요.","모두 ‘예’로 표시하면 다시 읽을 곳을 찾을 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_challenge#7','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C48',3,'mc','auto','『국어활동』 57쪽 「더 알아보기」에서 의견을 제시하는 글을 읽을 때 할 수 있는 질문으로 든 것은 무엇인가요?',ARRAY['K4-2-u4-X05']::text[],false,'{"seq":7,"concept":"K4-2-u4-C48","difficulty":3,"kind":"mc","stem":"『국어활동』 57쪽 「더 알아보기」에서 의견을 제시하는 글을 읽을 때 할 수 있는 질문으로 든 것은 무엇인가요?","options":[{"t":"글을 읽으며 생각이 바뀌거나 발전한 부분이 있었나요?","correct":true},{"t":"새롭게 안 사실은 무엇인가요?","mis":"K4-2-u4-X05"},{"t":"가장 기억에 남는 장면은 무엇인가요?","mis":"K4-2-u4-X05"}],"explanation":["읽기 과정을 점검하는 질문은 글의 종류에 따라 달라요.","설명하는 글은 새롭게 안 사실을 물어요.","의견을 제시하는 글은 생각이 바뀌거나 발전한 부분을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_challenge#8','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C49',4,'essay','teacher','『국어』 217쪽 「자신과 연결하기」처럼 「저작권을 왜 지켜야 하나요?」를 읽은 자신의 읽기 과정에서 잘한 점과 노력할 점을 쓰세요. 노력할 점에는 다음에 어떻게 할지도 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u4-C49","difficulty":4,"kind":"essay","stem":"『국어』 217쪽 「자신과 연결하기」처럼 「저작권을 왜 지켜야 하나요?」를 읽은 자신의 읽기 과정에서 잘한 점과 노력할 점을 쓰세요. 노력할 점에는 다음에 어떻게 할지도 쓰세요.","answer_guide":{"answer":"예: 잘한 점 — 제목을 보고 저작권을 지켜야 하는 까닭을 쓴 글일 것이라고 예상했다. 노력할 점 — 글을 읽고 나서 내 생각을 글쓴이의 생각과 비교해 보지 않았다. 다음에는 글쓴이의 의견과 내 의견에서 같은 점과 다른 점을 찾아 정리하겠다.","scoring_points":["질문을 활용해 읽기 과정을 되돌아보았는가","잘한 점과 노력할 점을 솔직하게 썼는가","다음에 어떻게 할지 구체적으로 썼는가"]},"explanation":["『국어』 215~216쪽 질문에 답하며 되돌아보아요.","글쓴이가 글을 쓴 목적과 의견을 살피며 읽었는지 생각해요.","노력할 점은 다음에 더 잘 읽는 방법이 돼요."],"asset":{"type":"passage","lines":["잘한 점 — 제목을 보고 저작권을 지켜야 하는 까닭을 쓴 글일 것이라고 예상했다.","노력할 점 — 글을 읽고 나서 내 생각을 글쓴이의 생각과 비교해 보지 않았다."],"title":"『국어』 217쪽 자신과 연결하기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_challenge#9','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C47',4,'essay','teacher','「저작권을 왜 지켜야 하나요?」를 읽고 글쓴이의 의견과 자신의 의견을 비교하여, 같은 점이나 다른 점과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u4-C47","difficulty":4,"kind":"essay","stem":"「저작권을 왜 지켜야 하나요?」를 읽고 글쓴이의 의견과 자신의 의견을 비교하여, 같은 점이나 다른 점과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 나도 글쓴이처럼 저작권을 지켜야 한다고 생각한다. 내가 정성껏 그린 그림을 친구가 자기 것처럼 쓴다면 무척 속상할 것 같기 때문이다. 다만 나는 학교에서 저작권을 지키는 방법을 더 자세히 배워야 한다고 생각한다.","scoring_points":["글쓴이의 의견을 바르게 찾았는가","자신의 의견과 같은 점이나 다른 점을 썼는가","자신의 의견에 대한 이유를 썼는가"]},"explanation":["글쓴이의 의견은 저작권을 지키기 위해 노력해야 한다는 것이에요.","내 생각과 견주어 같은 점, 다른 점을 찾아요.","그대로 따르거나 무조건 반대하지 말고 이유를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L11_challenge#10','kor',4,2,'u4','L11','tb_g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C66',4,'essay','teacher','일상생활에서 저작권을 지키기 위해 실천할 수 있는 일을 두 가지 쓰고, 그 일이 왜 필요한지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C66","difficulty":4,"kind":"essay","stem":"일상생활에서 저작권을 지키기 위해 실천할 수 있는 일을 두 가지 쓰고, 그 일이 왜 필요한지 쓰세요.","answer_guide":{"answer":"예: ① 과제를 할 때 인터넷에서 사진을 가져오면 반드시 출처를 밝힌다. ② 친구의 글이나 그림을 쓸 때에는 먼저 허락을 받는다. 창작자가 들인 시간과 노력을 인정하고 보호해야 더 좋은 작품이 계속 만들어지기 때문이다.","scoring_points":["실천할 수 있는 일을 두 가지 썼는가","두 가지가 저작권을 지키는 일과 이어지는가","그 일이 필요한 까닭을 글의 내용과 이어 썼는가"]},"explanation":["『국어』 217쪽 친구들의 대화를 떠올려요.","허락 받기, 출처 밝히기처럼 직접 할 수 있는 일을 써요.","까닭은 창작자의 권리와 이어 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“우리가 일상생활에서 저작권을 지키기 위해 할 수 있는 일에는 무엇이 있을까?”"},{"who":"친구 2","text":"“과제를 할 때 인터넷에서 사진을 가져오면 반드시 출처를 밝혀야 해.”"},{"who":"친구 3","text":"“친구의 글이나 그림을 허락 없이 사용하지 않아야 해.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_basic#1','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C50',1,'mc','auto','『국어』 218쪽 이런 활동 1이에요. 시를 읽고 생각이나 느낌을 나타내는 방법으로 보기에 나온 것이 아닌 것은 무엇인가요?',ARRAY['K4-2-u4-X67']::text[],false,'{"seq":1,"concept":"K4-2-u4-C50","difficulty":1,"kind":"mc","stem":"『국어』 218쪽 이런 활동 1이에요. 시를 읽고 생각이나 느낌을 나타내는 방법으로 보기에 나온 것이 아닌 것은 무엇인가요?","options":[{"t":"시를 다섯 번 베껴 쓰기","correct":true},{"t":"즉흥극으로 표현하기","mis":"K4-2-u4-X67"},{"t":"시 속 인물에게 편지 쓰기","mis":"K4-2-u4-X67"},{"t":"노래로 표현하기","mis":"K4-2-u4-X67"}],"explanation":["보기에는 즉흥극, 그림, 편지, 노래가 있어요.","이 가운데에서 고르거나 다른 창의적인 방법을 생각해도 돼요.","베껴 쓰기는 생각이나 느낌을 나타내는 방법이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_basic#2','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C68',1,'mc','auto','「마음먹기」에서 말하는 이가 먹은 마음이 아닌 것은 무엇인가요?',ARRAY['K4-2-u4-X73']::text[],false,'{"seq":2,"concept":"K4-2-u4-C68","difficulty":1,"kind":"mc","stem":"「마음먹기」에서 말하는 이가 먹은 마음이 아닌 것은 무엇인가요?","options":[{"t":"날마다 일찍 일어나자","correct":true},{"t":"동생과 사이좋게 지내자","mis":"K4-2-u4-X73"},{"t":"엄마에게 대들지 말자","mis":"K4-2-u4-X73"},{"t":"게임은 숙제 끝내고 하자","mis":"K4-2-u4-X73"}],"explanation":["시의 처음에 말하는 이가 먹은 마음이 나와요.","동생, 엄마, 게임과 숙제에 대한 마음이에요.","일찍 일어나자는 마음은 시에 나오지 않아요."],"asset":{"type":"passage","lines":["(간추림) 동생과 사이좋게 지내자, 엄마에게 대들지 말자,","(간추림) 게임은 숙제 끝내고 하자고 꼭 마음을 먹는다.","마음을 꾹꾹 먹어 보지만","꺼지는 배처럼","자꾸만 사라진다","(간추림) 그래서 마음도 밥처럼 매일매일 먹어야 하나 보다고 한다."],"title":"「마음먹기」(권용운 글) — 『국어』 218쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_basic#3','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C68',1,'mc','auto','「마음먹기」에서 꾹꾹 먹은 마음은 무엇처럼 자꾸만 사라진다고 했나요?',ARRAY['K4-2-u4-X73']::text[],false,'{"seq":3,"concept":"K4-2-u4-C68","difficulty":1,"kind":"mc","stem":"「마음먹기」에서 꾹꾹 먹은 마음은 무엇처럼 자꾸만 사라진다고 했나요?","options":[{"t":"꺼지는 배처럼","correct":true},{"t":"녹는 눈처럼","mis":"K4-2-u4-X73"},{"t":"날아가는 풍선처럼","mis":"K4-2-u4-X73"}],"explanation":["“마음을 꾹꾹 먹어 보지만”을 다시 읽어요.","바로 뒤에 “꺼지는 배처럼 / 자꾸만 사라진다”가 나와요.","배가 고파지듯 마음도 사라진다는 표현이에요."],"asset":{"type":"passage","lines":["(간추림) 동생과 사이좋게 지내자, 엄마에게 대들지 말자,","(간추림) 게임은 숙제 끝내고 하자고 꼭 마음을 먹는다.","마음을 꾹꾹 먹어 보지만","꺼지는 배처럼","자꾸만 사라진다","(간추림) 그래서 마음도 밥처럼 매일매일 먹어야 하나 보다고 한다."],"title":"「마음먹기」(권용운 글) — 『국어』 218쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_basic#4','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C52',1,'mc','auto','『국어』 219쪽 질문 사다리 타기 놀이의 질문 카드로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X28','K4-2-u4-X32']::text[],false,'{"seq":4,"concept":"K4-2-u4-C52","difficulty":1,"kind":"mc","stem":"『국어』 219쪽 질문 사다리 타기 놀이의 질문 카드로 알맞은 것은 무엇인가요?","options":[{"t":"제목을 보고 이 글이 어떤 내용이라고 예상했나요?","correct":true},{"t":"이 글은 모두 몇 줄인가요?","mis":"K4-2-u4-X28"},{"t":"글쓴이는 몇 살인가요?","mis":"K4-2-u4-X28"},{"t":"오늘 점심은 무엇인가요?","mis":"K4-2-u4-X32"}],"explanation":["질문 카드는 읽기 과정을 되돌아보는 질문이에요.","답하면 내가 어떻게 읽었는지 드러나요.","줄 수나 글쓴이 나이는 읽기와 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_basic#5','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C53',2,'mc','auto','질문 사다리 타기 놀이에서 도착한 질문 카드에 답할 때 알맞은 태도는 무엇인가요?',ARRAY['K4-2-u4-X51','K4-2-u4-X52','K4-2-u4-X50']::text[],false,'{"seq":5,"concept":"K4-2-u4-C53","difficulty":2,"kind":"mc","stem":"질문 사다리 타기 놀이에서 도착한 질문 카드에 답할 때 알맞은 태도는 무엇인가요?","options":[{"t":"질문에 답하며 자신의 읽기 과정을 되돌아보고, 답하기 어려우면 그 부분을 다시 읽는다","correct":true},{"t":"질문을 가장 많이 받은 사람이 이긴다","mis":"K4-2-u4-X51"},{"t":"가장 빨리 답한 사람이 잘한 것이다","mis":"K4-2-u4-X52"},{"t":"카드에 있는 질문 말고 다른 질문은 하면 안 된다","mis":"K4-2-u4-X50"}],"explanation":["질문 사다리는 이기는 놀이가 아니에요.","질문에 답하며 내가 어떻게 읽었는지 돌아보아요.","카드 밖의 질문도 떠올려 이야기해도 좋아요."],"asset":{"type":"passage","lines":["① 짧은 글 읽기","② 사다리 모양으로 놀이판을 그려 준비하기","③ 보기처럼 읽기 과정에서 활용할 수 있는 질문을 떠올려 질문 카드 만들기","④ 사다리 위쪽에는 이름을 쓰고 아래쪽에는 질문 카드 놓기","⑤ 사다리 타기로 도착한 질문 카드를 읽고 해당 질문에 답하기"],"title":"질문 사다리 타기 놀이 — 『국어』 219~220쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_basic#6','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C52',2,'mc','auto','질문 사다리 타기 놀이에서 처음에 읽을 짧은 글로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X07','K4-2-u4-X03']::text[],false,'{"seq":6,"concept":"K4-2-u4-C52","difficulty":2,"kind":"mc","stem":"질문 사다리 타기 놀이에서 처음에 읽을 짧은 글로 알맞은 것은 무엇인가요?","options":[{"t":"설명하는 글이나 의견을 제시하는 글 가운데 핵심 내용을 파악하기 쉬운 짧은 글","correct":true},{"t":"두꺼운 책 한 권 전체","mis":"K4-2-u4-X07"},{"t":"그림만 있고 글이 없는 책","mis":"K4-2-u4-X03"}],"explanation":["짧은 글은 읽기 과정을 점검하기에 부담이 적어요.","설명하는 글이나 의견을 제시하는 글 가운데 하나를 골라요.","핵심 내용을 파악하기 쉬운 글이 좋아요."],"asset":{"type":"passage","lines":["① 짧은 글 읽기","② 사다리 모양으로 놀이판을 그려 준비하기","③ 보기처럼 읽기 과정에서 활용할 수 있는 질문을 떠올려 질문 카드 만들기","④ 사다리 위쪽에는 이름을 쓰고 아래쪽에는 질문 카드 놓기","⑤ 사다리 타기로 도착한 질문 카드를 읽고 해당 질문에 답하기"],"title":"질문 사다리 타기 놀이 — 『국어』 219~220쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_basic#7','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C51',2,'mc','auto','친구들 앞에서 「마음먹기」를 노래로 표현한 발표를 감상했어요. 감상한 뒤 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X50','K4-2-u4-X12','K4-2-u4-X11']::text[],false,'{"seq":7,"concept":"K4-2-u4-C51","difficulty":2,"kind":"mc","stem":"친구들 앞에서 「마음먹기」를 노래로 표현한 발표를 감상했어요. 감상한 뒤 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"표현 방법과 내용에 대해 궁금한 점을 질문하거나 좋았던 점을 칭찬한다","correct":true},{"t":"그림으로 나타낸 모둠보다 못했다고 등수를 매긴다","mis":"K4-2-u4-X50"},{"t":"나와 다른 방법이니 틀렸다고 말한다","mis":"K4-2-u4-X12"},{"t":"다음 차례에 똑같이 따라 한다","mis":"K4-2-u4-X11"}],"explanation":["나타내는 방법에는 등수가 없어요.","궁금한 점을 질문하고 좋았던 점을 칭찬해요.","서로 격려하며 생각이나 느낌을 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_basic#8','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C55',2,'mc','auto','『국어』 222쪽 기초 다지기 1이에요. “주문하신 사과주스 나오셨습니다.”를 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u4-X59','K4-2-u4-X53']::text[],false,'{"seq":8,"concept":"K4-2-u4-C55","difficulty":2,"kind":"mc","stem":"『국어』 222쪽 기초 다지기 1이에요. “주문하신 사과주스 나오셨습니다.”를 바르게 고친 것은 무엇인가요?","options":[{"t":"주문하신 사과주스 나왔습니다.","correct":true},{"t":"주문하신 사과주스께서 나오셨습니다.","mis":"K4-2-u4-X59"},{"t":"주문하신 사과주스 나오셨어요.","mis":"K4-2-u4-X53"}],"explanation":["사과주스는 높일 대상이 아닌 물건이에요.","물건에 ‘-시-’를 붙이지 않아요.","그래서 ‘나왔습니다’로 고쳐요."],"asset":{"type":"passage","lines":["㉮ 교실에서 — “김치는 저희 나라의 전통 음식입니다.”","㉯ 가게에서 — “주문하신 사과주스 나오셨습니다.”"],"title":"『국어』 222쪽 기초 다지기 1"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_basic#9','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C56',2,'sa','auto','“김치는 저희 나라의 전통 음식입니다.”에서 ‘저희 나라’를 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u4-C56","difficulty":2,"kind":"sa","stem":"“김치는 저희 나라의 전통 음식입니다.”에서 ‘저희 나라’를 바르게 고쳐 쓰세요.","answer":["우리나라"],"explanation":["‘저희’는 자신을 낮추는 말이에요.","나라와 민족은 남의 나라와 비교해 낮출 수 없어요.","그래서 ‘우리나라’라고 해요."],"asset":{"type":"passage","lines":["㉮ 교실에서 — “김치는 저희 나라의 전통 음식입니다.”","㉯ 가게에서 — “주문하신 사과주스 나오셨습니다.”"],"title":"『국어』 222쪽 기초 다지기 1"},"mis":"K4-2-u4-X54"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_basic#10','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C57',3,'mc','auto','『국어』 222쪽 기초 다지기 2예요. 외국어를 우리말로 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u4-X55']::text[],false,'{"seq":10,"concept":"K4-2-u4-C57","difficulty":3,"kind":"mc","stem":"『국어』 222쪽 기초 다지기 2예요. 외국어를 우리말로 바르게 고친 것은 무엇인가요?","options":[{"t":"셀프 → 스스로, 이모티콘 → 그림말","correct":true},{"t":"셀프 → 그림말, 이모티콘 → 스스로","mis":"K4-2-u4-X55"},{"t":"셀프 → 셀프서비스, 이모티콘 → 이모지","mis":"K4-2-u4-X55"}],"explanation":["‘셀프’는 ‘스스로’로 바꿀 수 있어요.","‘이모티콘’은 ‘그림말’로 바꿀 수 있어요.","우리말로 바꾸면 누구나 쉽게 알아들어요."],"asset":{"type":"passage","lines":["㉮ 식당에서 — “물은 셀프로 가져오셔야 합니다.”","㉯ 집에서 — “친구에게 응원하는 이모티콘을 보내야지.”"],"title":"『국어』 222쪽 기초 다지기 2"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_challenge#1','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C58',2,'mc','auto','『국어』 223쪽 글씨 쓰기처럼 ‘ㄻ’ 받침이 들어간 낱말끼리 묶은 것은 무엇인가요?',ARRAY['K4-2-u4-X56']::text[],false,'{"seq":1,"concept":"K4-2-u4-C58","difficulty":2,"kind":"mc","stem":"『국어』 223쪽 글씨 쓰기처럼 ‘ㄻ’ 받침이 들어간 낱말끼리 묶은 것은 무엇인가요?","options":[{"t":"닮다 · 젊음 · 만듦새","correct":true},{"t":"닮다 · 읽다 · 넓다","mis":"K4-2-u4-X56"},{"t":"삶 · 앉다 · 굶다","mis":"K4-2-u4-X56"}],"explanation":["‘ㄻ’은 ㄹ과 ㅁ이 나란히 있는 받침이에요.","읽다는 ㄺ, 넓다는 ㄼ, 앉다는 ㄵ 받침이에요.","닮다, 젊음, 만듦새는 모두 ㄻ 받침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_challenge#2','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C68',2,'mc','auto','「마음먹기」에서 말하는 이가 마지막에 깨달은 것은 무엇인가요?',ARRAY['K4-2-u4-X73']::text[],false,'{"seq":2,"concept":"K4-2-u4-C68","difficulty":2,"kind":"mc","stem":"「마음먹기」에서 말하는 이가 마지막에 깨달은 것은 무엇인가요?","options":[{"t":"마음도 밥처럼 매일매일 먹어야 하나 보다는 것","correct":true},{"t":"마음은 한 번만 먹으면 사라지지 않는다는 것","mis":"K4-2-u4-X73"},{"t":"배가 고프면 마음먹기를 할 수 없다는 것","mis":"K4-2-u4-X73"}],"explanation":["먹은 마음이 꺼지는 배처럼 사라졌어요.","그래서 말하는 이는 마음도 밥처럼 매일 먹어야 한다고 했어요.","‘마음먹다’라는 말을 ‘밥을 먹다’에 빗댄 재미가 있어요."],"asset":{"type":"passage","lines":["(간추림) 동생과 사이좋게 지내자, 엄마에게 대들지 말자,","(간추림) 게임은 숙제 끝내고 하자고 꼭 마음을 먹는다.","마음을 꾹꾹 먹어 보지만","꺼지는 배처럼","자꾸만 사라진다","(간추림) 그래서 마음도 밥처럼 매일매일 먹어야 하나 보다고 한다."],"title":"「마음먹기」(권용운 글) — 『국어』 218쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_challenge#3','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C50',3,'mc','auto','「마음먹기」를 읽고 생각이나 느낌을 나타내려고 해요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u4-X50','K4-2-u4-X67']::text[],false,'{"seq":3,"concept":"K4-2-u4-C50","difficulty":3,"kind":"mc","stem":"「마음먹기」를 읽고 생각이나 느낌을 나타내려고 해요. 알맞은 생각은 무엇인가요?","options":[{"t":"보기의 방법 가운데에서 고르거나 다른 창의적인 방법을 생각해 나타낼 수 있다","correct":true},{"t":"보기의 네 가지 방법 말고는 쓸 수 없다","mis":"K4-2-u4-X50"},{"t":"글로 쓰는 것만 느낌을 나타내는 방법이다","mis":"K4-2-u4-X67"},{"t":"반드시 혼자서만 발표해야 한다","mis":"K4-2-u4-X50"}],"explanation":["즉흥극, 그림, 편지, 노래 가운데에서 골라도 돼요.","다른 창의적인 방법을 생각해도 좋아요.","혼자서 또는 두세 명이 함께 표현할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_challenge#4','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C52',3,'mc','auto','질문 카드 보기의 ㉮를 읽기 전 질문이라고 하는 까닭은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X32']::text[],false,'{"seq":4,"concept":"K4-2-u4-C52","difficulty":3,"kind":"mc","stem":"질문 카드 보기의 ㉮를 읽기 전 질문이라고 하는 까닭은 무엇인가요?","options":[{"t":"글을 읽지 않고 제목만 보고도 답할 수 있는 질문이기 때문","correct":true},{"t":"글을 끝까지 읽어야 답할 수 있는 질문이기 때문","mis":"K4-2-u4-X31"},{"t":"글과 상관없는 질문이기 때문","mis":"K4-2-u4-X32"}],"explanation":["㉮는 제목을 보고 어떤 내용이라고 예상했는지 물어요.","예상하기는 글을 읽기 전에 해요.","㉯는 읽으면서, ㉰·㉱는 읽으면서 찾거나 읽은 뒤에 답해요."],"asset":{"type":"passage","lines":["㉮ 제목을 보고 이 글이 어떤 내용이라고 예상했나요?","㉯ 자신이 예상한 내용과 글의 내용이 같았나요?","㉰ 글의 중심 내용이나 글쓴이의 의견은 무엇인가요?","㉱ 글을 읽고 새롭게 안 내용은 무엇인가요?"],"title":"질문 카드 보기 — 『국어』 219쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_challenge#5','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C52',3,'mc','auto','우리 반에서 정한 활동 예시 1 이야기 말판 놀이에서 붙임쪽지에 쓸 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X28','K4-2-u4-X32']::text[],false,'{"seq":5,"concept":"K4-2-u4-C52","difficulty":3,"kind":"mc","stem":"우리 반에서 정한 활동 예시 1 이야기 말판 놀이에서 붙임쪽지에 쓸 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"가장 기억에 남는 사건과 그 까닭은 무엇인가요?","correct":true},{"t":"이 책은 모두 몇 쪽인가요?","mis":"K4-2-u4-X28"},{"t":"주사위를 던지면 몇이 나오나요?","mis":"K4-2-u4-X32"}],"explanation":["이야기 말판 놀이는 생각이나 느낌을 나누는 놀이예요.","이야기를 읽고 생각이나 느낌을 말할 수 있는 질문을 써요.","“이야기를 다 읽고 나서 어떤 느낌이 들었나요?”도 좋은 질문이에요."],"asset":{"type":"passage","lines":["① 서너 명의 친구가 함께 활동한다.","② 이야기 한 편을 정해 읽고, 질문을 붙임쪽지에 각자 세 개 이상 쓴다.","③ 함께 만든 질문을 4절 도화지에 말판 모양으로 붙인다.","④ 이야기와 관련한 질문에 답하며 생각이나 느낌을 나눈다."],"title":"우리 반에서 정한 활동 예시 1 — 이야기 말판 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_challenge#6','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C5',3,'mc','auto','우리 반에서 정한 활동 예시 2 어린이 신문 읽기의 ③에 들어갈 활동은 무엇인가요?',ARRAY['K4-2-u4-X05','K4-2-u4-X06']::text[],false,'{"seq":6,"concept":"K4-2-u4-C5","difficulty":3,"kind":"mc","stem":"우리 반에서 정한 활동 예시 2 어린이 신문 읽기의 ③에 들어갈 활동은 무엇인가요?","options":[{"t":"설명하는 글인지 의견을 제시하는 글인지 확인하고, 읽기 과정을 점검할 질문을 붙임쪽지에 쓴다","correct":true},{"t":"글의 종류는 확인하지 않고 어떤 글이든 같은 질문만 쓴다","mis":"K4-2-u4-X05"},{"t":"질문을 최대한 많이 써서 붙임쪽지를 다 채운다","mis":"K4-2-u4-X06"}],"explanation":["고른 글이 어떤 종류인지 먼저 확인해요.","글의 종류에 따라 읽기 과정을 점검하는 질문이 달라요.","그 질문을 바탕으로 다시 읽으며 되돌아보아요."],"asset":{"type":"passage","lines":["① 서너 명의 친구가 함께 활동한다.","② 스마트 기기로 어린이 신문에서 관심 있는 분야의 글을 고른다.","③ (                    )","④ 질문을 바탕으로 다시 한번 글을 읽으며 읽기 과정을 되돌아본다."],"title":"우리 반에서 정한 활동 예시 2 — 어린이 신문 읽기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_challenge#7','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C55',3,'mc','auto','다음 가운데 높임 표현을 바르게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u4-X53','K4-2-u4-X54']::text[],false,'{"seq":7,"concept":"K4-2-u4-C55","difficulty":3,"kind":"mc","stem":"다음 가운데 높임 표현을 바르게 쓴 문장은 무엇인가요?","options":[{"t":"할머니께서 사과주스를 드신다.","correct":true},{"t":"주문하신 물건이 도착하셨습니다.","mis":"K4-2-u4-X53"},{"t":"저희 나라 음식이 맛있습니다.","mis":"K4-2-u4-X54"}],"explanation":["높임은 사람(할머니)에게 써요.","물건에는 ‘-시-’를 붙이지 않아요.","나라를 말할 때에는 ‘우리나라’라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_challenge#8','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C50',4,'essay','teacher','「마음먹기」를 읽고 보기의 방법 가운데 하나를 골라 생각이나 느낌을 어떻게 나타낼지 계획을 쓰세요. 고른 방법과 그 까닭, 나타낼 내용을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u4-C50","difficulty":4,"kind":"essay","stem":"「마음먹기」를 읽고 보기의 방법 가운데 하나를 골라 생각이나 느낌을 어떻게 나타낼지 계획을 쓰세요. 고른 방법과 그 까닭, 나타낼 내용을 쓰세요.","answer_guide":{"answer":"예: 시 속 인물에게 편지 쓰기 — 나도 마음을 먹어도 자꾸 잊어버린 적이 있어서 말하는 이에게 공감하는 마음을 전하고 싶다. “마음이 꺼지는 배처럼 사라져도 괜찮아. 나도 그래. 우리 밥 먹듯이 매일 다시 마음먹자.”","scoring_points":["보기의 방법 가운데 하나나 다른 창의적인 방법을 골랐는가","그 방법을 고른 까닭을 썼는가","나타낼 내용이 시에 대한 생각이나 느낌과 이어지는가"]},"explanation":["즉흥극, 그림, 편지, 노래 가운데에서 골라요.","그 방법이 내 생각이나 느낌을 잘 드러내는지 생각해요.","발표한 뒤 친구들의 질문과 칭찬을 들어요."],"asset":{"type":"passage","lines":["(간추림) 동생과 사이좋게 지내자, 엄마에게 대들지 말자,","(간추림) 게임은 숙제 끝내고 하자고 꼭 마음을 먹는다.","마음을 꾹꾹 먹어 보지만","꺼지는 배처럼","자꾸만 사라진다","(간추림) 그래서 마음도 밥처럼 매일매일 먹어야 하나 보다고 한다."],"title":"「마음먹기」(권용운 글) — 『국어』 218쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_challenge#9','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C52',4,'essay','teacher','질문 사다리 타기 놀이에 쓸 질문 카드를 읽기 전, 읽기 중, 읽기 후에 하나씩 만들어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u4-C52","difficulty":4,"kind":"essay","stem":"질문 사다리 타기 놀이에 쓸 질문 카드를 읽기 전, 읽기 중, 읽기 후에 하나씩 만들어 쓰세요.","answer_guide":{"answer":"예: 읽기 전 — 제목을 보고 이 글이 어떤 내용이라고 예상했나요? / 읽기 중 — 글쓴이의 의견을 뒷받침하는 이유가 적절한가요? / 읽기 후 — 글을 읽고 더 알고 싶은 내용은 무엇인가요?","scoring_points":["읽기 전·중·후 질문을 하나씩 만들었는가","각 질문이 그 과정에 알맞은가","답하면 자신의 읽기 과정이 드러나는 질문인가"]},"explanation":["『국어』 219쪽 보기 질문을 참고해요.","줄 수나 글쓴이 나이처럼 읽기와 상관없는 질문은 쓰지 않아요.","답하며 내 읽기를 되돌아볼 수 있는 질문이 좋아요."],"asset":{"type":"passage","lines":["㉮ 제목을 보고 이 글이 어떤 내용이라고 예상했나요?","㉯ 자신이 예상한 내용과 글의 내용이 같았나요?","㉰ 글의 중심 내용이나 글쓴이의 의견은 무엇인가요?","㉱ 글을 읽고 새롭게 안 내용은 무엇인가요?"],"title":"질문 카드 보기 — 『국어』 219쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_L13_challenge#10','kor',4,2,'u4','L13','tb_g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C57',4,'essay','teacher','일상생활에서 쓰는 외국어를 하나 떠올려 우리말로 바꾸어 쓰고, 외국어 대신 우리말을 쓰면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C57","difficulty":4,"kind":"essay","stem":"일상생활에서 쓰는 외국어를 하나 떠올려 우리말로 바꾸어 쓰고, 외국어 대신 우리말을 쓰면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 셀프 → 스스로 / 우리말을 쓰면 외국어를 모르는 사람도 쉽게 알아들을 수 있고, 한글을 아끼고 사랑하는 마음을 나타낼 수 있다.","scoring_points":["일상에서 쓰는 외국어를 하나 떠올렸는가","알맞은 우리말로 바꾸었는가","우리말을 쓰면 좋은 점을 썼는가"]},"explanation":["『국어』 222쪽 셀프, 이모티콘처럼 자주 쓰는 외국어를 떠올려요.","뜻이 같은 우리말을 찾아 바꾸어요.","한글을 아끼는 마음으로 우리말을 써요."],"asset":{"type":"passage","lines":["㉮ 식당에서 — “물은 셀프로 가져오셔야 합니다.”","㉯ 집에서 — “친구에게 응원하는 이모티콘을 보내야지.”"],"title":"『국어』 222쪽 기초 다지기 2"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#1','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C27',1,'ox','auto','『국어』 221쪽 스스로 확인하기의 돌 ㉮ 「글을 읽기 전에 제목을 보고 어떤 내용일지 예상해 봐.」는 바른 길이에요.',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":1,"concept":"K4-2-u4-C27","difficulty":1,"kind":"ox","stem":"『국어』 221쪽 스스로 확인하기의 돌 ㉮ 「글을 읽기 전에 제목을 보고 어떤 내용일지 예상해 봐.」는 바른 길이에요.","answer":"O","reason_options":[{"t":"읽기 전에는 제목이나 차례를 보며 내용을 예상해요.","correct":true},{"t":"제목은 글을 다 읽은 뒤에만 봐요.","mis":"K4-2-u4-X30"}],"mis":"K4-2-u4-X30","explanation":["길 찾기는 읽기 과정을 되돌아보는 바른 방법을 찾는 활동이에요.","읽기 전에는 제목을 보고 어떤 내용일지 예상해요.","이 돌은 바른 길이에요."],"asset":{"type":"passage","lines":["㉮ 글을 읽기 전에 제목을 보고 어떤 내용일지 예상해 봐.","㉯ 글의 내용은 빠짐없이 기억해야 해.","㉰ 예상한 내용과 글의 내용이 같은지 확인해 보면 좋아.","㉱ 예상한 내용과 글의 내용은 꼭 같아야 해.","㉲ 의견을 제시하는 글에서 글쓴이의 의견은 무조건 옳다고 믿으면 돼.","㉳ 시나 이야기를 읽고 떠올린 경험은 모두가 똑같아.","㉴ 설명하는 글에서는 글의 중심 내용을 찾으며 읽으면 좋아."],"title":"『국어』 221쪽 스스로 확인하기 — 바른 길 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#2','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C1',1,'mc','auto','『국어』 183쪽 「무엇을 배울까요」에서 소단원 2에서 배우는 내용이 아닌 것은 무엇인가요?',ARRAY['K4-2-u4-X01']::text[],false,'{"seq":2,"concept":"K4-2-u4-C1","difficulty":1,"kind":"mc","stem":"『국어』 183쪽 「무엇을 배울까요」에서 소단원 2에서 배우는 내용이 아닌 것은 무엇인가요?","options":[{"t":"이야기를 읽고 생각이나 느낌 나누기","correct":true},{"t":"읽기 과정을 되돌아볼 수 있는 질문 알기","mis":"K4-2-u4-X01"},{"t":"설명하는 글을 읽고 읽기 과정 되돌아보기","mis":"K4-2-u4-X01"},{"t":"의견을 제시하는 글을 읽고 읽기 과정 되돌아보기","mis":"K4-2-u4-X01"}],"explanation":["소단원 1은 시와 이야기를 읽고 생각이나 느낌을 나누어요.","소단원 2는 질문을 활용해 읽기 과정을 되돌아보아요.","이야기를 읽고 생각이나 느낌 나누기는 소단원 1이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#3','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C59',1,'sa','auto','「기뻐의 비밀」에서 ‘기뻐’ 안에 들어 있다고 한 낱말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u4-C59","difficulty":1,"kind":"sa","stem":"「기뻐의 비밀」에서 ‘기뻐’ 안에 들어 있다고 한 낱말을 쓰세요.","answer":["이뻐"],"explanation":["“기뻐 안에는”을 읽어요.","다음 줄에 “이뻐가 들어 있다”라고 했어요.","‘기’를 늘이면 ‘이뻐’가 들려요."],"asset":{"type":"passage","lines":["내가 기뻐의 비밀을 말해 줄까?","기뻐 안에는","이뻐가 들어 있다","(간추림) 왼손으로 ‘기’, 오른손으로 ‘뻐’를 잡고 고무줄처럼 늘이면","(간추림) ‘기’와 ‘뻐’ 사이가 ‘이’로 길게 이어진다."],"title":"「기뻐의 비밀」(이안 글) 앞부분 — 『국어』 184쪽"},"mis":"K4-2-u4-X65"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#4','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C60',1,'mc','auto','「네 생각을 솔직히 말해」에서 승한이가 선물 가게에서 사려고 한 가방은 어떤 가방이었나요?',ARRAY['K4-2-u4-X60']::text[],false,'{"seq":4,"concept":"K4-2-u4-C60","difficulty":1,"kind":"mc","stem":"「네 생각을 솔직히 말해」에서 승한이가 선물 가게에서 사려고 한 가방은 어떤 가방이었나요?","options":[{"t":"버지5가 아닌, 아저씨가 좋다고 한 다른 가방","correct":true},{"t":"전부터 가지고 싶다고 한 버지5 가방","mis":"K4-2-u4-X60"},{"t":"서영이가 가지고 싶어 한 가방","mis":"K4-2-u4-X60"},{"t":"진우가 골라 준 가방","mis":"K4-2-u4-X60"}],"explanation":["승한이는 전부터 버지5 가방을 가지고 싶다고 했어요.","그런데 아저씨가 다 떨어졌다며 다른 가방을 권했어요.","승한이는 싫다는 말을 못 하고 그 가방을 사려 했어요."],"asset":{"type":"passage","lines":["(간추림) 진우와 서영이는 승한이가 선물 가게로 들어가는 것을 보고 따라갔다.","(간추림) 승한이는 막 계산을 마치고 가방을 받고 있었다.","“야! 정승한. 너 이 가방, 버지5 아니잖아.”","“그, 그게……. 버지5도 좋은데 아저씨가 지금은 다 떨어졌다고 해서.","이 가방도 좋은 거래.”"],"title":"「네 생각을 솔직히 말해」(신지영 글) 선물 가게 — 『국어』 188~189쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#5','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C62',1,'blank','auto','「서영이의 (     )에 승한이가 우물쭈물하더니 기어드는 소리로 말했다.」 빈칸에 알맞은 낱말은 무엇인가요?',ARRAY['K4-2-u4-X64']::text[],false,'{"seq":5,"concept":"K4-2-u4-C62","difficulty":1,"kind":"blank","stem":"「서영이의 (     )에 승한이가 우물쭈물하더니 기어드는 소리로 말했다.」 빈칸에 알맞은 낱말은 무엇인가요?","options":[{"t":"추궁","correct":true},{"t":"교정","mis":"K4-2-u4-X64"},{"t":"경청","mis":"K4-2-u4-X64"}],"explanation":["서영이가 승한이를 엄하게 따져 묻는 장면이에요.","잘못한 일을 엄하게 따져서 밝히는 것을 ‘추궁’이라고 해요.","승한이는 우물쭈물하며 작게 대답했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#6','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C27',1,'mc','auto','다음 가운데 읽기 전에 할 수 있는 활동은 무엇인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":6,"concept":"K4-2-u4-C27","difficulty":1,"kind":"mc","stem":"다음 가운데 읽기 전에 할 수 있는 활동은 무엇인가요?","options":[{"t":"자신이 알고 있는 내용 떠올리기","correct":true},{"t":"글 전체의 내용을 요약하여 정리하기","mis":"K4-2-u4-X30"},{"t":"새롭게 안 내용 파악하기","mis":"K4-2-u4-X30"},{"t":"더 알고 싶은 내용 생각하기","mis":"K4-2-u4-X30"}],"explanation":["읽기 전에는 아직 글을 읽지 않았어요.","제목을 보고 예상하거나 알고 있는 내용을 떠올려요.","요약과 더 알고 싶은 내용은 읽기 후에 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#7','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C34',1,'ox','auto','조립 설명서, 소개 글, 음식 조리 방법, 안내문은 모두 설명하는 글이에요.',ARRAY['K4-2-u4-X34']::text[],false,'{"seq":7,"concept":"K4-2-u4-C34","difficulty":1,"kind":"ox","stem":"조립 설명서, 소개 글, 음식 조리 방법, 안내문은 모두 설명하는 글이에요.","answer":"O","reason_options":[{"t":"모두 어떤 지식이나 정보를 이해하기 쉽게 전달하는 글이에요.","correct":true},{"t":"설명하는 글은 책에 실린 긴 글만을 말해요.","mis":"K4-2-u4-X34"}],"mis":"K4-2-u4-X34","explanation":["설명하는 글은 지식이나 정보를 전달해요.","생활 속 설명서나 안내문도 설명하는 글이에요.","『국어』 204쪽 친구들도 설명서, 책, 조리법을 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#8','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C55',1,'sa','auto','“주문하신 사과주스 나오셨습니다.”에서 잘못 쓴 부분을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u4-C55","difficulty":1,"kind":"sa","stem":"“주문하신 사과주스 나오셨습니다.”에서 잘못 쓴 부분을 바르게 고쳐 쓰세요.","answer":["나왔습니다","나왔습니다."],"explanation":["사과주스는 물건이에요.","물건에는 ‘-시-’를 붙여 높이지 않아요.","‘나오셨습니다’를 ‘나왔습니다’로 고쳐요."],"asset":{"type":"passage","lines":["㉮ 교실에서 — “김치는 저희 나라의 전통 음식입니다.”","㉯ 가게에서 — “주문하신 사과주스 나오셨습니다.”"],"title":"『국어』 222쪽 기초 다지기 1"},"mis":"K4-2-u4-X53"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#9','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C5',2,'mc','auto','「이 글은 무엇에 대해 자세하게 알려 주고 있나요?」는 어떤 글을 읽고 떠올린 질문인가요?',ARRAY['K4-2-u4-X05']::text[],false,'{"seq":9,"concept":"K4-2-u4-C5","difficulty":2,"kind":"mc","stem":"「이 글은 무엇에 대해 자세하게 알려 주고 있나요?」는 어떤 글을 읽고 떠올린 질문인가요?","options":[{"t":"설명하는 글","correct":true},{"t":"시나 이야기","mis":"K4-2-u4-X05"},{"t":"의견을 제시하는 글","mis":"K4-2-u4-X05"}],"explanation":["무엇에 대해 알려 주는지 묻고 있어요.","지식이나 정보를 알려 주는 글은 설명하는 글이에요.","『국어』 183쪽 3번에서 선으로 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#10','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C10',2,'mc','auto','시를 읽고 떠올린 생각이나 느낌을 나타내는 방법으로 알맞은 것을 모두 고른 것은 무엇인가요?',ARRAY['K4-2-u4-X67']::text[],false,'{"seq":10,"concept":"K4-2-u4-C10","difficulty":2,"kind":"mc","stem":"시를 읽고 떠올린 생각이나 느낌을 나타내는 방법으로 알맞은 것을 모두 고른 것은 무엇인가요?","options":[{"t":"㉠, ㉡, ㉢, ㉣","correct":true},{"t":"㉠, ㉡ — 말이나 글로만 나타낸다","mis":"K4-2-u4-X67"},{"t":"㉣ — 색깔이나 모양으로만 나타낸다","mis":"K4-2-u4-X67"}],"explanation":["생각이나 느낌은 말과 글로 나타낼 수 있어요.","표정, 소리, 동작으로도 나타낼 수 있어요.","『국어』 185쪽처럼 색깔이나 모양으로도 나타내요."],"asset":{"type":"passage","lines":["㉠ 말로 이야기하기","㉡ 글로 쓰기","㉢ 표정, 소리, 동작으로 나타내기","㉣ 색깔이나 모양으로 나타내기"],"title":"생각이나 느낌을 나타내는 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#11','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C19',2,'mc','auto','역할놀이에서 서영이의 성격을 잘 드러내는 말투는 무엇인가요?',ARRAY['K4-2-u4-X22']::text[],false,'{"seq":11,"concept":"K4-2-u4-C19","difficulty":2,"kind":"mc","stem":"역할놀이에서 서영이의 성격을 잘 드러내는 말투는 무엇인가요?","options":[{"t":"말의 속도가 빠르고 다소 높은 목소리","correct":true},{"t":"천천히, 느리게 말하는 목소리","mis":"K4-2-u4-X22"},{"t":"단단하면서도 차분한 목소리","mis":"K4-2-u4-X22"}],"explanation":["서영이는 자기 생각을 거리낌 없이 표현해요.","그래서 빠르고 다소 높은 목소리가 어울려요.","차분한 목소리는 진우, 느린 말투는 승한이에게 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#12','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C30',2,'blank','auto','『국어』 209쪽 읽기 후 ㉡에 붙일 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X31']::text[],false,'{"seq":12,"concept":"K4-2-u4-C30","difficulty":2,"kind":"blank","stem":"『국어』 209쪽 읽기 후 ㉡에 붙일 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"읽은 내용을 요약했나요?","correct":true},{"t":"제목을 보고 어떤 내용일지 예상했나요?","mis":"K4-2-u4-X31"},{"t":"자신이 알고 있는 내용을 떠올렸나요?","mis":"K4-2-u4-X31"}],"explanation":["읽기 후에는 읽은 내용을 요약해요.","그다음 더 알고 싶은 내용을 생각해요.","예상하기와 알고 있는 내용 떠올리기는 읽기 전이에요."],"asset":{"type":"passage","lines":["[읽기 전] (     ㉠     )","[읽기 전] 글을 읽기 전에 제목을 보고 자신이 알고 있는 내용을 떠올렸나요?","[읽기 중] 자신이 예상한 내용이 글의 내용과 같은지 확인했나요?","[읽기 중] 글의 중심 내용을 찾으며 읽었나요?","[읽기 중] 새롭게 안 내용을 찾으며 읽었나요?","[읽기 후] (     ㉡     )","[읽기 후] 더 알고 싶은 내용을 생각했나요?","‘예’면 다음 질문으로, ‘아니요’면 「이렇게 해 보세요」로 가요."],"title":"『국어』 209쪽 — 질문을 활용해 읽기 과정 되돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#13','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C63',2,'mc','auto','「화살나무를 아시나요?」에서 화살나무를 관심만 가지면 쉽게 찾아볼 수 있다고 한 까닭은 무엇인가요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":13,"concept":"K4-2-u4-C63","difficulty":2,"kind":"mc","stem":"「화살나무를 아시나요?」에서 화살나무를 관심만 가지면 쉽게 찾아볼 수 있다고 한 까닭은 무엇인가요?","options":[{"t":"아파트 정원이나 공원, 도로변에 많이 심겨 있기 때문","correct":true},{"t":"꽃이 크고 화려해서 멀리서도 보이기 때문","mis":"K4-2-u4-X35"},{"t":"깊은 산속에서만 자라기 때문","mis":"K4-2-u4-X35"}],"explanation":["첫째 문단을 다시 읽어요.","화살나무는 아파트 정원, 공원, 도로변에 많이 심겨 있어요.","꽃은 작아서 눈에 잘 띄지 않아요."],"asset":{"type":"passage","lines":["봄날의 화려한 꽃이 지고 필 때 눈에 띄지 않게 꽃이 피는 식물이","있습니다. 바로 화살나무입니다.","(간추림) 아파트 정원이나 공원, 도로변에 많이 심겨 있어 쉽게 찾아볼 수 있다.","(간추림) 이름이 어떻게 붙었는지는 가지를 보면 알 수 있다."],"title":"「화살나무를 아시나요?」(신영준 글·사진) 첫째 문단 — 『국어』 201쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#14','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C66',2,'mc','auto','「저작권을 왜 지켜야 하나요?」에서 창작자에게는 어떤 권리가 있다고 했나요?',ARRAY['K4-2-u4-X72','K4-2-u4-X35']::text[],false,'{"seq":14,"concept":"K4-2-u4-C66","difficulty":2,"kind":"mc","stem":"「저작권을 왜 지켜야 하나요?」에서 창작자에게는 어떤 권리가 있다고 했나요?","options":[{"t":"자신이 만든 창작물을 다른 사람이 이용할 수 있도록 허락하거나 허락하지 않을 권리","correct":true},{"t":"다른 사람의 창작물을 허락 없이 쓸 권리","mis":"K4-2-u4-X72"},{"t":"창작물을 아무도 보지 못하게 숨길 의무","mis":"K4-2-u4-X35"}],"explanation":["창작물은 만든 사람의 것이에요.","그래서 이용을 허락할지 말지 정할 권리가 있어요.","우리는 허락을 받고 창작물을 이용해야 해요."],"asset":{"type":"passage","lines":["저작권이란 사람의 생각 또는 감정을 표현한 창작물에 대하여","이를 만든 사람이 가지는 권리를 말합니다.","(간추림) 창작자가 창작물에 들인 시간과 노력을 인정하고 보호해 주어야 한다.","(간추림) 창작자에게는 이용을 허락하거나 허락하지 않을 권리가 있다.","(간추림) 그러므로 만든 사람에게 허락을 받고 창작물을 이용해야 한다."],"title":"「저작권을 왜 지켜야 하나요?」 둘째 문단 — 『국어』 213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#15','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C50',2,'mc','auto','『국어』 218쪽 활동처럼 시를 읽고 생각이나 느낌을 발표하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X50']::text[],false,'{"seq":15,"concept":"K4-2-u4-C50","difficulty":2,"kind":"mc","stem":"『국어』 218쪽 활동처럼 시를 읽고 생각이나 느낌을 발표하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"혼자서 또는 두세 명이 함께 표현할 수 있다","correct":true},{"t":"반 전체가 같은 방법으로만 발표해야 한다","mis":"K4-2-u4-X50"},{"t":"발표한 방법마다 등수를 매긴다","mis":"K4-2-u4-X50"}],"explanation":["혼자 해도 되고 두세 명이 함께 해도 돼요.","나타내는 방법은 저마다 고를 수 있어요.","방법에는 등수가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#16','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C49',2,'mc','auto','『국어활동』 57쪽에서 ‘예’가 6~7개면 「당신은 읽기 전문가!」라고 했어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u4-X40','K4-2-u4-X41']::text[],false,'{"seq":16,"concept":"K4-2-u4-C49","difficulty":2,"kind":"mc","stem":"『국어활동』 57쪽에서 ‘예’가 6~7개면 「당신은 읽기 전문가!」라고 했어요. 알맞은 생각은 무엇인가요?","options":[{"t":"‘예’ 개수보다 ‘아니요’가 나온 부분을 찾아 다음에 노력할 점으로 삼는다","correct":true},{"t":"읽기 전문가가 되려고 모두 ‘예’에 표시한다","mis":"K4-2-u4-X40"},{"t":"빨리 표시하고 끝낸다","mis":"K4-2-u4-X41"}],"explanation":["점검은 나를 위해 솔직하게 해요.","‘아니요’가 나온 곳이 다음에 노력할 점이에요.","그 점을 다짐으로 써 보아요."],"asset":{"type":"passage","lines":["내가 읽은 글 — 「시장이란 무엇인가요?」","글의 내용 — 시장의 뜻과 종류, 특징을 설명하고 있습니다.","‘예’가 6~7개 — 당신은 읽기 전문가!","‘예’가 3~5개 — 글을 읽을 때 질문하며 생각하는 습관을 조금 더 길러 보세요.","‘예’가 0~2개 — 『국어』에서 공부한 내용을 떠올려 보세요."],"title":"『국어활동』 56~57쪽 실력 키우기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#17','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C12',3,'mc','auto','『국어』 187쪽 대문책의 맨 앞 장과 맨 뒷장에는 무엇을 쓰나요?',ARRAY['K4-2-u4-X15']::text[],false,'{"seq":17,"concept":"K4-2-u4-C12","difficulty":3,"kind":"mc","stem":"『국어』 187쪽 대문책의 맨 앞 장과 맨 뒷장에는 무엇을 쓰나요?","options":[{"t":"찾은 낱말을 한 글자씩 쓰고, 중간도 늘인 소리로 채운다","correct":true},{"t":"시의 제목만 쓴다","mis":"K4-2-u4-X15"},{"t":"짝의 이름을 쓴다","mis":"K4-2-u4-X15"}],"explanation":["대문책은 도화지를 이어 붙여 길게 만들어요.","맨 앞 장과 맨 뒷장에 찾은 낱말을 한 글자씩 써요.","예를 들어 ‘기’와 ‘뻐’를 쓰고 중간을 ‘이’로 채워요."],"asset":{"type":"passage","lines":["① 도화지를 준비해 가로로 반을 자른다.","② 자른 도화지 두 장을 겹쳐 반을 접고, 뒤집어서 대문 접기를 한다.","③ 도화지를 테이프로 이어 붙인다. 겹치는 부분이 없게 한다.","④ 맨 앞 장과 맨 뒷장에 찾은 낱말을 한 글자씩 쓰고 중간도 채운다."],"title":"대문책 만드는 방법 — 『국어』 187쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#18','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C25',3,'mc','auto','진우가 서영이와 승한이에게 한 말을 바르게 정리한 것은 무엇인가요?',ARRAY['K4-2-u4-X29']::text[],false,'{"seq":18,"concept":"K4-2-u4-C25","difficulty":3,"kind":"mc","stem":"진우가 서영이와 승한이에게 한 말을 바르게 정리한 것은 무엇인가요?","options":[{"t":"승한이에게는 무조건 양보하는 것은 도망치는 것이라고, 서영이에게는 상대방의 입장에서 생각하고 말해야 한다고 했다","correct":true},{"t":"승한이만 잘못했고 서영이는 다 옳다고 했다","mis":"K4-2-u4-X29"},{"t":"서영이만 잘못했고 승한이는 다 옳다고 했다","mis":"K4-2-u4-X29"}],"explanation":["진우는 두 친구 모두에게 고칠 점을 말했어요.","승한이는 자기 마음을 속이고 피했어요.","서영이는 상대의 입장을 생각하지 않고 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#19','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C30',3,'mc','auto','「약, 잘 쓰고 잘 버리는 방법」을 펴기 전, 제목만 보고 답할 수 있는 질문은 무엇인가요?',ARRAY['K4-2-u4-X31']::text[],false,'{"seq":19,"concept":"K4-2-u4-C30","difficulty":3,"kind":"mc","stem":"「약, 잘 쓰고 잘 버리는 방법」을 펴기 전, 제목만 보고 답할 수 있는 질문은 무엇인가요?","options":[{"t":"이 글은 약을 어떻게 쓰고 버리는지 알려 주는 글일까?","correct":true},{"t":"글에서 내성이란 무슨 뜻이라고 했나요?","mis":"K4-2-u4-X31"},{"t":"글 전체의 내용을 요약했나요?","mis":"K4-2-u4-X31"}],"explanation":["읽기 전에는 제목만 보고 내용을 예상해요.","내성의 뜻은 글을 읽어야 알 수 있어요.","요약은 다 읽은 뒤에 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#20','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C37',3,'mc','auto','「약, 잘 쓰고 잘 버리는 방법」에서 약 보관에 관한 문단의 중심 문장으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X37']::text[],false,'{"seq":20,"concept":"K4-2-u4-C37","difficulty":3,"kind":"mc","stem":"「약, 잘 쓰고 잘 버리는 방법」에서 약 보관에 관한 문단의 중심 문장으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"약은 반드시 상자와 사용 설명서를 함께 보관하고, 설명서에 적힌 보관법대로 보관해야 해요.","correct":true},{"t":"약국에서 약을 사면 상자에 소비 기한이 적혀 있지요?","mis":"K4-2-u4-X37"},{"t":"소비 기한은 적절하게 보관했을 경우에 적용되거든요.","mis":"K4-2-u4-X37"}],"explanation":["중심 문장은 그 문단에서 가장 중요한 내용을 담고 있어요.","나머지 문장은 왜 그렇게 해야 하는지 자세히 풀어 줘요.","첫 문장이 늘 중심 문장은 아니에요."],"asset":{"type":"passage","lines":["약도 우유나 빵처럼 소비 기한이 있다는 사실, 알고 있나요?","(간추림) 소비 기한이 지나면 약효가 떨어질 뿐 아니라 상할 수도 있다.","(간추림) 약은 반드시 상자와 사용 설명서를 함께 보관해야 한다.","(간추림) 설명서에 적힌 보관법대로 보관해야 한다.","(간추림) 소비 기한은 적절하게 보관했을 경우에 적용된다."],"title":"「약, 잘 쓰고 잘 버리는 방법」 보관하기 — 『국어』 205쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#21','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C45',3,'mc','auto','「저작권을 지켜야 한다」는 의견을 뒷받침하는 이유가 적절한지 살피는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X47','K4-2-u4-X46']::text[],false,'{"seq":21,"concept":"K4-2-u4-C45","difficulty":3,"kind":"mc","stem":"「저작권을 지켜야 한다」는 의견을 뒷받침하는 이유가 적절한지 살피는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"그 이유가 저작권을 지키면 좋은 점이나 지키지 않으면 생기는 문제와 이어지는지 살핀다","correct":true},{"t":"내가 그 의견에 찬성하면 적절한 이유라고 본다","mis":"K4-2-u4-X47"},{"t":"이유가 길고 많으면 적절하다고 본다","mis":"K4-2-u4-X46"}],"explanation":["이유는 의견을 받쳐 주어야 해요.","의견과 이어지는지 따져요.","찬성하는지와 상관없이 판단해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#22','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C33',3,'mc','auto','글을 읽을 때 읽기 과정에 따른 활동을 쓰는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X07','K4-2-u4-X06']::text[],false,'{"seq":22,"concept":"K4-2-u4-C33","difficulty":3,"kind":"mc","stem":"글을 읽을 때 읽기 과정에 따른 활동을 쓰는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"매번 모두 하는 것이 아니라 그때그때 상황에 맞는 것을 스스로 골라 쓴다","correct":true},{"t":"어떤 글이든 모든 활동을 빠짐없이 다 한다","mis":"K4-2-u4-X07"},{"t":"질문은 많이 만들수록 좋으니 최대한 많이 만든다","mis":"K4-2-u4-X06"}],"explanation":["읽기 과정에 따른 활동은 예시예요.","상황에 맞게 알맞은 것을 골라요.","많이, 빠짐없이 하는 것이 목표가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#23','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C14',4,'essay','teacher','「네 생각을 솔직히 말해」에서 인상 깊은 인물의 말이나 행동을 하나 찾아 쓰고, 그에 대한 자신의 생각이나 느낌을 관련 있는 경험과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u4-C14","difficulty":4,"kind":"essay","stem":"「네 생각을 솔직히 말해」에서 인상 깊은 인물의 말이나 행동을 하나 찾아 쓰고, 그에 대한 자신의 생각이나 느낌을 관련 있는 경험과 함께 쓰세요.","answer_guide":{"answer":"예: 진우가 “그건 참는 게 아니라 도망치는 거니까.”라고 한 말이 인상 깊었다. 나도 친구가 하자는 대로만 하고 내가 하고 싶은 것은 말하지 못한 적이 있다. 진우의 말을 듣고 나도 내 마음을 솔직하게 말해야겠다고 생각했다.","scoring_points":["인상 깊은 인물의 말이나 행동을 이야기에서 찾았는가","그에 대한 자신의 생각이나 느낌을 썼는가","관련 있는 경험이 드러나게 썼는가"]},"explanation":["정답이 없으니 떠올린 생각이나 느낌을 자유롭게 써요.","인상 깊은 부분과 관련 있는 경험을 함께 써요.","친구와 바꾸어 읽으며 공감해 보아요."],"asset":{"type":"passage","lines":["[표] 인물 · 인물의 말이나 행동 · 자신의 생각이나 느낌","1 인물의 말이나 행동에 대한 자신의 생각이나 느낌을 정리해 봅시다.","2 등장인물에게 마음을 담아 편지를 써 봅시다."],"title":"문학 작품을 읽고 자신의 생각이나 느낌 표현하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#24','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C30',4,'essay','teacher','설명하는 글이나 의견을 제시하는 글을 하나 골라 읽고, 읽기 전·중·후에 떠오른 생각과 활용한 질문을 표처럼 하나씩 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u4-C30","difficulty":4,"kind":"essay","stem":"설명하는 글이나 의견을 제시하는 글을 하나 골라 읽고, 읽기 전·중·후에 떠오른 생각과 활용한 질문을 표처럼 하나씩 쓰세요.","answer_guide":{"answer":"예: 「약, 잘 쓰고 잘 버리는 방법」 — 읽기 전: 생각 “약을 버리는 방법이 나오겠지.” / 질문 「제목을 보고 어떤 내용일지 예상했나요?」 · 읽기 중: 생각 “쓰레기통에 버리면 안 되는구나.” / 질문 「새롭게 안 내용을 찾으며 읽었나요?」 · 읽기 후: 생각 “수거함의 약은 어떻게 처리될까?” / 질문 「더 알고 싶은 내용을 생각했나요?」","scoring_points":["읽기 전·중·후에 떠오른 생각을 썼는가","각 과정에 알맞은 질문을 이어 썼는가","떠오른 생각과 질문이 서로 이어지는가"]},"explanation":["글을 읽으며 든 생각을 과정마다 적어요.","그 생각과 이어지는 질문을 찾아 써요.","결과만이 아니라 생각과 질문을 함께 써요."],"asset":{"type":"passage","lines":["[표] 과정 · 떠오른 생각 · 활용한 질문","읽기 전 · (          ) · (          )","읽기 중 · (          ) · (          )","읽기 후 · (          ) · (          )"],"title":"글을 읽고 자신의 읽기 과정 되돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_a#25','kor',4,2,'u4','','tb_g4_2_kor_u4_review_a','unit_review','K4-2-u4-C1',4,'essay','teacher','『국어』 221쪽 「생활 속으로」처럼 이 단원에서 공부한 내용을 생활 속에서 어떻게 실천할지 다짐을 쓰세요. 언제, 무엇을 할지 구체적으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u4-C1","difficulty":4,"kind":"essay","stem":"『국어』 221쪽 「생활 속으로」처럼 이 단원에서 공부한 내용을 생활 속에서 어떻게 실천할지 다짐을 쓰세요. 언제, 무엇을 할지 구체적으로 쓰세요.","answer_guide":{"answer":"예: 도서관에서 책을 빌려 읽을 때 먼저 제목과 차례를 보고 내용을 예상하고, 다 읽은 뒤에는 중요한 내용을 공책에 짧게 요약하겠다. 시를 읽으면 떠오른 느낌을 그림으로도 나타내 보겠다.","scoring_points":["이 단원에서 배운 내용과 이어지는 다짐인가","언제, 무엇을 할지 구체적으로 썼는가","실천할 수 있는 다짐인가"]},"explanation":["세 친구의 다짐을 떠올려요.","작품 감상과 읽기 과정 되돌아보기 가운데 실천할 것을 골라요.","실천했는지 알 수 있게 구체적으로 써요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“작품을 읽고 생각이나 느낌을 다양하게 표현할 거야.”"},{"who":"친구 2","text":"“책을 읽고 나서 내용을 잘 기억할 수 있게 여러 가지 질문을 활용해 볼래.”"},{"who":"친구 3","text":"“글을 읽고 나서 질문을 활용해 나의 읽기 과정을 되돌아볼 거야.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#1','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C38',1,'ox','auto','스스로 확인하기의 돌 ㉯ 「글의 내용은 빠짐없이 기억해야 해.」는 바른 길이에요.',ARRAY['K4-2-u4-X68']::text[],false,'{"seq":1,"concept":"K4-2-u4-C38","difficulty":1,"kind":"ox","stem":"스스로 확인하기의 돌 ㉯ 「글의 내용은 빠짐없이 기억해야 해.」는 바른 길이에요.","answer":"X","reason_options":[{"t":"글의 내용을 빠짐없이 외우는 것이 아니라 중요한 내용을 찾아 요약해요.","correct":true},{"t":"잘 읽으려면 글의 모든 문장을 다 기억해야 해요.","mis":"K4-2-u4-X68"}],"mis":"K4-2-u4-X68","explanation":["글을 잘 읽는다는 것은 모든 문장을 외우는 것이 아니에요.","중심 내용을 찾고 읽은 내용을 요약해요.","이 돌은 바른 길이 아니에요."],"asset":{"type":"passage","lines":["㉮ 글을 읽기 전에 제목을 보고 어떤 내용일지 예상해 봐.","㉯ 글의 내용은 빠짐없이 기억해야 해.","㉰ 예상한 내용과 글의 내용이 같은지 확인해 보면 좋아.","㉱ 예상한 내용과 글의 내용은 꼭 같아야 해.","㉲ 의견을 제시하는 글에서 글쓴이의 의견은 무조건 옳다고 믿으면 돼.","㉳ 시나 이야기를 읽고 떠올린 경험은 모두가 똑같아.","㉴ 설명하는 글에서는 글의 중심 내용을 찾으며 읽으면 좋아."],"title":"『국어』 221쪽 스스로 확인하기 — 바른 길 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#2','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C2',1,'ox','auto','『국어』 181쪽 「생각 열기」에서 책을 읽고 기억나는 내용이 없었던 남자아이는 책을 읽기만 했어요.',ARRAY['K4-2-u4-X02']::text[],false,'{"seq":2,"concept":"K4-2-u4-C2","difficulty":1,"kind":"ox","stem":"『국어』 181쪽 「생각 열기」에서 책을 읽고 기억나는 내용이 없었던 남자아이는 책을 읽기만 했어요.","answer":"O","reason_options":[{"t":"남자아이는 내용을 짐작하거나 이해했는지 확인하지 않고 읽기만 했어요.","correct":true},{"t":"책을 끝까지 읽기만 하면 내용이 저절로 기억나요.","mis":"K4-2-u4-X02"}],"mis":"K4-2-u4-X02","explanation":["여자아이는 짐작하고 확인하고 정리하며 읽었어요.","남자아이는 그런 활동 없이 읽기만 했어요.","읽는 동안 무엇을 하느냐가 중요해요."],"asset":{"type":"speech","turns":[{"who":"남자아이 — 읽기 전","text":"“이 책을 읽어 봐야지!”"},{"who":"남자아이 — 읽은 뒤","text":"“책을 읽었는데 왜 기억나는 내용이 없지?”"},{"who":"여자아이 — 읽기 전","text":"“제목을 보니 이 책에서는 화살나무에 대한 정보를 얻을 수 있겠어.”"},{"who":"여자아이 — 읽는 중","text":"“이 부분은 이해가 안 되네. 다시 천천히 읽어 보자.”"},{"who":"여자아이 — 읽은 뒤","text":"“책을 읽고 난 뒤에 중요한 내용을 따로 정리해 두어야지.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#3','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C12',1,'mc','auto','『국어』 186쪽 4번 (1)의 보기에서 ‘박수’를 늘였을 때 숨어 있는 비밀은 무엇인가요?',ARRAY['K4-2-u4-X15']::text[],false,'{"seq":3,"concept":"K4-2-u4-C12","difficulty":1,"kind":"mc","stem":"『국어』 186쪽 4번 (1)의 보기에서 ‘박수’를 늘였을 때 숨어 있는 비밀은 무엇인가요?","options":[{"t":"악수","correct":true},{"t":"박자","mis":"K4-2-u4-X15"},{"t":"수박","mis":"K4-2-u4-X15"},{"t":"기뻐","mis":"K4-2-u4-X15"}],"explanation":["‘박’을 길게 늘이면 ‘바아아악수’가 돼요.","그러면 뒤에서 ‘악수’가 들려요.","「박수의 비밀」은 이 낱말로 시를 바꾸어 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#4','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C60',1,'mc','auto','진우와 서영이는 승한이와 어디에 가기로 한 날 승한이를 따라 선물 가게에 갔나요?',ARRAY['K4-2-u4-X60']::text[],false,'{"seq":4,"concept":"K4-2-u4-C60","difficulty":1,"kind":"mc","stem":"진우와 서영이는 승한이와 어디에 가기로 한 날 승한이를 따라 선물 가게에 갔나요?","options":[{"t":"승한이 할아버지의 판소리 강습소","correct":true},{"t":"학교 축제 연습실","mis":"K4-2-u4-X60"},{"t":"태권도장","mis":"K4-2-u4-X60"},{"t":"도서관","mis":"K4-2-u4-X60"}],"explanation":["이야기의 첫 문장을 다시 읽어요.","승한이 할아버지의 판소리 강습소에 가기로 한 날이었어요.","가는 길에 승한이가 선물 가게로 들어가는 것을 보았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#5','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C65',1,'mc','auto','「병원에서 감기약 ( 처방 )을 받았다.」에서 ‘처방’의 뜻은 무엇인가요?',ARRAY['K4-2-u4-X70']::text[],false,'{"seq":5,"concept":"K4-2-u4-C65","difficulty":1,"kind":"mc","stem":"「병원에서 감기약 ( 처방 )을 받았다.」에서 ‘처방’의 뜻은 무엇인가요?","options":[{"t":"치료하는 데 필요한 의약품이나 방법 따위를 적은 문서","correct":true},{"t":"열지 못하게 붙여 두었던 것을 떼거나 엶","mis":"K4-2-u4-X70"},{"t":"거두어 감","mis":"K4-2-u4-X70"},{"t":"깊이 생각해 이치를 깨달아 알아냄","mis":"K4-2-u4-X70"}],"explanation":["『국어』 208쪽 낱말 알기 보기 문장이에요.","병원에서 받는 처방은 약이나 치료 방법을 적은 문서예요.","개봉·수거·터득은 다른 낱말의 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#6','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C28',1,'mc','auto','다음 가운데 읽기 중에 할 수 있는 활동은 무엇인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":6,"concept":"K4-2-u4-C28","difficulty":1,"kind":"mc","stem":"다음 가운데 읽기 중에 할 수 있는 활동은 무엇인가요?","options":[{"t":"짐작한 내용이 맞는지 확인하기","correct":true},{"t":"제목이나 차례를 보며 내용 예상하기","mis":"K4-2-u4-X30"},{"t":"더 알고 싶은 내용 생각하기","mis":"K4-2-u4-X30"},{"t":"글 전체의 내용을 요약하여 정리하기","mis":"K4-2-u4-X30"}],"explanation":["읽는 동안에는 짐작한 내용이 맞는지 확인해요.","중심 내용과 새롭게 안 내용도 파악해요.","예상하기는 읽기 전, 요약은 읽기 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#7','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C41',1,'mc','auto','『국어』 212쪽 「경험 떠올리기」에서 세 친구가 읽은 글은 모두 어떤 글인가요?',ARRAY['K4-2-u4-X05','K4-2-u4-X42']::text[],false,'{"seq":7,"concept":"K4-2-u4-C41","difficulty":1,"kind":"mc","stem":"『국어』 212쪽 「경험 떠올리기」에서 세 친구가 읽은 글은 모두 어떤 글인가요?","options":[{"t":"의견을 제시하는 글","correct":true},{"t":"설명하는 글","mis":"K4-2-u4-X05"},{"t":"시","mis":"K4-2-u4-X42"},{"t":"이야기","mis":"K4-2-u4-X42"}],"explanation":["메모해야 하는 까닭, 바르게 걷자, 깨끗이 사용하자는 글이에요.","모두 어떤 문제에 대해 생각이나 주장을 밝혔어요.","그래서 의견을 제시하는 글이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“메모해야 하는 까닭을 알려 주는 글을 읽은 적이 있어.”"},{"who":"친구 2","text":"“복도에서 바르게 걷자는 글을 읽었어.”"},{"who":"친구 3","text":"“학교 화장실을 깨끗이 사용하자는 글을 읽었어.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#8','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C56',1,'mc','auto','나라를 말할 때 ‘저희 나라’ 대신 ‘우리나라’라고 해야 하는 까닭은 무엇인가요?',ARRAY['K4-2-u4-X54']::text[],false,'{"seq":8,"concept":"K4-2-u4-C56","difficulty":1,"kind":"mc","stem":"나라를 말할 때 ‘저희 나라’ 대신 ‘우리나라’라고 해야 하는 까닭은 무엇인가요?","options":[{"t":"나라와 민족은 대등하여 남의 나라와 비교해 낮출 수 없기 때문","correct":true},{"t":"‘우리나라’가 글자 수가 더 많아서","mis":"K4-2-u4-X54"},{"t":"어른 앞에서는 ‘저희 나라’라고 해야 해서","mis":"K4-2-u4-X54"}],"explanation":["‘저희’는 자신을 낮추는 말이에요.","나라와 민족은 대등해서 낮출 수 없어요.","그래서 ‘우리나라’라고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#9','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C5',2,'mc','auto','의견을 제시하는 글을 읽고 떠올릴 질문으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X05']::text[],false,'{"seq":9,"concept":"K4-2-u4-C5","difficulty":2,"kind":"mc","stem":"의견을 제시하는 글을 읽고 떠올릴 질문으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"글쓴이의 의견을 뒷받침하는 이유가 적절한가요?","correct":true},{"t":"가장 기억에 남는 표현이나 장면은 무엇인가요?","mis":"K4-2-u4-X05"},{"t":"이 글은 무엇에 대해 자세하게 알려 주고 있나요?","mis":"K4-2-u4-X05"}],"explanation":["의견을 제시하는 글에는 의견과 이유가 있어요.","이유가 의견을 잘 뒷받침하는지 따져요.","장면을 묻는 질문은 시나 이야기에 어울려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#10','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C11',2,'mc','auto','짝이 「기뻐의 비밀」을 읽고 나와 다른 색깔로 말하는 이의 마음을 나타냈어요. 알맞은 말은 무엇인가요?',ARRAY['K4-2-u4-X12','K4-2-u4-X13']::text[],false,'{"seq":10,"concept":"K4-2-u4-C11","difficulty":2,"kind":"mc","stem":"짝이 「기뻐의 비밀」을 읽고 나와 다른 색깔로 말하는 이의 마음을 나타냈어요. 알맞은 말은 무엇인가요?","options":[{"t":"“왜 그 색깔로 나타냈는지 까닭을 말해 줄래?”","correct":true},{"t":"“그 색깔은 틀렸어.”","mis":"K4-2-u4-X12"},{"t":"“그럼 나도 너처럼 바꿀게.”","mis":"K4-2-u4-X13"}],"explanation":["나와 다른 느낌은 틀린 것이 아니에요.","내 느낌을 바꿀 필요도 없어요.","까닭을 물으면 서로의 생각을 더 잘 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#11','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C19',2,'mc','auto','역할놀이에서 승한이를 맡았어요. 승한이의 성격을 잘 드러내려면 어떻게 말하는 것이 좋을까요?',ARRAY['K4-2-u4-X22','K4-2-u4-X24']::text[],false,'{"seq":11,"concept":"K4-2-u4-C19","difficulty":2,"kind":"mc","stem":"역할놀이에서 승한이를 맡았어요. 승한이의 성격을 잘 드러내려면 어떻게 말하는 것이 좋을까요?","options":[{"t":"다른 사람의 기분을 맞추느라 말을 천천히, 느리게 한다","correct":true},{"t":"자기 생각을 거침없이 빠르게 말한다","mis":"K4-2-u4-X22"},{"t":"친구들을 웃기려고 큰 소리로 말한다","mis":"K4-2-u4-X24"}],"explanation":["승한이는 자기 생각보다 다른 사람의 기분을 맞추는 것이 습관이에요.","그래서 말을 천천히, 느리게 하는 것이 어울려요.","웃기려고 크게 말하면 인물의 성격이 드러나지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#12','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C48',2,'blank','auto','『국어』 215쪽 읽기 후 ㉢에 붙일 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X32']::text[],false,'{"seq":12,"concept":"K4-2-u4-C48","difficulty":2,"kind":"blank","stem":"『국어』 215쪽 읽기 후 ㉢에 붙일 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"주제에 대한 자신의 생각을 떠올렸나요?","correct":true},{"t":"제목이나 차례를 보며 내용을 예상했나요?","mis":"K4-2-u4-X31"},{"t":"글쓴이가 몇 살인지 알아보았나요?","mis":"K4-2-u4-X32"}],"explanation":["의견을 제시하는 글을 다 읽으면 주제에 대한 내 생각을 떠올려요.","그다음 글쓴이와 내 의견을 비교해요.","글쓴이의 나이는 읽기 과정과 상관없어요."],"asset":{"type":"passage","lines":["[읽기 전] 글을 읽기 전에 제목을 보고 어떤 내용일지 예상했나요?","[읽기 전] (     ㉠     )","[읽기 중] 자신이 예상한 내용이 글의 내용과 같은지 확인했나요?","[읽기 중] 글쓴이의 의견이 무엇인지 찾으며 읽었나요?","[읽기 중] (     ㉡     )","[읽기 후] (     ㉢     )","[읽기 후] 글쓴이와 자신의 의견을 비교하여 정리했나요?","‘예’면 다음 질문으로, ‘아니요’면 「이렇게 해 보세요」로 가요."],"title":"『국어』 215쪽 — 질문을 활용해 읽기 과정 되돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#13','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C63',2,'mc','auto','「화살나무를 아시나요?」에서 화살나무 가지에 있는 날개처럼 생긴 것은 몇 줄 보인다고 했나요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":13,"concept":"K4-2-u4-C63","difficulty":2,"kind":"mc","stem":"「화살나무를 아시나요?」에서 화살나무 가지에 있는 날개처럼 생긴 것은 몇 줄 보인다고 했나요?","options":[{"t":"2~4줄","correct":true},{"t":"1줄","mis":"K4-2-u4-X35"},{"t":"10줄","mis":"K4-2-u4-X35"}],"explanation":["둘째 문단에서 가지의 모습을 설명했어요.","코르크 재질의 날개처럼 생긴 것이 2~4줄 보인다고 했어요.","그 모습이 화살의 날개처럼 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#14','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C66',2,'mc','auto','실수로 저작권을 침해했을 때 필요한 태도는 무엇인가요?',ARRAY['K4-2-u4-X72']::text[],false,'{"seq":14,"concept":"K4-2-u4-C66","difficulty":2,"kind":"mc","stem":"실수로 저작권을 침해했을 때 필요한 태도는 무엇인가요?","options":[{"t":"바로 인정하고 수정한다","correct":true},{"t":"모르는 척하고 그대로 쓴다","mis":"K4-2-u4-X72"},{"t":"실수였으니 아무것도 하지 않아도 된다","mis":"K4-2-u4-X72"}],"explanation":["넷째 문단에서 저작권을 지키는 노력을 말했어요.","실수로 침해했다면 바로 인정하고 수정해요.","그것이 정직한 사회를 만드는 길이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#15','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C53',2,'mc','auto','질문 사다리 타기 놀이를 마친 뒤 할 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X51','K4-2-u4-X52']::text[],false,'{"seq":15,"concept":"K4-2-u4-C53","difficulty":2,"kind":"mc","stem":"질문 사다리 타기 놀이를 마친 뒤 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"질문에 답하며 되돌아본 읽기 과정에 대한 소감을 나누고, 잘한 부분을 서로 칭찬한다","correct":true},{"t":"질문 카드를 가장 많이 받은 사람을 뽑는다","mis":"K4-2-u4-X51"},{"t":"가장 빨리 답한 사람을 뽑는다","mis":"K4-2-u4-X52"}],"explanation":["질문 사다리는 많이, 빨리 답하는 놀이가 아니에요.","내 읽기 과정을 되돌아본 소감을 나누어요.","친구들끼리 잘한 부분을 칭찬하고 격려해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#16','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C27',2,'mc','auto','스스로 읽기 「동혁이의 경제 배우기」를 읽기 전에 할 수 있는 활동은 무엇인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":16,"concept":"K4-2-u4-C27","difficulty":2,"kind":"mc","stem":"스스로 읽기 「동혁이의 경제 배우기」를 읽기 전에 할 수 있는 활동은 무엇인가요?","options":[{"t":"책 표지를 보고 어떤 이야기일지 내용 짐작하기","correct":true},{"t":"현명한 소비자가 되는 방법 정리하기","mis":"K4-2-u4-X30"},{"t":"글과 그림에서 새롭게 안 부분 이야기하기","mis":"K4-2-u4-X30"}],"explanation":["읽기 전에는 아직 내용을 몰라요.","책 표지를 보고 내용을 짐작해요.","새롭게 안 부분과 소비자가 되는 방법은 읽은 뒤에 이야기해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#17','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C12',3,'error','auto','세 친구가 글자를 늘였을 때 비밀이 숨어 있는 낱말을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['K4-2-u4-X15','K4-2-u4-X09']::text[],false,'{"seq":17,"concept":"K4-2-u4-C12","difficulty":3,"kind":"error","stem":"세 친구가 글자를 늘였을 때 비밀이 숨어 있는 낱말을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"은수: ‘모기’를 늘이면 ‘암기’가 숨어 있어.","correct":true,"mis_target":"K4-2-u4-X15"},{"t":"지호: ‘감기’를 늘이면 ‘암기’가 숨어 있어.","mis":"K4-2-u4-X09"},{"t":"다은: ‘박수’를 늘이면 ‘악수’가 숨어 있어.","mis":"K4-2-u4-X09"}],"explanation":["‘모기’의 ‘모’를 늘이면 ‘모오오기’가 돼요.","그러면 뒤에서 ‘오기’가 들려요.","‘암기’는 ‘감기’에 숨어 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#18','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C61',3,'mc','auto','진우의 말을 듣고 서영이가 깨달은 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X62','K4-2-u4-X63']::text[],false,'{"seq":18,"concept":"K4-2-u4-C61","difficulty":3,"kind":"mc","stem":"진우의 말을 듣고 서영이가 깨달은 것으로 알맞은 것은 무엇인가요?","options":[{"t":"한 번도 상대의 입장에서 생각하지 않고 자기가 옳다고 믿는 대로 하고 싶은 말을 다 했다는 것","correct":true},{"t":"솔직하게 말했으니 자기는 하나도 잘못이 없다는 것","mis":"K4-2-u4-X62"},{"t":"앞으로는 친구에게 아무 말도 하지 말아야 한다는 것","mis":"K4-2-u4-X63"}],"explanation":["서영이는 소은이, 기윤이, 승한이와 있었던 일을 떠올렸어요.","모두 상대의 입장에서 생각하지 않고 말한 일이었어요.","서영이도 자신을 돌아보았어요."],"asset":{"type":"passage","lines":["(간추림) 서영이는 짝 소은이에게 이상한 냄새가 난다고 말했던 일을 떠올렸다.","(간추림) 놀리거나 괴롭히려는 생각은 없었지만 소은이는 다르게 받아들였다.","(간추림) 소은이가 된 상상을 하자 서영이는 마음이 따갑고 아팠다.","(간추림) 승한이는 친구들이 프라모델을 달라고 할까 봐 집에 부르지 않았다.","(간추림) 서영이도 승한이도 오랫동안 말이 없었다."],"title":"「네 생각을 솔직히 말해」 돌아보는 두 친구 — 『국어』 194~195쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#19','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C30',3,'mc','auto','다음 가운데 읽기 과정을 되돌아보는 질문이 아닌 것은 무엇인가요?',ARRAY['K4-2-u4-X32']::text[],false,'{"seq":19,"concept":"K4-2-u4-C30","difficulty":3,"kind":"mc","stem":"다음 가운데 읽기 과정을 되돌아보는 질문이 아닌 것은 무엇인가요?","options":[{"t":"이 글이 실린 책은 무슨 색인가요?","correct":true},{"t":"새롭게 안 내용을 찾으며 읽었나요?","mis":"K4-2-u4-X32"},{"t":"더 알고 싶은 내용을 생각했나요?","mis":"K4-2-u4-X32"}],"explanation":["읽기 과정을 되돌아보는 질문은 내가 어떻게 읽었는지 묻는 것이에요.","책의 색깔은 읽기와 상관없어요.","새롭게 안 내용, 더 알고 싶은 내용은 읽기 과정 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#20','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C38',3,'mc','auto','「화살나무를 아시나요?」를 요약할 때 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u4-X38','K4-2-u4-X39']::text[],false,'{"seq":20,"concept":"K4-2-u4-C38","difficulty":3,"kind":"mc","stem":"「화살나무를 아시나요?」를 요약할 때 알맞은 방법은 무엇인가요?","options":[{"t":"각 부분의 중심 내용을 모아 짧게 정리한다","correct":true},{"t":"글의 문장을 처음부터 끝까지 모두 옮겨 적는다","mis":"K4-2-u4-X38"},{"t":"가장 재미있었던 부분 하나만 적는다","mis":"K4-2-u4-X39"}],"explanation":["요약은 짧게 정리하는 것이에요.","문단마다 중심 내용을 찾아 이어요.","모두 옮기거나 한 부분만 쓰면 요약이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#21','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C46',3,'mc','auto','「저작권을 왜 지켜야 하나요?」 같은 의견을 제시하는 글을 읽는 태도로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X48','K4-2-u4-X49']::text[],false,'{"seq":21,"concept":"K4-2-u4-C46","difficulty":3,"kind":"mc","stem":"「저작권을 왜 지켜야 하나요?」 같은 의견을 제시하는 글을 읽는 태도로 알맞은 것은 무엇인가요?","options":[{"t":"글쓴이의 의견과 이유를 따져 보고 내 생각과 견주어 본다","correct":true},{"t":"글에 실린 의견이니 그대로 따른다","mis":"K4-2-u4-X48"},{"t":"일단 틀렸다고 보고 무조건 반대한다","mis":"K4-2-u4-X49"}],"explanation":["글쓴이의 의견이 무조건 옳은 것은 아니에요.","그렇다고 무조건 의심할 것도 아니에요.","이유를 따지고 내 생각과 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#22','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C6',3,'mc','auto','읽기 과정을 되돌아보는 질문을 만들 때 가장 중요한 것은 무엇인가요?',ARRAY['K4-2-u4-X06','K4-2-u4-X32']::text[],false,'{"seq":22,"concept":"K4-2-u4-C6","difficulty":3,"kind":"mc","stem":"읽기 과정을 되돌아보는 질문을 만들 때 가장 중요한 것은 무엇인가요?","options":[{"t":"지금 읽는 글과 나에게 필요한 질문인가","correct":true},{"t":"질문의 개수가 많은가","mis":"K4-2-u4-X06"},{"t":"질문 글씨가 예쁜가","mis":"K4-2-u4-X32"}],"explanation":["질문은 내 읽기를 점검하려고 만들어요.","글의 종류와 읽는 목적에 맞는 질문이 좋아요.","개수를 채우는 것이 목적이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#23','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C24',4,'essay','teacher','「네 생각을 솔직히 말해」의 등장인물 가운데 한 명에게 자신의 마음을 담아 편지를 쓰세요. 인물의 말이나 행동에 대한 생각이 드러나게, 받는 인물이 상처받지 않게 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u4-C24","difficulty":4,"kind":"essay","stem":"「네 생각을 솔직히 말해」의 등장인물 가운데 한 명에게 자신의 마음을 담아 편지를 쓰세요. 인물의 말이나 행동에 대한 생각이 드러나게, 받는 인물이 상처받지 않게 쓰세요.","answer_guide":{"answer":"예: 서영이에게 / 서영아, 승한이를 위해서 용기 내어 말한 네 마음은 멋졌어. 그런데 소은이가 얼마나 속상했을지 생각하니 나도 마음이 아팠어. 다음에는 상대의 마음을 먼저 생각하며 말해 보면 어떨까? 늘 응원할게. / ○○가","scoring_points":["편지 받을 인물을 정하고 편지의 짜임을 갖추었는가","인물의 말이나 행동에 대한 자신의 생각이 드러나는가","받는 인물이 상처받지 않게 배려하는 말로 썼는가"]},"explanation":["인상 깊은 인물을 한 명 골라요.","그 인물의 말이나 행동을 떠올리며 내 마음을 써요.","“너는 ~하잖아.”보다 “나는 ~라고 생각해.”로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#24','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C39',4,'essay','teacher','일곱 가지 확인 내용으로 자신의 읽기 과정을 되돌아보고, ‘아니요’가 나온 것을 하나 골라 다음에는 어떻게 읽을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u4-C39","difficulty":4,"kind":"essay","stem":"일곱 가지 확인 내용으로 자신의 읽기 과정을 되돌아보고, ‘아니요’가 나온 것을 하나 골라 다음에는 어떻게 읽을지 쓰세요.","answer_guide":{"answer":"예: ⑥ 「읽은 내용을 요약했나요?」에 ‘아니요’가 나왔다. 다음에는 문단마다 중심 문장에 밑줄을 긋고, 다 읽은 뒤 그 문장들을 이어 두세 문장으로 요약하겠다.","scoring_points":["일곱 가지 확인 내용으로 솔직하게 되돌아보았는가","‘아니요’가 나온 것을 하나 골랐는가","다음에 어떻게 읽을지 구체적인 방법을 썼는가"]},"explanation":["되돌아보기는 점수를 매기는 것이 아니에요.","‘아니요’가 나온 곳이 다음에 노력할 점이에요.","「이렇게 해 보세요」를 떠올려 방법을 정해요."],"asset":{"type":"passage","lines":["① 글을 읽기 전에 제목을 보고 어떤 내용일지 예상했나요?  예 / 아니요","② 글을 읽기 전에 제목을 보고 자신이 알고 있는 내용을 떠올렸나요?  예 / 아니요","③ 자신이 예상한 내용이 글의 내용과 같은지 확인했나요?  예 / 아니요","④ 글의 중심 내용을 찾으며 읽었나요?  예 / 아니요","⑤ 새롭게 안 내용을 찾으며 읽었나요?  예 / 아니요","⑥ 읽은 내용을 요약했나요?  예 / 아니요","⑦ 더 알고 싶은 내용을 생각했나요?  예 / 아니요"],"title":"자신의 읽기 과정을 되돌아봅시다"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_b#25','kor',4,2,'u4','','tb_g4_2_kor_u4_review_b','unit_review','K4-2-u4-C11',4,'essay','teacher','작품에 대한 생각이나 느낌을 친구와 나눌 때 지켜야 할 태도를 두 가지 쓰고, 그렇게 해야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u4-C11","difficulty":4,"kind":"essay","stem":"작품에 대한 생각이나 느낌을 친구와 나눌 때 지켜야 할 태도를 두 가지 쓰고, 그렇게 해야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: ① 나와 다른 느낌을 들으면 틀렸다고 하지 않고 까닭을 묻는다. ② 내 느낌을 말할 때 까닭을 함께 말한다. 사람마다 경험이 달라 느낌도 다를 수 있고, 서로의 생각을 나누면 작품을 더 깊이 이해할 수 있기 때문이다.","scoring_points":["나누는 태도를 두 가지 썼는가","다른 느낌을 존중하는 태도가 드러나는가","그렇게 해야 하는 까닭을 썼는가"]},"explanation":["느낌은 틀린 것이 아니라 다를 수 있어요.","까닭을 묻고, 내 까닭도 말해요.","나누면 작품의 다양한 면을 발견할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#1','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C46',1,'ox','auto','스스로 확인하기의 돌 ㉲ 「의견을 제시하는 글에서 글쓴이의 의견은 무조건 옳다고 믿으면 돼.」는 바른 길이에요.',ARRAY['K4-2-u4-X48']::text[],false,'{"seq":1,"concept":"K4-2-u4-C46","difficulty":1,"kind":"ox","stem":"스스로 확인하기의 돌 ㉲ 「의견을 제시하는 글에서 글쓴이의 의견은 무조건 옳다고 믿으면 돼.」는 바른 길이에요.","answer":"X","reason_options":[{"t":"의견에 대한 이유가 적절한지 살피며 읽어야 해요.","correct":true},{"t":"글에 실린 의견은 따지지 않고 믿으면 돼요.","mis":"K4-2-u4-X48"}],"mis":"K4-2-u4-X48","explanation":["글쓴이의 의견은 글쓴이의 생각이에요.","이유가 적절한지 살피고 내 의견과 견주어요.","이 돌은 바른 길이 아니에요."],"asset":{"type":"passage","lines":["㉮ 글을 읽기 전에 제목을 보고 어떤 내용일지 예상해 봐.","㉯ 글의 내용은 빠짐없이 기억해야 해.","㉰ 예상한 내용과 글의 내용이 같은지 확인해 보면 좋아.","㉱ 예상한 내용과 글의 내용은 꼭 같아야 해.","㉲ 의견을 제시하는 글에서 글쓴이의 의견은 무조건 옳다고 믿으면 돼.","㉳ 시나 이야기를 읽고 떠올린 경험은 모두가 똑같아.","㉴ 설명하는 글에서는 글의 중심 내용을 찾으며 읽으면 좋아."],"title":"『국어』 221쪽 스스로 확인하기 — 바른 길 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#2','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C4',1,'mc','auto','글을 읽으며 스스로 질문을 던지는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X04','K4-2-u4-X06','K4-2-u4-X02']::text[],false,'{"seq":2,"concept":"K4-2-u4-C4","difficulty":1,"kind":"mc","stem":"글을 읽으며 스스로 질문을 던지는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"자신이 글의 내용을 잘 이해하고 있는지 점검하려고","correct":true},{"t":"선생님께 칭찬을 받으려고","mis":"K4-2-u4-X04"},{"t":"질문 개수를 채우려고","mis":"K4-2-u4-X06"},{"t":"글을 빨리 끝내려고","mis":"K4-2-u4-X02"}],"explanation":["읽기 과정의 질문은 스스로 만드는 질문이에요.","내가 잘 이해하고 있는지 점검하게 해 줘요.","그러면 수동적인 독자가 아닌 능동적인 독자가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#3','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C59',1,'ox','auto','「기뻐의 비밀」에서 말하는 이는 길게 늘일수록 언제나 좋다고 했어요.',ARRAY['K4-2-u4-X65']::text[],false,'{"seq":3,"concept":"K4-2-u4-C59","difficulty":1,"kind":"ox","stem":"「기뻐의 비밀」에서 말하는 이는 길게 늘일수록 언제나 좋다고 했어요.","answer":"X","reason_options":[{"t":"말하는 이는 길다고 꼭 좋은 것만은 아니라고 했어요.","correct":true},{"t":"기뻐는 끊어질 때까지 늘일수록 좋다고 했어요.","mis":"K4-2-u4-X65"}],"mis":"K4-2-u4-X65","explanation":["말하는 이는 기뻐를 끊어 먹지 않도록 조심하라고 했어요.","길다고 꼭 좋은 것만은 아니라고 했어요.","끊어지면 따끔해서 찔끔 눈물이 난대요."],"asset":{"type":"passage","lines":["기쁘다고 너무 뻐기다가","기뻐를 끊어 먹지 않도록 조심해","(간추림) 길다고 꼭 좋은 것만은 아니라고 한다.","(간추림) 기뻐가 끊어질 땐 무지 따끔하다고 한다.","어쩔 땐 찔끔 눈물이이 나아"],"title":"「기뻐의 비밀」(이안 글) 뒷부분 — 『국어』 184쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#4','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C61',1,'mc','auto','진우가 들려준 이야기에서 한 스님이 막대기를 휘둘러 사슴을 쫓아낸 까닭은 무엇인가요?',ARRAY['K4-2-u4-X60']::text[],false,'{"seq":4,"concept":"K4-2-u4-C61","difficulty":1,"kind":"mc","stem":"진우가 들려준 이야기에서 한 스님이 막대기를 휘둘러 사슴을 쫓아낸 까닭은 무엇인가요?","options":[{"t":"사냥꾼도 있으니 사슴에게 사람을 조심해야 하는 걸 가르쳐 주려고","correct":true},{"t":"채소가 아까워서","mis":"K4-2-u4-X60"},{"t":"사슴이 무서워서","mis":"K4-2-u4-X60"},{"t":"다른 스님들을 화나게 하려고","mis":"K4-2-u4-X60"}],"explanation":["다른 스님들은 채소가 아까워서 그런 줄 알았어요.","하지만 그 스님은 세상에 사냥꾼도 있다고 했어요.","진짜 사슴을 위한다면 사람을 조심하도록 가르쳐야 한다고 했어요."],"asset":{"type":"passage","lines":["(간추림) 스님들은 채소를 먹는 어린 사슴이 귀엽고 안돼서 쫓아내지 않았다.","(간추림) 어느 날 한 스님이 막대기를 휘두르며 사슴을 쫓아냈다.","(간추림) 세상에는 사냥꾼도 있으니 사람을 조심해야 하는 걸 가르쳐야 한다고 했다.","“서영이는 그런 너를 위해 스님처럼 막대기를 휘둘러 준 거야.”"],"title":"「네 생각을 솔직히 말해」 스님과 사슴 이야기 — 『국어』 191~192쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#5','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C67',1,'mc','auto','『국어』 214쪽 낱말 ‘창작’의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X70','K4-2-u4-X72']::text[],false,'{"seq":5,"concept":"K4-2-u4-C67","difficulty":1,"kind":"mc","stem":"『국어』 214쪽 낱말 ‘창작’의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"예술 작품을 독창적으로 지어냄","correct":true},{"t":"침범해 해를 끼침","mis":"K4-2-u4-X70"},{"t":"더 낫고 좋은 상태나 더 높은 단계로 나아감","mis":"K4-2-u4-X70"},{"t":"남의 작품을 그대로 베껴 씀","mis":"K4-2-u4-X72"}],"explanation":["창작은 새로 지어내는 것이에요.","창작자는 오랜 시간 공들여 창작물을 만들어요.","침해는 침범해 해를 끼치는 것, 발전은 나아가는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#6','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C29',1,'mc','auto','다음 가운데 읽기 후에 할 수 있는 활동은 무엇인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":6,"concept":"K4-2-u4-C29","difficulty":1,"kind":"mc","stem":"다음 가운데 읽기 후에 할 수 있는 활동은 무엇인가요?","options":[{"t":"더 알고 싶은 내용 생각하기","correct":true},{"t":"자신이 알고 있는 내용 떠올리기","mis":"K4-2-u4-X30"},{"t":"각 부분의 중심 내용 파악하기","mis":"K4-2-u4-X30"},{"t":"제목이나 차례를 보며 내용 예상하기","mis":"K4-2-u4-X30"}],"explanation":["다 읽은 뒤에는 더 알고 싶은 내용을 생각해요.","글 전체의 내용을 요약하여 정리하기도 해요.","중심 내용 파악은 읽기 중에 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#7','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C41',1,'mc','auto','수업 시간에 읽은 글 말고도 의견을 제시하는 글을 읽은 경험으로 떠올릴 수 있는 것은 무엇인가요?',ARRAY['K4-2-u4-X42']::text[],false,'{"seq":7,"concept":"K4-2-u4-C41","difficulty":1,"kind":"mc","stem":"수업 시간에 읽은 글 말고도 의견을 제시하는 글을 읽은 경험으로 떠올릴 수 있는 것은 무엇인가요?","options":[{"t":"안내장이나 현수막, 광고를 읽은 경험","correct":true},{"t":"동시를 외운 경험","mis":"K4-2-u4-X42"},{"t":"일기를 쓴 경험","mis":"K4-2-u4-X42"}],"explanation":["의견을 제시하는 글은 생활 곳곳에 있어요.","안내장, 현수막, 광고에도 무엇을 하자는 생각이 담겨 있어요.","동시나 일기는 의견을 제시하는 글이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#8','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C57',1,'blank','auto','“친구에게 응원하는 (     )을 보내야지.” — ‘이모티콘’ 대신 쓸 우리말은 무엇인가요?',ARRAY['K4-2-u4-X55']::text[],false,'{"seq":8,"concept":"K4-2-u4-C57","difficulty":1,"kind":"blank","stem":"“친구에게 응원하는 (     )을 보내야지.” — ‘이모티콘’ 대신 쓸 우리말은 무엇인가요?","options":[{"t":"그림말","correct":true},{"t":"스스로","mis":"K4-2-u4-X55"},{"t":"이모지","mis":"K4-2-u4-X55"}],"explanation":["『국어』 222쪽 기초 다지기 2예요.","‘이모티콘’은 ‘그림말’로 바꿀 수 있어요.","‘스스로’는 ‘셀프’를 바꾼 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#9','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C32',2,'mc','auto','『국어활동』 57쪽 「더 알아보기」에서 설명하는 글을 읽을 때 할 수 있는 질문으로 든 것은 무엇인가요?',ARRAY['K4-2-u4-X05']::text[],false,'{"seq":9,"concept":"K4-2-u4-C32","difficulty":2,"kind":"mc","stem":"『국어활동』 57쪽 「더 알아보기」에서 설명하는 글을 읽을 때 할 수 있는 질문으로 든 것은 무엇인가요?","options":[{"t":"새롭게 안 사실은 무엇인가요?","correct":true},{"t":"글을 읽으며 생각이 바뀌거나 발전한 부분이 있었나요?","mis":"K4-2-u4-X05"},{"t":"인물은 그 상황에서 어떤 마음이었나요?","mis":"K4-2-u4-X05"}],"explanation":["설명하는 글은 지식이나 정보를 알려 줘요.","그래서 새롭게 안 사실을 물어요.","생각이 바뀐 부분은 의견을 제시하는 글에 어울리는 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#10','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C13',2,'mc','auto','친구들과 작품에 대한 생각이나 느낌을 나누면 좋은 점은 무엇인가요?',ARRAY['K4-2-u4-X16','K4-2-u4-X10']::text[],false,'{"seq":10,"concept":"K4-2-u4-C13","difficulty":2,"kind":"mc","stem":"친구들과 작품에 대한 생각이나 느낌을 나누면 좋은 점은 무엇인가요?","options":[{"t":"서로의 생각이나 느낌이 다름을 알고 작품의 다양한 면을 발견할 수 있다","correct":true},{"t":"나눈 뒤에는 모두 같은 느낌이 된다","mis":"K4-2-u4-X16"},{"t":"가장 많이 나온 느낌을 정답으로 정할 수 있다","mis":"K4-2-u4-X10"}],"explanation":["사람마다 경험이 달라 느끼는 부분도 달라요.","다른 생각을 들으면 내가 못 본 면을 볼 수 있어요.","나눈 뒤에 모두 같아질 필요는 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#11','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C21',2,'mc','auto','역할놀이를 할 때 다른 모둠이 발표하는 동안 해야 할 일은 무엇인가요?',ARRAY['K4-2-u4-X26']::text[],false,'{"seq":11,"concept":"K4-2-u4-C21","difficulty":2,"kind":"mc","stem":"역할놀이를 할 때 다른 모둠이 발표하는 동안 해야 할 일은 무엇인가요?","options":[{"t":"경청하는 분위기에서 집중해서 본다","correct":true},{"t":"우리 모둠 대사를 큰 소리로 연습한다","mis":"K4-2-u4-X26"},{"t":"재미없으면 중간에 끼어든다","mis":"K4-2-u4-X26"}],"explanation":["다른 모둠의 발표도 귀 기울여 보아요.","그래야 서로의 생각이나 느낌을 나눌 수 있어요.","발표 중에 끼어들지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#12','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C48',2,'blank','auto','『국어』 215쪽 읽기 전 ㉠에 붙일 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X31']::text[],false,'{"seq":12,"concept":"K4-2-u4-C48","difficulty":2,"kind":"blank","stem":"『국어』 215쪽 읽기 전 ㉠에 붙일 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"글을 읽기 전에 제목을 보고 자신이 알고 있는 내용을 떠올렸나요?","correct":true},{"t":"글쓴이와 자신의 의견을 비교하여 정리했나요?","mis":"K4-2-u4-X31"},{"t":"의견에 대한 이유가 적절한지 살피며 읽었나요?","mis":"K4-2-u4-X31"}],"explanation":["읽기 전에는 제목을 보고 예상하고, 알고 있는 내용을 떠올려요.","저작권에 대해 알고 있는 것을 떠올리는 거예요.","의견 비교는 읽기 후, 이유 살피기는 읽기 중이에요."],"asset":{"type":"passage","lines":["[읽기 전] 글을 읽기 전에 제목을 보고 어떤 내용일지 예상했나요?","[읽기 전] (     ㉠     )","[읽기 중] 자신이 예상한 내용이 글의 내용과 같은지 확인했나요?","[읽기 중] 글쓴이의 의견이 무엇인지 찾으며 읽었나요?","[읽기 중] (     ㉡     )","[읽기 후] (     ㉢     )","[읽기 후] 글쓴이와 자신의 의견을 비교하여 정리했나요?","‘예’면 다음 질문으로, ‘아니요’면 「이렇게 해 보세요」로 가요."],"title":"『국어』 215쪽 — 질문을 활용해 읽기 과정 되돌아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#13','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C64',2,'mc','auto','「약, 잘 쓰고 잘 버리는 방법」에서 약은 반드시 무엇과 함께 보관해야 한다고 했나요?',ARRAY['K4-2-u4-X35','K4-2-u4-X71']::text[],false,'{"seq":13,"concept":"K4-2-u4-C64","difficulty":2,"kind":"mc","stem":"「약, 잘 쓰고 잘 버리는 방법」에서 약은 반드시 무엇과 함께 보관해야 한다고 했나요?","options":[{"t":"상자와 사용 설명서","correct":true},{"t":"처방전과 영수증","mis":"K4-2-u4-X35"},{"t":"다른 약들과 한 봉지에 섞어서","mis":"K4-2-u4-X71"}],"explanation":["설명서가 없으면 어느 약을 어디에 써야 할지 몰라요.","상자가 없으면 소비 기한을 알 수 없어요.","그래서 상자와 설명서를 함께 보관해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#14','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C66',2,'mc','auto','저작권을 잘 지키지 않으면 문화와 관련된 산업에 어떤 일이 생긴다고 했나요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":14,"concept":"K4-2-u4-C66","difficulty":2,"kind":"mc","stem":"저작권을 잘 지키지 않으면 문화와 관련된 산업에 어떤 일이 생긴다고 했나요?","options":[{"t":"산업이 발전하지 않아 일자리도 사라지고 경제적인 성장도 기대할 수 없게 된다","correct":true},{"t":"일자리가 더 많이 생긴다","mis":"K4-2-u4-X35"},{"t":"문화 상품을 더 많이 수출하게 된다","mis":"K4-2-u4-X35"}],"explanation":["좋은 작품이 만들어지지 않으면 문화 산업도 발전하지 않아요.","일자리가 사라지고 문화 상품도 수출하지 못해요.","결국 경제적인 성장도 기대할 수 없게 돼요."],"asset":{"type":"passage","lines":["(간추림) 저작권을 잘 지키지 않으면 창작자는 더 좋은 작품을 만들려고 노력하지 않게 된다.","(간추림) 그러면 사람들이 누릴 수 있는 문화의 수준도 낮아질 가능성이 크다.","(간추림) 음악이나 영화, 책도 없어지고 문화 산업도 발전하지 않을 것이다.","(간추림) 일자리가 사라지고 우리나라의 경제적인 성장도 기대할 수 없게 된다."],"title":"「저작권을 왜 지켜야 하나요?」 셋째 문단 — 『국어』 213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#15','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C52',2,'mc','auto','이야기 말판 놀이에서 각자 붙임쪽지에 쓰는 질문은 몇 개 이상이라고 했나요?',ARRAY['K4-2-u4-X06']::text[],false,'{"seq":15,"concept":"K4-2-u4-C52","difficulty":2,"kind":"mc","stem":"이야기 말판 놀이에서 각자 붙임쪽지에 쓰는 질문은 몇 개 이상이라고 했나요?","options":[{"t":"세 개 이상","correct":true},{"t":"한 개만","mis":"K4-2-u4-X06"},{"t":"열 개 이상","mis":"K4-2-u4-X06"}],"explanation":["서너 명이 함께 이야기 한 편을 읽어요.","생각이나 느낌을 말할 수 있는 질문을 각자 세 개 이상 써요.","개수보다 생각이나 느낌을 나눌 수 있는 질문인지가 중요해요."],"asset":{"type":"passage","lines":["① 서너 명의 친구가 함께 활동한다.","② 이야기 한 편을 정해 읽고, 질문을 붙임쪽지에 각자 세 개 이상 쓴다.","③ 함께 만든 질문을 4절 도화지에 말판 모양으로 붙인다.","④ 이야기와 관련한 질문에 답하며 생각이나 느낌을 나눈다."],"title":"우리 반에서 정한 활동 예시 1 — 이야기 말판 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#16','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C40',2,'mc','auto','「동혁이의 경제 배우기」를 읽고 새롭게 안 부분을 이야기하려고 해요. 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X58']::text[],false,'{"seq":16,"concept":"K4-2-u4-C40","difficulty":2,"kind":"mc","stem":"「동혁이의 경제 배우기」를 읽고 새롭게 안 부분을 이야기하려고 해요. 알맞은 것은 무엇인가요?","options":[{"t":"똑같은 물건이라도 가격이 변하는 까닭이 있다는 것을 알았다","correct":true},{"t":"동혁이의 꿈이 무엇인지 궁금하다","mis":"K4-2-u4-X58"},{"t":"시장에 가면 재미있을 것 같다","mis":"K4-2-u4-X58"}],"explanation":["새롭게 안 부분은 글을 읽고 알게 된 것이에요.","이코는 가격이 변하는 까닭을 알려 주었어요.","궁금한 것이나 짐작은 새롭게 안 것과 달라요."],"asset":{"type":"passage","lines":["(간추림) 동혁이는 아버지께 꿈과 관련 있는 물건을 사 오라는 말씀을 듣는다.","(간추림) 시장으로 가는 길에 경제 요정 이코를 만난다.","(간추림) 꿈인 ‘작가’와 관련 있는 연필을 사려고 가격을 비교하며 고민한다.","(간추림) 이코는 경쟁과 비용, 가격이 변하는 까닭, 돈을 쓰고 관리하는 법을 알려 준다.","(간추림) 동혁이는 현명한 소비자가 되기를 다짐하며 집으로 돌아간다."],"title":"「동혁이의 경제 배우기」(박원배 글) — 『국어활동』 58~69쪽 스스로 읽기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#17','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C12',3,'mc','auto','「박수의 비밀」은 「기뻐의 비밀」을 어떻게 바꾸어 쓴 시인가요?',ARRAY['K4-2-u4-X11','K4-2-u4-X15']::text[],false,'{"seq":17,"concept":"K4-2-u4-C12","difficulty":3,"kind":"mc","stem":"「박수의 비밀」은 「기뻐의 비밀」을 어떻게 바꾸어 쓴 시인가요?","options":[{"t":"‘기뻐’ 대신 비밀이 숨은 낱말 ‘박수’를 넣고, 숨은 낱말 ‘악수’로 새로운 뜻을 붙였다","correct":true},{"t":"「기뻐의 비밀」을 한 글자도 바꾸지 않고 옮겨 썼다","mis":"K4-2-u4-X11"},{"t":"숨은 낱말 없이 제목만 바꾸었다","mis":"K4-2-u4-X15"}],"explanation":["「박수의 비밀」은 「기뻐의 비밀」의 짜임을 살렸어요.","‘박수’ 안에 ‘악수’가 들어 있다고 했어요.","친구에게 박수를 보내면 악수를 나눌 친구가 생긴다는 새 뜻을 붙였어요."],"asset":{"type":"passage","lines":["내가 박수의 비밀을 말해 줄까?","박수 안에는","악수가 들어 있다","(간추림) 왼손으로 ‘박’, 오른손으로 ‘수’를 잡고 고무줄처럼 늘인다.","친구의 기쁨에","진심으로 박수를 보내다 보면","너와 악수를 나눌 좋은 친구가","많이 생기게 될 거야"],"title":"시 바꾸어 쓰기 예 「박수의 비밀」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#18','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C18',3,'ox','auto','서영이는 소은이를 놀리거나 괴롭히려고 이상한 냄새가 난다고 말했어요.',ARRAY['K4-2-u4-X61']::text[],false,'{"seq":18,"concept":"K4-2-u4-C18","difficulty":3,"kind":"ox","stem":"서영이는 소은이를 놀리거나 괴롭히려고 이상한 냄새가 난다고 말했어요.","answer":"X","reason_options":[{"t":"서영이는 놀리거나 괴롭히려는 생각이 없었지만 소은이의 마음을 헤아리지 못했어요.","correct":true},{"t":"서영이는 일부러 친구에게 상처를 주는 나쁜 아이예요.","mis":"K4-2-u4-X61"}],"mis":"K4-2-u4-X61","explanation":["서영이는 친한 친구가 깨끗이 씻고 다니길 바랐을 뿐이었어요.","하지만 아이들 앞에서 한 말이 소은이에게 상처가 되었어요.","인물의 마음과 행동을 함께 살펴요."],"asset":{"type":"passage","lines":["(간추림) 서영이는 짝 소은이에게 이상한 냄새가 난다고 말했던 일을 떠올렸다.","(간추림) 놀리거나 괴롭히려는 생각은 없었지만 소은이는 다르게 받아들였다.","(간추림) 소은이가 된 상상을 하자 서영이는 마음이 따갑고 아팠다.","(간추림) 승한이는 친구들이 프라모델을 달라고 할까 봐 집에 부르지 않았다.","(간추림) 서영이도 승한이도 오랫동안 말이 없었다."],"title":"「네 생각을 솔직히 말해」 돌아보는 두 친구 — 『국어』 194~195쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#19','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C28',3,'mc','auto','「화살나무를 아시나요?」를 읽기 전에 ‘화살을 만드는 나무’라고 예상했는데, 글을 읽어 보니 달랐어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u4-X69']::text[],false,'{"seq":19,"concept":"K4-2-u4-C28","difficulty":3,"kind":"mc","stem":"「화살나무를 아시나요?」를 읽기 전에 ‘화살을 만드는 나무’라고 예상했는데, 글을 읽어 보니 달랐어요. 알맞은 생각은 무엇인가요?","options":[{"t":"예상이 맞는지 확인한 것이니, 글에서 이름이 붙은 까닭을 찾아 바로잡는다","correct":true},{"t":"예상이 틀렸으니 처음부터 잘못 읽은 것이다","mis":"K4-2-u4-X69"},{"t":"예상과 다르면 그 글은 더 읽지 않는다","mis":"K4-2-u4-X69"}],"explanation":["읽기 중에는 예상한 내용이 맞는지 확인해요.","예상과 다르면 글에서 맞는 내용을 찾아 바로잡아요.","예상이 틀린 것은 잘못 읽은 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#20','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C38',3,'mc','auto','「저작권을 왜 지켜야 하나요?」를 요약한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X39','K4-2-u4-X37']::text[],false,'{"seq":20,"concept":"K4-2-u4-C38","difficulty":3,"kind":"mc","stem":"「저작권을 왜 지켜야 하나요?」를 요약한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"저작권은 창작물을 만든 사람의 권리이다. 지키지 않으면 문화 수준과 문화 산업이 낮아지므로 허락을 받고 이용하는 등 저작권을 지키기 위해 노력해야 한다.","correct":true},{"t":"음악이나 재미있는 영화, 책이 좋다.","mis":"K4-2-u4-X39"},{"t":"친구가 허락 없이 내 작품을 써서 칭찬받은 일을 상상해 보는 글이다.","mis":"K4-2-u4-X37"}],"explanation":["저작권의 뜻, 지켜야 하는 까닭, 지키는 방법이 들어가야 해요.","한 부분만 쓰면 전체 내용을 알 수 없어요.","글쓴이의 의견도 빠뜨리지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#21','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C45',3,'mc','auto','「학교에 반려동물을 데려올 수 있어야 한다.」라는 의견에 든 이유 가운데 의견과 이어지는 것은 무엇인가요?',ARRAY['K4-2-u4-X46']::text[],false,'{"seq":21,"concept":"K4-2-u4-C45","difficulty":3,"kind":"mc","stem":"「학교에 반려동물을 데려올 수 있어야 한다.」라는 의견에 든 이유 가운데 의견과 이어지는 것은 무엇인가요?","options":[{"t":"반려동물을 돌보며 생명을 소중히 여기는 마음을 배울 수 있기 때문","correct":true},{"t":"나는 글씨를 예쁘게 쓰고 싶기 때문","mis":"K4-2-u4-X46"},{"t":"어제 비가 왔기 때문","mis":"K4-2-u4-X46"}],"explanation":["이유는 그 의견대로 하면 좋은 점이어야 해요.","글씨나 날씨는 반려동물을 데려오는 것과 이어지지 않아요.","내가 찬성하는지와 상관없이 이어지는지를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#22','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C33',3,'mc','auto','짧은 안내문을 읽을 때와 두꺼운 설명 책을 읽을 때 활용하는 질문이 다를 수 있는 까닭은 무엇인가요?',ARRAY['K4-2-u4-X07','K4-2-u4-X06']::text[],false,'{"seq":22,"concept":"K4-2-u4-C33","difficulty":3,"kind":"mc","stem":"짧은 안내문을 읽을 때와 두꺼운 설명 책을 읽을 때 활용하는 질문이 다를 수 있는 까닭은 무엇인가요?","options":[{"t":"글의 특성과 읽는 목적, 읽기 상황에 따라 필요한 활동이 달라지기 때문","correct":true},{"t":"짧은 글에는 질문을 할 필요가 전혀 없기 때문","mis":"K4-2-u4-X07"},{"t":"두꺼운 책일수록 질문 개수를 늘려야 하기 때문","mis":"K4-2-u4-X06"}],"explanation":["글의 길이와 종류가 다르면 필요한 활동도 달라요.","왜 읽는지에 따라서도 달라져요.","그때그때 알맞은 질문을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#23','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C10',4,'essay','teacher','「기뻐의 비밀」에서 마음에 드는 표현을 골라 집중해 읽고, 떠오른 장면이나 경험과 함께 생각이나 느낌을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u4-C10","difficulty":4,"kind":"essay","stem":"「기뻐의 비밀」에서 마음에 드는 표현을 골라 집중해 읽고, 떠오른 장면이나 경험과 함께 생각이나 느낌을 쓰세요.","answer_guide":{"answer":"예: “기쁘다고 너무 뻐기다가 / 기뻐를 끊어 먹지 않도록 조심해”가 마음에 든다. 받아쓰기 백 점을 받고 친구들에게 너무 자랑하다가 친구가 속상해했던 일이 떠올랐다. 기쁠 때에도 친구 마음을 생각해야겠다는 생각이 들었다.","scoring_points":["마음에 드는 표현을 골랐는가","떠오른 장면이나 경험을 썼는가","생각이나 느낌을 까닭과 함께 썼는가"]},"explanation":["『국어활동』 55쪽처럼 마음에 드는 표현을 골라 집중해요.","그 표현을 읽고 떠오른 장면이나 경험을 떠올려요.","내 생각이나 느낌은 정답이 없어요."],"asset":{"type":"passage","lines":["기쁘다고 너무 뻐기다가","기뻐를 끊어 먹지 않도록 조심해","(간추림) 길다고 꼭 좋은 것만은 아니라고 한다.","(간추림) 기뻐가 끊어질 땐 무지 따끔하다고 한다.","어쩔 땐 찔끔 눈물이이 나아"],"title":"「기뻐의 비밀」(이안 글) 뒷부분 — 『국어』 184쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#24','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C49',4,'essay','teacher','『국어활동』 57쪽 3번처럼 자신의 읽기 과정을 되돌아보고, 앞으로 글을 읽을 때 어떻게 할지 다짐을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u4-C49","difficulty":4,"kind":"essay","stem":"『국어활동』 57쪽 3번처럼 자신의 읽기 과정을 되돌아보고, 앞으로 글을 읽을 때 어떻게 할지 다짐을 쓰세요.","answer_guide":{"answer":"예: 글을 읽기 전에 제목을 보고 내용을 예상해 보니 글이 더 잘 이해되었다. 읽는 동안 예상한 내용과 비교하며 중요한 정보를 찾을 수 있었다. 앞으로는 읽은 뒤에 중심 내용을 찾아 정리하는 습관을 들이겠다.","scoring_points":["자신의 읽기 과정을 되돌아본 내용이 있는가","잘한 점이나 부족한 점을 솔직하게 썼는가","앞으로의 다짐을 구체적으로 썼는가"]},"explanation":["2번 질문에 답한 결과를 바탕으로 써요.","잘된 점은 이어 가고 부족한 점은 고칠 방법을 정해요.","다짐은 실천할 수 있게 구체적으로 써요."],"asset":{"type":"passage","lines":["내가 읽은 글 — 「시장이란 무엇인가요?」","글의 내용 — 시장의 뜻과 종류, 특징을 설명하고 있습니다.","‘예’가 6~7개 — 당신은 읽기 전문가!","‘예’가 3~5개 — 글을 읽을 때 질문하며 생각하는 습관을 조금 더 길러 보세요.","‘예’가 0~2개 — 『국어』에서 공부한 내용을 떠올려 보세요."],"title":"『국어활동』 56~57쪽 실력 키우기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_c#25','kor',4,2,'u4','','tb_g4_2_kor_u4_review_c','unit_review','K4-2-u4-C40',4,'essay','teacher','스스로 읽기 「동혁이의 경제 배우기」를 읽고 새롭게 안 점을 쓰고, 자신의 삶 속에서 현명한 소비자가 되는 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u4-C40","difficulty":4,"kind":"essay","stem":"스스로 읽기 「동혁이의 경제 배우기」를 읽고 새롭게 안 점을 쓰고, 자신의 삶 속에서 현명한 소비자가 되는 방법을 쓰세요.","answer_guide":{"answer":"예: 똑같은 물건이라도 가격이 달라질 수 있다는 것을 새롭게 알았다. 나도 학용품을 살 때 바로 사지 않고 여러 가게의 가격을 비교해 보고, 꼭 필요한 물건인지 생각한 뒤에 사겠다.","scoring_points":["글을 읽고 새롭게 안 점을 썼는가","현명한 소비자가 되는 방법을 썼는가","자신의 생활과 이어 구체적으로 썼는가"]},"explanation":["동혁이는 이코에게 경제 이야기를 들었어요.","새롭게 안 것을 먼저 정리해요.","내 생활에서 실천할 방법으로 이어요."],"asset":{"type":"passage","lines":["(간추림) 동혁이는 아버지께 꿈과 관련 있는 물건을 사 오라는 말씀을 듣는다.","(간추림) 시장으로 가는 길에 경제 요정 이코를 만난다.","(간추림) 꿈인 ‘작가’와 관련 있는 연필을 사려고 가격을 비교하며 고민한다.","(간추림) 이코는 경쟁과 비용, 가격이 변하는 까닭, 돈을 쓰고 관리하는 법을 알려 준다.","(간추림) 동혁이는 현명한 소비자가 되기를 다짐하며 집으로 돌아간다."],"title":"「동혁이의 경제 배우기」(박원배 글) — 『국어활동』 58~69쪽 스스로 읽기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#1','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C9',1,'ox','auto','스스로 확인하기의 돌 ㉳ 「시나 이야기를 읽고 떠올린 경험은 모두가 똑같아.」는 바른 길이에요.',ARRAY['K4-2-u4-X08']::text[],false,'{"seq":1,"concept":"K4-2-u4-C9","difficulty":1,"kind":"ox","stem":"스스로 확인하기의 돌 ㉳ 「시나 이야기를 읽고 떠올린 경험은 모두가 똑같아.」는 바른 길이에요.","answer":"X","reason_options":[{"t":"사람마다 겪은 일이 달라서 떠올린 경험도 다를 수 있어요.","correct":true},{"t":"같은 시를 읽으면 누구나 똑같은 경험을 떠올려요.","mis":"K4-2-u4-X08"}],"mis":"K4-2-u4-X08","explanation":["같은 작품을 읽어도 떠오르는 경험은 저마다 달라요.","그래서 생각이나 느낌을 나누면 작품의 여러 면을 볼 수 있어요.","이 돌은 바른 길이 아니에요."],"asset":{"type":"passage","lines":["㉮ 글을 읽기 전에 제목을 보고 어떤 내용일지 예상해 봐.","㉯ 글의 내용은 빠짐없이 기억해야 해.","㉰ 예상한 내용과 글의 내용이 같은지 확인해 보면 좋아.","㉱ 예상한 내용과 글의 내용은 꼭 같아야 해.","㉲ 의견을 제시하는 글에서 글쓴이의 의견은 무조건 옳다고 믿으면 돼.","㉳ 시나 이야기를 읽고 떠올린 경험은 모두가 똑같아.","㉴ 설명하는 글에서는 글의 중심 내용을 찾으며 읽으면 좋아."],"title":"『국어』 221쪽 스스로 확인하기 — 바른 길 찾기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#2','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C1',1,'mc','auto','『국어』 221쪽 「생활 속으로」에서 소단원 1(작품을 읽고 생각이나 느낌 나누기)에서 배운 것을 실천하겠다고 한 친구는 누구인가요?',ARRAY['K4-2-u4-X01']::text[],false,'{"seq":2,"concept":"K4-2-u4-C1","difficulty":1,"kind":"mc","stem":"『국어』 221쪽 「생활 속으로」에서 소단원 1(작품을 읽고 생각이나 느낌 나누기)에서 배운 것을 실천하겠다고 한 친구는 누구인가요?","options":[{"t":"친구 1","correct":true},{"t":"친구 2","mis":"K4-2-u4-X01"},{"t":"친구 3","mis":"K4-2-u4-X01"}],"explanation":["친구 1은 작품을 읽고 생각이나 느낌을 다양하게 표현하겠다고 했어요.","친구 2와 친구 3은 질문을 활용하겠다고 했어요.","질문 활용은 소단원 2에서 배웠어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"“작품을 읽고 생각이나 느낌을 다양하게 표현할 거야.”"},{"who":"친구 2","text":"“책을 읽고 나서 내용을 잘 기억할 수 있게 여러 가지 질문을 활용해 볼래.”"},{"who":"친구 3","text":"“글을 읽고 나서 질문을 활용해 나의 읽기 과정을 되돌아볼 거야.”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#3','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C59',1,'mc','auto','「기뻐의 비밀」에서 말하는 이는 ‘기뻐’를 늘이는 모습을 무엇에 빗대었나요?',ARRAY['K4-2-u4-X65']::text[],false,'{"seq":3,"concept":"K4-2-u4-C59","difficulty":1,"kind":"mc","stem":"「기뻐의 비밀」에서 말하는 이는 ‘기뻐’를 늘이는 모습을 무엇에 빗대었나요?","options":[{"t":"고무줄","correct":true},{"t":"풍선","mis":"K4-2-u4-X65"},{"t":"밀가루 반죽","mis":"K4-2-u4-X65"},{"t":"엿가락","mis":"K4-2-u4-X65"}],"explanation":["왼손으로 ‘기’, 오른손으로 ‘뻐’를 잡고 늘여요.","그 모습을 고무줄처럼 늘인다고 했어요.","짝 대화에서도 고무줄로 빗댄 표현이 재미있다고 했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#4','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C61',1,'mc','auto','진우의 이야기를 듣고 승한이가 깨달은 것은 무엇인가요?',ARRAY['K4-2-u4-X29','K4-2-u4-X60','K4-2-u4-X63']::text[],false,'{"seq":4,"concept":"K4-2-u4-C61","difficulty":1,"kind":"mc","stem":"진우의 이야기를 듣고 승한이가 깨달은 것은 무엇인가요?","options":[{"t":"친구들이 프라모델을 달라고 할까 봐 집에 부르지 않으면서 자기 마음을 속여 왔다는 것","correct":true},{"t":"서영이가 모두 잘못했다는 것","mis":"K4-2-u4-X29"},{"t":"버지5 가방이 다 떨어졌다는 것","mis":"K4-2-u4-X60"},{"t":"양보만 하면 언제나 친구가 많아진다는 것","mis":"K4-2-u4-X63"}],"explanation":["엄마는 승한이에게 왜 친구들을 집에 데려오지 않느냐고 물었어요.","승한이는 이제 그 질문에 솔직하게 대답해야겠다고 생각했어요.","자기 마음을 속이고 있었다는 것을 깨달았어요."],"asset":{"type":"passage","lines":["(간추림) 서영이는 짝 소은이에게 이상한 냄새가 난다고 말했던 일을 떠올렸다.","(간추림) 놀리거나 괴롭히려는 생각은 없었지만 소은이는 다르게 받아들였다.","(간추림) 소은이가 된 상상을 하자 서영이는 마음이 따갑고 아팠다.","(간추림) 승한이는 친구들이 프라모델을 달라고 할까 봐 집에 부르지 않았다.","(간추림) 서영이도 승한이도 오랫동안 말이 없었다."],"title":"「네 생각을 솔직히 말해」 돌아보는 두 친구 — 『국어』 194~195쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#5','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C63',1,'mc','auto','「화살나무의 새순도 먹을 수 있답니다.」에서 ‘새순’의 뜻은 무엇인가요?',ARRAY['K4-2-u4-X70','K4-2-u4-X35']::text[],false,'{"seq":5,"concept":"K4-2-u4-C63","difficulty":1,"kind":"mc","stem":"「화살나무의 새순도 먹을 수 있답니다.」에서 ‘새순’의 뜻은 무엇인가요?","options":[{"t":"새로 돋아나는 순. 새싹","correct":true},{"t":"주로 헐거나 곪은 데 붙이는 끈끈한 약","mis":"K4-2-u4-X70"},{"t":"가을에 붉게 물든 잎","mis":"K4-2-u4-X35"},{"t":"잎이 진 뒤 보이는 빨간 열매","mis":"K4-2-u4-X35"}],"explanation":["『국어』 201쪽 낱말 풀이를 보아요.","새순은 새로 돋아나는 순, 새싹이에요.","화살나무의 새순은 무쳐 먹거나 국에 넣어 먹어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#6','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C28',1,'ox','auto','예상한 내용과 글의 내용이 다르면 글을 잘못 읽은 것이에요.',ARRAY['K4-2-u4-X69']::text[],false,'{"seq":6,"concept":"K4-2-u4-C28","difficulty":1,"kind":"ox","stem":"예상한 내용과 글의 내용이 다르면 글을 잘못 읽은 것이에요.","answer":"X","reason_options":[{"t":"읽기 중에는 예상한 내용이 맞는지 확인하는 것이고, 예상과 다를 수도 있어요.","correct":true},{"t":"예상한 내용과 글의 내용은 꼭 같아야 해요.","mis":"K4-2-u4-X69"}],"mis":"K4-2-u4-X69","explanation":["예상은 맞히기 시험이 아니에요.","읽으면서 예상이 맞는지 확인하고 다르면 바로잡아요.","『국어』 221쪽 돌 ㉱도 바른 길이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#7','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C64',1,'mc','auto','「약, 잘 쓰고 잘 버리는 방법」에서 보건소와 대부분의 약국에 비치되어 있다고 한 것은 무엇인가요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":7,"concept":"K4-2-u4-C64","difficulty":1,"kind":"mc","stem":"「약, 잘 쓰고 잘 버리는 방법」에서 보건소와 대부분의 약국에 비치되어 있다고 한 것은 무엇인가요?","options":[{"t":"폐의약품 수거함","correct":true},{"t":"항생제 자판기","mis":"K4-2-u4-X35"},{"t":"약 만드는 기계","mis":"K4-2-u4-X35"},{"t":"처방전 상자","mis":"K4-2-u4-X35"}],"explanation":["더 이상 쓰지 않는 약을 넣는 곳이에요.","보건소와 대부분의 약국에 있어요.","모은 약은 따로 버려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#8','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C58',1,'mc','auto','다음 가운데 ‘ㄻ’ 받침이 들어간 낱말이 아닌 것은 무엇인가요?',ARRAY['K4-2-u4-X56']::text[],false,'{"seq":8,"concept":"K4-2-u4-C58","difficulty":1,"kind":"mc","stem":"다음 가운데 ‘ㄻ’ 받침이 들어간 낱말이 아닌 것은 무엇인가요?","options":[{"t":"읽다","correct":true},{"t":"짊어지다","mis":"K4-2-u4-X56"},{"t":"굶다","mis":"K4-2-u4-X56"},{"t":"옮다","mis":"K4-2-u4-X56"}],"explanation":["‘ㄻ’은 ㄹ과 ㅁ이 나란히 있는 받침이에요.","짊어지다, 굶다, 옮다는 ㄻ 받침이에요.","읽다는 ㄺ 받침이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#9','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C5',2,'mc','auto','『국어』 182쪽 1번 상황 ㉮처럼 “글쓴이의 의견이 뭐지?” 하는 어려움을 겪었다면 어떤 글을 읽고 있었을까요?',ARRAY['K4-2-u4-X05']::text[],false,'{"seq":9,"concept":"K4-2-u4-C5","difficulty":2,"kind":"mc","stem":"『국어』 182쪽 1번 상황 ㉮처럼 “글쓴이의 의견이 뭐지?” 하는 어려움을 겪었다면 어떤 글을 읽고 있었을까요?","options":[{"t":"의견을 제시하는 글","correct":true},{"t":"시","mis":"K4-2-u4-X05"},{"t":"설명하는 글","mis":"K4-2-u4-X05"}],"explanation":["글쓴이의 의견을 찾고 있어요.","의견이 담긴 글은 의견을 제시하는 글이에요.","글의 종류에 따라 겪는 어려움도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#10','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C10',2,'mc','auto','『국어활동』 55쪽 「더 알아보기」에서 시에 대한 생각이나 느낌을 떠올리는 방법으로 소개하지 않은 것은 무엇인가요?',ARRAY['K4-2-u4-X14','K4-2-u4-X50','K4-2-u4-X67']::text[],false,'{"seq":10,"concept":"K4-2-u4-C10","difficulty":2,"kind":"mc","stem":"『국어활동』 55쪽 「더 알아보기」에서 시에 대한 생각이나 느낌을 떠올리는 방법으로 소개하지 않은 것은 무엇인가요?","options":[{"t":"시를 처음부터 끝까지 빨리 여러 번 읽기","correct":true},{"t":"눈을 감고 상상하기","mis":"K4-2-u4-X14"},{"t":"시 속 표현 가운데에서 마음에 드는 것을 골라 집중하기","mis":"K4-2-u4-X50"},{"t":"어떤 느낌이 들었는지 한 낱말로 표현하기","mis":"K4-2-u4-X67"}],"explanation":["눈을 감고 상상하면 장면이 떠올라요.","마음에 드는 표현에 집중하거나 느낌을 한 낱말로 나타낼 수도 있어요.","빨리 여러 번 읽는 것은 소개한 방법이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#11','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C20',2,'mc','auto','모둠에서 역할놀이로 표현할 장면을 정하기 어려울 때 할 수 있는 방법은 무엇인가요?',ARRAY['K4-2-u4-X23','K4-2-u4-X24']::text[],false,'{"seq":11,"concept":"K4-2-u4-C20","difficulty":2,"kind":"mc","stem":"모둠에서 역할놀이로 표현할 장면을 정하기 어려울 때 할 수 있는 방법은 무엇인가요?","options":[{"t":"장면 카드를 준비해 뽑는다","correct":true},{"t":"장면을 정하지 않고 아무렇게나 시작한다","mis":"K4-2-u4-X23"},{"t":"가장 웃긴 장면만 고른다","mis":"K4-2-u4-X24"}],"explanation":["장면 카드에는 이야기 속 여러 장면이 있어요.","정하기 어려우면 카드를 뽑아 정할 수 있어요.","뽑은 장면에서 인물의 말과 행동을 살려 표현해요."],"asset":{"type":"passage","lines":["① 서영이가 선물 가게에서 원하지 않는 가방을 사려는 승한이를 다그치는 장면","② 서영이와 승한이가 신호등 앞에서 다투는 장면","③ 진우가 스님과 사슴 이야기로 승한이에게 깨달음을 주는 장면","④ 진우가 서영이에게 친구 관계에 대한 조언을 하는 장면","⑤ 서영이가 소은이에게 이상한 냄새가 난다고 말하는 장면","⑥ 서영이와 승한이가 오랫동안 말없이 앉아 있는 장면"],"title":"장면 카드 — 역할놀이로 나타낼 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#12','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C30',2,'blank','auto','『국어』 202쪽 4번 표의 ㉡에 붙일 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X31']::text[],false,'{"seq":12,"concept":"K4-2-u4-C30","difficulty":2,"kind":"blank","stem":"『국어』 202쪽 4번 표의 ㉡에 붙일 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"자신이 예상한 내용이 맞는지 확인했나요?","correct":true},{"t":"더 알고 싶은 내용을 생각했나요?","mis":"K4-2-u4-X31"},{"t":"읽은 내용을 요약했나요?","mis":"K4-2-u4-X31"}],"explanation":["㉡은 읽기 중의 ‘예상한 내용 확인하기’ 칸이에요.","예상이 맞는지 확인했는지 물어요.","나머지 두 질문은 읽기 후 질문이에요."],"asset":{"type":"passage","lines":["[읽기 전] 내용 예상하기 — 제목이나 차례를 보며 내용을 예상했나요?","[읽기 전] 알고 있는 내용 떠올리기 — (     ㉠     )","[읽기 중] 예상한 내용 확인하기 — (     ㉡     )","[읽기 중] 중심 내용 파악하기 — 글의 중심 내용을 찾으며 읽었나요?","[읽기 중] 중심 생각 파악하기 — (     ㉢     )","[읽기 중] 새롭게 안 내용 파악하기 — 새롭게 안 내용을 찾으며 읽었나요?","[읽기 후] 요약하여 정리하기 — (     ㉣     )","[읽기 후] 더 알고 싶은 내용 생각하기 — 더 알고 싶은 내용을 생각했나요?"],"title":"『국어』 202쪽 4번 — 읽기 과정을 되돌아볼 수 있는 질문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#13','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C64',2,'mc','auto','「쓰레기통에 버린다고 해서 약이 사라지는 건 아니에요.」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X71']::text[],false,'{"seq":13,"concept":"K4-2-u4-C64","difficulty":2,"kind":"mc","stem":"「쓰레기통에 버린다고 해서 약이 사라지는 건 아니에요.」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"버린 약은 결국 어디론가 흘러가서 환경을 오염시킨다","correct":true},{"t":"쓰레기통에 버린 약은 곧바로 없어진다","mis":"K4-2-u4-X71"},{"t":"약은 쓰레기통에 버리는 것이 가장 좋다","mis":"K4-2-u4-X71"}],"explanation":["버린 쓰레기는 땅에 묻히거나 강으로 흘러 들어가요.","약도 사라지지 않고 환경을 오염시켜요.","그래서 폐의약품 수거함에 넣어야 해요."],"asset":{"type":"passage","lines":["(간추림) 버린 쓰레기는 땅에 묻히거나 하수구를 통해 강으로 흘러간다.","(간추림) 항생제나 성호르몬이 든 약은 생물들의 번식에 영향을 줄 수 있다.","쓰레기통에 버린다고 해서 약이 사라지는 건 아니에요.","(간추림) 과학자들은 버려진 약이 사람에게 어떤 영향을 미칠지 모른다고 경고한다."],"title":"「약, 잘 쓰고 잘 버리는 방법」 버려진 약 — 『국어』 206쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#14','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C43',2,'mc','auto','글쓴이가 글의 처음에서 내 작품을 친구가 허락 없이 사용한 상황을 상상해 보자고 한 까닭은 무엇인가요?',ARRAY['K4-2-u4-X72','K4-2-u4-X44']::text[],false,'{"seq":14,"concept":"K4-2-u4-C43","difficulty":2,"kind":"mc","stem":"글쓴이가 글의 처음에서 내 작품을 친구가 허락 없이 사용한 상황을 상상해 보자고 한 까닭은 무엇인가요?","options":[{"t":"저작권을 지켜야 하는 까닭을 읽는 사람이 자기 일처럼 느끼게 하려고","correct":true},{"t":"친구의 작품을 마음대로 써도 된다고 말하려고","mis":"K4-2-u4-X72"},{"t":"선생님께 칭찬받는 방법을 알려 주려고","mis":"K4-2-u4-X44"}],"explanation":["내 작품을 도둑맞았다고 생각하면 속상하고 불공평하겠지요.","글쓴이는 “저작권을 지켜야 하는 이유가 여기에 있습니다.”라고 했어요.","읽는 사람이 자기 일처럼 느끼게 한 거예요."],"asset":{"type":"passage","lines":["(간추림) 정성 들여 만든 내 작품을 친구가 허락 없이 써서 칭찬받는 상황을 상상해 보자.","(간추림) 시간과 정성을 도둑맞았다는 생각이 들고 불공평하다고 느낄 것이다.","저작권을 지켜야 하는 이유가 여기에 있습니다."],"title":"「저작권을 왜 지켜야 하나요?」(정문성 글) 첫째 문단 — 『국어』 212~213쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#15','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C52',2,'mc','auto','어린이 신문 읽기 활동에서 「새롭게 안 내용을 찾으며 읽었나요?」 같은 질문을 붙임쪽지에 쓰는 까닭은 무엇인가요?',ARRAY['K4-2-u4-X06','K4-2-u4-X02']::text[],false,'{"seq":15,"concept":"K4-2-u4-C52","difficulty":2,"kind":"mc","stem":"어린이 신문 읽기 활동에서 「새롭게 안 내용을 찾으며 읽었나요?」 같은 질문을 붙임쪽지에 쓰는 까닭은 무엇인가요?","options":[{"t":"질문을 바탕으로 다시 읽으며 자신의 읽기 과정을 되돌아보려고","correct":true},{"t":"붙임쪽지를 많이 붙이려고","mis":"K4-2-u4-X06"},{"t":"신문 기사를 빨리 다 읽으려고","mis":"K4-2-u4-X02"}],"explanation":["관심 있는 분야의 글을 골라 읽어요.","읽기 과정을 점검할 질문을 붙임쪽지에 써요.","그 질문으로 다시 읽으며 되돌아보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#16','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C39',2,'mc','auto','『국어활동』 56쪽 2번처럼 질문을 활용해 자신의 읽기 과정을 되돌아볼 때 알맞은 태도는 무엇인가요?',ARRAY['K4-2-u4-X11','K4-2-u4-X40']::text[],false,'{"seq":16,"concept":"K4-2-u4-C39","difficulty":2,"kind":"mc","stem":"『국어활동』 56쪽 2번처럼 질문을 활용해 자신의 읽기 과정을 되돌아볼 때 알맞은 태도는 무엇인가요?","options":[{"t":"실제로 한 대로 솔직하게 ‘예’나 ‘아니요’에 표시한다","correct":true},{"t":"친구와 똑같이 표시한다","mis":"K4-2-u4-X11"},{"t":"모두 ‘예’에 표시한다","mis":"K4-2-u4-X40"}],"explanation":["되돌아보기는 내가 어떻게 읽었는지 확인하는 것이에요.","솔직하게 표시해야 노력할 점을 찾을 수 있어요.","친구 것을 따라 하면 내 읽기를 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#17','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C59',3,'mc','auto','『국어』 186쪽 짝 대화에서 남자아이가 「기뻐의 비밀」이 재미있다고 한 까닭은 무엇인가요?',ARRAY['K4-2-u4-X65']::text[],false,'{"seq":17,"concept":"K4-2-u4-C59","difficulty":3,"kind":"mc","stem":"『국어』 186쪽 짝 대화에서 남자아이가 「기뻐의 비밀」이 재미있다고 한 까닭은 무엇인가요?","options":[{"t":"기뻐를 고무줄로 빗대어, 글자가 고무줄처럼 늘어나는 장면이 떠올라서","correct":true},{"t":"기뻐를 끊어 먹으면 눈물이 나서","mis":"K4-2-u4-X65"},{"t":"시가 길고 어려워서","mis":"K4-2-u4-X65"}],"explanation":["남자아이는 고무줄로 빗댄 표현이 재미있다고 했어요.","‘기’와 ‘뻐’를 잡고 늘이는 장면이 떠올랐대요.","마음에 드는 표현과 떠오른 장면을 함께 말했어요."],"asset":{"type":"speech","turns":[{"who":"남자아이","text":"“기뻐를 고무줄로 빗대어 표현한 게 재미있어. 글자가 고무줄처럼 늘어나는 장면이 떠올랐어.”"},{"who":"여자아이","text":"“기쁘다고 너무 뻐기다가 기뻐를 끊어 먹지 않도록 조심하라고 한 건…….”"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#18','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C61',3,'mc','auto','진우의 말 「우리 모두는 친구를 원하는 거지 논리 선생님을 구하는 건 아니니까.」에 담긴 뜻은 무엇인가요?',ARRAY['K4-2-u4-X62']::text[],false,'{"seq":18,"concept":"K4-2-u4-C61","difficulty":3,"kind":"mc","stem":"진우의 말 「우리 모두는 친구를 원하는 거지 논리 선생님을 구하는 건 아니니까.」에 담긴 뜻은 무엇인가요?","options":[{"t":"친구들은 잘못을 하나하나 짚어 고쳐 주는 사람보다 이해해 주는 친구를 좋아한다","correct":true},{"t":"친구에게는 늘 잘못을 조목조목 짚어 주어야 한다","mis":"K4-2-u4-X62"},{"t":"선생님처럼 친구를 가르치는 것이 좋은 친구다","mis":"K4-2-u4-X62"}],"explanation":["진우는 서영이가 말도 조리 있게 잘한다고 했어요.","하지만 친구들이 좋아하는 사람은 이해해 주는 친구라고 했어요.","잘못을 교정해 주는 사람을 원하는 게 아니라는 뜻이에요."],"asset":{"type":"passage","lines":["“내가 보기엔 서영이 너도 좀 문제야.”","(간추림) 친구들이 좋아하는 사람은 이해를 해 주는 친구라고 했다.","“그리고 같은 말이라도 얼마든지 다른 느낌으로 할 수 있어.”","“넌 한 번이라도 상대방의 입장이 돼서 생각하고 말해 본 적 있니?”"],"title":"「네 생각을 솔직히 말해」 진우의 조언 — 『국어』 193~194쪽"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#19','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C30',3,'match','auto','『국어』 210쪽 「이렇게 해 보세요」와 그것이 도와주는 질문을 알맞게 이으세요.','{}'::text[],false,'{"seq":19,"concept":"K4-2-u4-C30","difficulty":3,"kind":"match","stem":"『국어』 210쪽 「이렇게 해 보세요」와 그것이 도와주는 질문을 알맞게 이으세요.","pairs":[{"l":"자신이 알고 있는 약 복용법과 보관법을 떠올려 보세요.","r":"자신이 알고 있는 내용을 떠올렸나요?"},{"l":"각 문단에서 가장 중요한 문장이 무엇인지 찾으며 읽어 보세요.","r":"글의 중심 내용을 찾으며 읽었나요?"},{"l":"글을 읽으며 약에 대해 궁금했던 점을 찾아보세요.","r":"더 알고 싶은 내용을 생각했나요?"}],"mis":"K4-2-u4-X31","explanation":["‘아니요’가 나오면 「이렇게 해 보세요」를 따라 다시 해요.","알고 있는 것 떠올리기는 읽기 전 질문을 도와요.","중요한 문장 찾기와 궁금한 점 찾기는 읽기 중·후 질문을 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#20','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C37',3,'error','auto','세 친구가 중심 문장을 찾는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X37','K4-2-u4-X38','K4-2-u4-X39']::text[],false,'{"seq":20,"concept":"K4-2-u4-C37","difficulty":3,"kind":"error","stem":"세 친구가 중심 문장을 찾는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준: 문단의 첫 문장이 언제나 중심 문장이야.","correct":true,"mis_target":"K4-2-u4-X37"},{"t":"서아: 그 문장이 없으면 문단의 뜻이 통하지 않는 문장을 찾아.","mis":"K4-2-u4-X38"},{"t":"지우: 나머지 문장이 자세히 풀어 주고 있는 문장을 찾아.","mis":"K4-2-u4-X39"}],"explanation":["중심 문장은 문단의 가장 중요한 내용이에요.","첫 문장일 수도, 가운데나 끝 문장일 수도 있어요.","나머지 문장들이 무엇을 풀어 주는지 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#21','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C47',3,'mc','auto','『국어』 217쪽 자신과 연결하기 예시의 노력할 점 「글을 읽고 나서 내 생각을 글쓴이의 생각과 비교해 보지 않았다.」는 어느 과정을 되돌아본 것인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":21,"concept":"K4-2-u4-C47","difficulty":3,"kind":"mc","stem":"『국어』 217쪽 자신과 연결하기 예시의 노력할 점 「글을 읽고 나서 내 생각을 글쓴이의 생각과 비교해 보지 않았다.」는 어느 과정을 되돌아본 것인가요?","options":[{"t":"읽기 후","correct":true},{"t":"읽기 전","mis":"K4-2-u4-X30"},{"t":"읽기 중","mis":"K4-2-u4-X30"}],"explanation":["글쓴이와 내 의견을 비교하는 것은 다 읽은 뒤에 해요.","『국어』 215쪽에서도 읽기 후 질문이었어요.","그래서 읽기 후를 되돌아본 것이에요."],"asset":{"type":"passage","lines":["잘한 점 — 제목을 보고 저작권을 지켜야 하는 까닭을 쓴 글일 것이라고 예상했다.","노력할 점 — 글을 읽고 나서 내 생각을 글쓴이의 생각과 비교해 보지 않았다."],"title":"『국어』 217쪽 자신과 연결하기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#22','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C4',3,'mc','auto','읽기 과정을 되돌아보는 질문을 떠올리기 어려울 때 할 수 있는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X02','K4-2-u4-X11']::text[],false,'{"seq":22,"concept":"K4-2-u4-C4","difficulty":3,"kind":"mc","stem":"읽기 과정을 되돌아보는 질문을 떠올리기 어려울 때 할 수 있는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"글을 읽으며 어떤 생각을 했는지 말해 보고, 그 생각을 질문과 연결한다","correct":true},{"t":"질문하지 않고 글을 빨리 다시 읽기만 한다","mis":"K4-2-u4-X02"},{"t":"친구가 만든 질문을 그대로 베낀다","mis":"K4-2-u4-X11"}],"explanation":["읽는 동안 떠오른 생각을 먼저 말하거나 써 보아요.","그 생각을 질문으로 바꾸어 보아요.","예: “이 말이 무슨 뜻이지?” → 「모르는 낱말의 뜻을 찾으며 읽었나요?」"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#23','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C7',4,'essay','teacher','시 「운명 교향곡」의 두 줄을 듣고 떠오르는 장면이나 경험을 쓰세요. 직접 겪은 일이 아니어도 책이나 텔레비전에서 본 일을 떠올려도 좋아요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u4-C7","difficulty":4,"kind":"essay","stem":"시 「운명 교향곡」의 두 줄을 듣고 떠오르는 장면이나 경험을 쓰세요. 직접 겪은 일이 아니어도 책이나 텔레비전에서 본 일을 떠올려도 좋아요.","answer_guide":{"answer":"예: 아침에 알람을 끄고 “오 분만 더.” 하고 눈을 감았다가 일어나 보니 삼십 분이 지나 있던 일이 떠올랐다. 그때 너무 놀라서 허둥지둥 가방을 챙겼다. 시의 말하는 이도 나처럼 깜짝 놀랐을 것 같다.","scoring_points":["시를 듣고 떠오른 장면이나 경험을 썼는가","시의 내용과 이어지는 경험인가","그때의 생각이나 느낌을 함께 썼는가"]},"explanation":["시를 듣고 떠오르는 장면을 자유롭게 떠올려요.","직접 겪은 일뿐 아니라 책이나 영상에서 본 일도 경험이 돼요.","떠오른 경험과 느낌을 함께 써요."],"asset":{"type":"passage","lines":["분명히 여덟 시에 일어났는데","눈 한 번 감았다가 다시 떴는데","(간추림) 아홉 시가 되어 지각이라며 꿈이면 좋겠다고 외친다."],"title":"시 「운명 교향곡」(신민규 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#24','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C48',4,'essay','teacher','「저작권을 왜 지켜야 하나요?」를 다시 읽는다고 생각하고, 읽기 전·중·후에 활용할 질문을 하나씩 쓰고 그 질문에 대한 자신의 답을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u4-C48","difficulty":4,"kind":"essay","stem":"「저작권을 왜 지켜야 하나요?」를 다시 읽는다고 생각하고, 읽기 전·중·후에 활용할 질문을 하나씩 쓰고 그 질문에 대한 자신의 답을 쓰세요.","answer_guide":{"answer":"예: 읽기 전 — 「제목을 보고 어떤 내용일지 예상했나요?」 → 저작권을 지켜야 하는 까닭이 나올 것이라고 예상했다. / 읽기 중 — 「의견에 대한 이유가 적절한지 살피며 읽었나요?」 → 문화 수준이 낮아진다는 이유가 의견과 잘 이어졌다. / 읽기 후 — 「글쓴이와 자신의 의견을 비교하여 정리했나요?」 → 나도 글쓴이처럼 허락을 받고 써야 한다고 생각한다.","scoring_points":["읽기 전·중·후 질문을 하나씩 썼는가","의견을 제시하는 글에 알맞은 질문인가","각 질문에 대한 자신의 답을 썼는가"]},"explanation":["의견을 제시하는 글은 의견과 이유를 살피는 질문이 필요해요.","『국어』 215~216쪽 질문을 떠올려요.","질문에 솔직하게 답하며 되돌아보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g4_2_kor_u4_review_d#25','kor',4,2,'u4','','tb_g4_2_kor_u4_review_d','unit_review','K4-2-u4-C50',4,'essay','teacher','「마음먹기」와 「기뻐의 비밀」 가운데 한 편을 골라, 그 시에 대한 생각이나 느낌을 즉흥극·그림·편지·노래 가운데 한 가지 방법으로 어떻게 나타낼지 쓰고, 발표한 뒤 친구들에게 받고 싶은 질문을 하나 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u4-C50","difficulty":4,"kind":"essay","stem":"「마음먹기」와 「기뻐의 비밀」 가운데 한 편을 골라, 그 시에 대한 생각이나 느낌을 즉흥극·그림·편지·노래 가운데 한 가지 방법으로 어떻게 나타낼지 쓰고, 발표한 뒤 친구들에게 받고 싶은 질문을 하나 쓰세요.","answer_guide":{"answer":"예: 「기뻐의 비밀」을 즉흥극으로 나타내겠다. 두 친구가 ‘기’와 ‘뻐’ 글자 판을 들고 양쪽으로 멀어지며 “기이이이…뻐!” 하고 외치다가, 너무 멀어지면 “따끔!” 하고 주저앉는다. 받고 싶은 질문 — “왜 끊어지는 장면을 넣었나요?”","scoring_points":["한 편의 시를 고르고 나타낼 방법을 정했는가","나타낼 내용이 시에 대한 생각이나 느낌과 이어지는가","발표 뒤 받고 싶은 질문을 썼는가"]},"explanation":["보기의 방법 가운데 내 느낌을 잘 드러낼 방법을 골라요.","시의 어느 부분을 어떻게 나타낼지 구체적으로 써요.","발표한 뒤 친구들의 질문과 칭찬을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
